function setAuthMode(m){
  authMode=m;
  $('#authTitle').textContent=m==='login'?'Log in':'Create account';
  $('#authSubmit').textContent=m==='login'?'Log in':'Create account';
  $('#authToggle').textContent=m==='login'?'New to VendorFlow? Create an account':'Already have an account? Log in';
  m==='signup'?show($('#name')):hide($('#name'));
  hide($('#authError'));
}

$('#authToggle').onclick=()=>setAuthMode(authMode==='login'?'signup':'login');

$('#authSubmit').onclick=async()=>{
  try{
    hide($('#authError'));
    if(authMode==='signup'){
      let n=$('#name').value.trim();
      if(!n)throw Error('Enter your name.');
      let r=await createUserWithEmailAndPassword(auth,$('#email').value.trim(),$('#password').value);
      await updateProfile(r.user,{displayName:n});
    }else{
      await signInWithEmailAndPassword(auth,$('#email').value.trim(),$('#password').value);
    }
  }catch(e){
    $('#authError').textContent=e.message;
    show($('#authError'));
  }
};

$('#logout').onclick=()=>signOut(auth);


/*
 * Business-info setup can't be skipped to a dashboard (there isn't
 * one yet -- onboardingComplete gates app access), but a vendor can
 * still save their progress and pick this back up later instead of
 * losing everything typed so far. Mirrors the "Run Setup Wizard
 * Later" pattern used by the classes/certificates/payments wizard.
 */
$('#onboardLogout').onclick=async()=>{

  if(questions[step]){
    answers[questions[step][0]]=$('#answer')?.value.trim()||'';
  }

  try{

    await setDoc(
      vendorDoc(),
      {
        ...answers,
        email:user?.email||'',
        lastOnboardingStep:step,
        updatedAt:serverTimestamp()
      },
      {merge:true}
    );

  }catch(err){
    /*
     * Even if the save fails (offline, etc.), still let the vendor
     * sign out rather than trapping them on this screen.
     */
  }

  toast("You're logged out. Your progress was saved -- log back in anytime to pick up where you left off.");

  await signOut(auth);
};

let vfAuthStateGeneration=0;

onAuthStateChanged(auth,async u=>{
  const vfThisAuthGeneration=++vfAuthStateGeneration;

  hide($('#loading'));
  hide($('#auth'));
  hide($('#onboarding'));
  hide($('#app'));
  hide($('#vfPaywallGate'));
  hide($('#vfSubscriptionActivating'));

  if(!u){
    const vfWasSignedIn=!!user;

    user=null;

    /*
     * inboundEmailPromise is a module-level cache. Without clearing
     * it on sign-out, a second account signing in on the same
     * browser tab (no full page reload) could inherit the previous
     * vendor's cached "creating the address" promise -- and even
     * once resolved, would never re-fetch this account's own actual
     * address. Same family of bug as the wizard-step localStorage
     * leak fixed earlier: state that outlives the signed-in user.
     */
    inboundEmailPromise=null;

    show($('#auth'));

    /*
     * Only announce this for a genuine mid-session drop -- not the
     * very first page load, where `user` was never set to begin
     * with and showing this toast would be confusing noise on every
     * normal visit to the login screen.
     */
    if(vfWasSignedIn){
      toast('You were signed out -- please log back in.');
    }

    return;
  }

  user=u;
  let s=await getDoc(vendorDoc());

  /*
   * Auth state can fire more than once in quick succession (a token
   * refresh right after sign-in, for example). If a newer event has
   * already started, let it own the screen instead of this stale one
   * showing onboarding and the app dashboard at the same time.
   */
  if(vfThisAuthGeneration!==vfAuthStateGeneration)return;

  if(!s.exists()||!s.data().onboardingComplete){
    profile=s.exists()?s.data():{};
    answers={...profile,ownerName:profile.ownerName||u.displayName||''};
    step=Math.max(
      0,
      Math.min(
        questions.length-1,
        Number(profile.lastOnboardingStep||0)
      )
    );
    renderQuestion();
    hide($('#app'));
    show($('#onboarding'));
  }else{
    profile=s.data();
    hide($('#onboarding'));
    await vfEnforceBillingGate();
  }
});

/*
 * Safety net for a signed-out session that the UI hasn't visibly
 * caught up to yet (see the write-up above onAuthStateChanged). Only
 * ever shown once per page load -- a vendor who dismisses it and
 * reloads either lands back on the login screen (if they really were
 * signed out) or resumes normally (if this was a one-off hiccup).
 */
let vfSessionExpiredPromptShown=false;

function vfShowSessionExpiredPrompt(){

  if(vfSessionExpiredPromptShown){
    return;
  }

  vfSessionExpiredPromptShown=true;

  const overlay=document.createElement('div');
  overlay.id='vfSessionExpiredOverlay';
  overlay.className='vf-modal-overlay';
  overlay.style.zIndex='250000';

  overlay.innerHTML=`
    <div class="vf-modal-card">
      <div class="eyebrow">Session ended</div>
      <h2>You've been signed out</h2>
      <p>
        Your VendorFlow session ended -- nothing you were working on
        was lost. Log back in to keep going.
      </p>
      <button
        type="button"
        id="vfSessionExpiredReload"
        class="primary">
        Log back in
      </button>
    </div>
  `;

  document.body.appendChild(overlay);

  $('#vfSessionExpiredReload').onclick=()=>{
    location.reload();
  };
}

window.addEventListener('unhandledrejection',event=>{

  if(auth.currentUser){
    return;
  }

  const appEl=$('#app');

  if(!appEl || appEl.classList.contains('hidden')){
    return;
  }

  const reason=event?.reason;
  const message=String(reason?.message||reason||'');

  if(!/reading 'uid'|null is not an object|cannot read propert/i.test(message)){
    return;
  }

  event.preventDefault();
  vfShowSessionExpiredPrompt();
});


/*
 * Billing launch cutover: any vendor whose Firebase Auth account was
 * created before this moment is grandfathered in as free forever (Tim's
 * explicit decision) -- they never see a paywall, no Stripe involvement
 * needed for them at all. Anyone whose account is created from this
 * moment on must have an active or trialing Stripe subscription to get
 * past this gate.
 */
const VF_BILLING_LAUNCH_AT=new Date('2026-09-04T23:40:00Z').getTime();

function vfHasBillingAccess(p,authUser){

  const createdAtMs=Date.parse(authUser?.metadata?.creationTime||'')||0;
  if(createdAtMs && createdAtMs<VF_BILLING_LAUNCH_AT)return true;

  /*
   * A free account granted from the admin console.
   *
   * Checked BEFORE subscriptionStatus, and deliberately kept in its
   * own field: Stripe's webhook overwrites subscriptionStatus on
   * every subscription event, so a free account faked by writing
   * 'active' there would revert the moment Stripe mentioned that
   * customer. Nothing in the billing flow touches this field.
   */
  if(p?.complimentaryAccess===true)return true;

  const status=p?.subscriptionStatus;
  return status==='trialing'||status==='active';
}

function vfSubscribeUrl(){
  return 'https://myvendorflow.com/subscribe/';
}

async function vfEnforceBillingGate(){
  if(vfHasBillingAccess(profile,user)){
    await enterApp();
    return;
  }

  const cameFromCheckout=
    new URLSearchParams(window.location.search).get('checkout')==='success';

  if(!cameFromCheckout){
    hide($('#app'));
    show($('#vfPaywallGate'));
    return;
  }

  hide($('#app'));
  show($('#vfSubscriptionActivating'));
  hide($('#vfSubscriptionActivatingRetry'));

  for(let attempt=0;attempt<10;attempt++){
    await new Promise(r=>setTimeout(r,1500));
    const s=await getDoc(vendorDoc());
    profile=s.exists()?s.data():profile;
    if(vfHasBillingAccess(profile,user)){
      hide($('#vfSubscriptionActivating'));
      await enterApp();
      return;
    }
  }

  show($('#vfSubscriptionActivatingRetry'));
}

$('#vfPaywallStartTrial').onclick=()=>{
  window.location.href=vfSubscribeUrl();
};

$('#vfPaywallSignOut').onclick=async()=>{
  await signOut(auth);
};

$('#vfSubscriptionActivatingCheckAgain').onclick=async()=>{
  hide($('#vfSubscriptionActivatingRetry'));
  await vfEnforceBillingGate();
};

function renderQuestion(){
  let[k,q,h]=questions[step];

  $('#progressBar').style.width=`${(step+1)/questions.length*100}%`;
  $('#backBtn').disabled=step===0;
  $('#nextBtn').textContent=step===questions.length-1?'Finish setup':'Next';

  $('#questionBox').innerHTML=
    `<div class="eyebrow">Step ${step+1} of ${questions.length+VF_WIZARD_STEPS.length}</div>
     <h2>${q}</h2>
     <p>${h}</p>
     ${
       ['locations','schools'].includes(k)
       ? `<textarea id="answer" class="input" rows="5">${esc(answers[k]||'')}</textarea>`
       : `<input id="answer" class="input" value="${esc(answers[k]||'')}">`
     }`;
}

$('#backBtn').onclick=()=>{
  if(step){
    answers[questions[step][0]]=$('#answer').value.trim();
    step--;
    renderQuestion();
  }
};

$('#nextBtn').onclick=async()=>{
  let k=questions[step][0];
  answers[k]=$('#answer').value.trim();

  if(['businessName','ownerName'].includes(k)&&!answers[k]){
    toast('Please answer this one first.');
    return;
  }

  if(step<questions.length-1){
    step++;
    renderQuestion();
    return;
  }

  profile={
    ...answers,
    email:user.email,
    onboardingComplete:true,
    updatedAt:serverTimestamp()
  };

  await setDoc(vendorDoc(),profile,{merge:true});
  await log('Business setup completed',`${profile.businessName} workspace created.`,'Onboarding');

  hide($('#onboarding'));

  await enterApp();

  /*
   * A vendor finishing setup should always arrive at
   * the Dashboard, where VendorFlow gives next-step guidance.
   */
  switchView('review');
};

async function enterApp(){
  show($('#app'));
  $('#bizNameSide').textContent=profile.businessName||'VendorFlow';
  $('#userEmail').textContent=user.email||'';
  fillProfile();
  await refreshAll();

  /*
   * The Email Inbox sidebar badge is only ever set inside
   * renderInboundInbox(), which only ever ran after visiting the
   * Email Inbox tab itself -- refreshAll() above never touches
   * inbound email data. So the badge sat stuck on whatever's
   * hardcoded in index.html ("0") for the entire session until the
   * vendor happened to click into Email Inbox, at which point it
   * would finally show the real count -- Tim saw this as "shows a
   * zero and then when you click it there is an email there."
   * Loading it once here at startup, same as refreshAll() above,
   * keeps the badge accurate from the moment the app opens.
   */
  if(typeof loadInboundInbox==='function'){
    loadInboundInbox();
  }

  switchView('review');

  /*
   * Runs before the first render so a vendor who has been ticking
   * items off in this browser keeps that progress the first time
   * they sign in after the checklist moved to the account.
   */
  if(typeof vfSetupMigrateLocalState==='function'){
    await vfSetupMigrateLocalState();
  }

  if(typeof vfRenderWizardNudge==='function')vfRenderWizardNudge();
  if(typeof vfRenderReadySetupButton==='function')vfRenderReadySetupButton();
  if(typeof vfSetupClearSnooze==='function')vfSetupClearSnooze();
  if(typeof vfRenderSetupChecklist==='function')vfRenderSetupChecklist();
}

async function log(
  action,
  detail,
  source='Manual',
  evidence=null
){

  const data={
    action,
    detail,
    source,

    createdAt:
      serverTimestamp()
  };


  if(
    evidence &&
    typeof evidence==='object'
  ){

    data.evidence={
      ...evidence
    };
  }


  await addDoc(
    sub('history'),
    data
  );
}

async function getList(name,ordered=true){
  let c=sub(name);
  let q=ordered?query(c,orderBy('createdAt','desc')):c;
  let s=await getDocs(q);
  return s.docs.map(d=>({id:d.id,...d.data()}));
}


function paymentReviewKey(
  studentId,
  method,
  date,
  amount
){

  return [
    String(studentId||'').trim(),
    String(method||'').trim().toLowerCase(),
    String(date||'').trim(),
    Math.round(
      Number(amount||0)*100
    )
  ].join('|');
}


async function cleanupLegacyPaymentDuplicateReviews(){

  /*
   * Older inbound-payment code created a generic review record:
   *
   *   reviewType: payment
   *
   * The corrected system creates:
   *
   *   reviewType: duplicate
   *   itemType: payment
   *   incoming: {...}
   *
   * Remove an old record ONLY when an exact matching corrected
   * duplicate review already exists. This prevents deleting a
   * legitimate unrelated Needs Review item.
   */

  const properDuplicates=
    reviews.filter(
      review=>
        review.reviewType==='duplicate' &&
        review.itemType==='payment'
    );


  const legacy=
    reviews.filter(
      review=>
        review.reviewType==='payment' &&
        review.itemType==='payment'
    );


  if(
    !properDuplicates.length ||
    !legacy.length
  ){
    return 0;
  }


  const properKeys=
    new Set(
      properDuplicates.map(review=>{

        const incoming=
          review.incoming||{};

        return paymentReviewKey(
          incoming.studentId,
          incoming.method,
          incoming.date,
          incoming.amount
        );
      })
    );


  const stale=
    legacy.filter(
      review=>
        properKeys.has(
          paymentReviewKey(
            review.studentId,
            review.method,
            review.date,
            review.amount
          )
        )
    );


  for(const review of stale){

    await deleteDoc(
      doc(
        db,
        'vendors',
        user.uid,
        'review',
        review.id
      )
    );
  }


  return stale.length;
}



function certificateAttentionIssue(cert){

  if(
    !cert ||
    cert.deleted
  ){
    return null;
  }


  if(!cert.studentId){

    if(cert.dismissedMatchWarning){
      return null;
    }

    return {
      code:'missing-student',
      title:'Certificate needs a matching student',
      detail:
        `${cert.student||'This certificate'} — ${money(cert.amount)} — `+
        `no student account matches this name yet. Add the student, then come back and match this certificate to them.`
    };
  }


  if(!cert.charterSchoolId){

    return {
      code:'missing-charter',
      title:'Certificate needs a charter school',
      detail:
        `${cert.student||'Student'} — ${money(cert.amount)} — `+
        `attach the correct charter school so VendorFlow can schedule the invoice.`
    };
  }


  if(!cert.serviceStartDate){

    return {
      code:'missing-service-dates',
      title:'Certificate needs service dates',
      detail:
        `${cert.student||'Student'} — ${money(cert.amount)} — `+
        `enter the service start date so VendorFlow can calculate when the invoice should be created.`
    };
  }


  if(!cert.invoiceScheduleValid){

    return {
      code:'missing-invoice-schedule',
      title:'Certificate invoice schedule needs attention',
      detail:
        `${cert.student||'Student'} — ${money(cert.amount)} — `+
        `review the charter and service start date so VendorFlow can schedule the invoice.`
    };
  }


  return null;
}



function invoiceNumberingReviewItems(){

  if(profile.invoiceNumberMode){
    return [];
  }


  return invoiceReadyCertificates()
    .map(cert=>({

      id:
        `invoice-numbering-${cert.id}`,

      reviewType:
        'invoice-numbering',

      itemType:
        'invoice',

      certificateId:
        cert.id,

      title:
        'Invoice cannot be prepared yet',

      detail:
        `${cert.student||'Student'} — ${money(cert.amount)} — `+
        `this certificate has reached its invoice date, but VendorFlow cannot prepare the invoice until you choose an invoice numbering system.`,

      source:
        'VendorFlow'
    }));
}


function overdueInvoiceNotificationItems(){

  const settings=
    profile.overdueInvoiceSettings ||
    defaultOverdueInvoiceSettings();

  const today=
    new Date();

  today.setHours(0,0,0,0);

  return invoices
    .filter(invoice=>
      invoiceStatus(invoice)==='Sent'
    )
    .map(invoice=>{

      const dueDateRaw=
        invoice.dueDate ||
        invoiceDueDateForTerms(
          invoice.invoiceDate,
          invoice.paymentTermsDays
        );

      const dueDate=
        parseVendorDate(dueDateRaw);

      if(!dueDate){
        return null;
      }

      const graceDeadline=
        new Date(
          dueDate.getFullYear(),
          dueDate.getMonth(),
          dueDate.getDate() +
            Number(settings.graceDays||0),
          12,
          0,
          0
        );

      if(graceDeadline>today){
        return null;
      }

      const dismissedUntil=
        invoice.overdueReminder?.dismissedUntil
          ? parseVendorDate(
              invoice.overdueReminder.dismissedUntil
            )
          : null;

      if(
        dismissedUntil &&
        dismissedUntil>today
      ){
        return null;
      }

      const daysOverdue=
        Math.max(
          0,
          Math.round(
            (today-dueDate) /
            (1000*60*60*24)
          )
        );

      return {

        id:
          `overdue-invoice-${invoice.id}`,

        reviewType:
          'overdue-invoice',

        itemType:
          'invoice',

        invoiceId:
          invoice.id,

        title:
          `Overdue: Invoice ${invoice.invoiceNumber||''}`,

        detail:
          `${invoice.charterSchoolName||'Charter school'} — ${money(invoice.amount)} — `+
          `${daysOverdue} day${daysOverdue===1?'':'s'} past due (due ${invoiceLedgerDate(dueDateRaw)}).`,

        source:
          'VendorFlow'
      };
    })
    .filter(Boolean);
}


function todoNotificationItems(){

  const today=
    new Date();

  today.setHours(0,0,0,0);

  return compliance
    .filter(task=>{

      const status=
        String(
          task.status || ''
        ).toLowerCase();

      if(
        status==='complete' ||
        status==='approved' ||
        status==='archived' ||
        task.archived===true
      ){
        return false;
      }

      const due=
        task.due
          ? new Date(`${task.due}T00:00:00`)
          : null;

      const reminder=
        task.reminderDate
          ? new Date(`${task.reminderDate}T00:00:00`)
          : null;

      const sevenDays=
        new Date(today);

      sevenDays.setDate(
        sevenDays.getDate()+7
      );

      return (
        reminder &&
        !Number.isNaN(reminder.getTime()) &&
        reminder<=today
      ) || (
        due &&
        !Number.isNaN(due.getTime()) &&
        due<=sevenDays
      );
    })
    .map(task=>{

      const due=
        task.due
          ? new Date(`${task.due}T00:00:00`)
          : null;

      const overdue=
        due &&
        !Number.isNaN(due.getTime()) &&
        due<today;

      return {
        id:
          `todo-notification-${task.id}`,
        reviewType:
          'todo-reminder',
        itemType:
          'todo',
        todoId:
          task.id,
        title:
          overdue
            ? `Overdue: ${task.task || 'To-do item'}`
            : `Reminder: ${task.task || 'To-do item'}`,
        detail:[
          task.school || '',
          task.due
            ? `Due ${task.due}`
            : '',
          task.notes || ''
        ].filter(Boolean).join(' — '),
        source:
          'To-do List'
      };
    });
}


function allNeedsReviewItems(){

  return [
    ...reviews,
    ...todoNotificationItems(),
    ...invoiceNumberingReviewItems(),
    ...overdueInvoiceNotificationItems()
  ];
}


function certificateAttentionReviews(){

  return certs
    .map(cert=>{

      const issue=
        certificateAttentionIssue(
          cert
        );

      if(!issue){
        return null;
      }


      return {
        id:
          `certificate-attention-${cert.id}`,

        reviewType:
          'certificate-attention',

        itemType:
          'certificate',

        certificateId:
          cert.id,

        title:
          issue.title,

        detail:
          issue.detail,

        issueCode:
          issue.code,

        student:
          cert.student||'',

        amount:
          Number(cert.amount||0),

        number:
          cert.number||'',

        source:
          'VendorFlow'
      };
    })
    .filter(Boolean);
}


function paymentAttentionIssue(payment){

  if(
    !payment ||
    payment.deleted ||
    payment.studentId ||
    payment.dismissedMatchWarning
  ){
    return null;
  }

  return {
    code:'missing-student',
    title:'Payment needs a matching student',
    detail:
      `${payment.payer||payment.student||'This payment'} — ${money(payment.amount)} — `+
      `no student account matches this name yet. Add the student, then come back and match this payment to them.`
  };
}


function paymentAttentionReviews(){

  return payments
    .map(payment=>{

      const issue=
        paymentAttentionIssue(payment);

      if(!issue){
        return null;
      }

      return {
        id:
          `payment-attention-${payment.id}`,

        reviewType:
          'payment-attention',

        itemType:
          'payment',

        paymentId:
          payment.id,

        title:
          issue.title,

        detail:
          issue.detail,

        issueCode:
          issue.code,

        student:
          payment.payer||payment.student||'',

        amount:
          Number(payment.amount||0),

        source:
          'VendorFlow'
      };
    })
    .filter(Boolean);
}


async function refreshAll(){
  classes=await getList('classes',false);

  await repairRosterCoreLinksOnce();

  /*
   * These collections don't depend on each other, so fetching them
   * all at once instead of one at a time cuts most of the page's
   * load time -- this was the main reason VendorFlow felt slow to
   * open. Nothing about what gets loaded or in what order the rest
   * of this function runs has changed, only how these particular
   * reads are dispatched.
   */
  const [
    studentsResult,
    servicesResult,
    obligationsResult,
    charterSchoolsResult,
    paymentsResult,
    expensesResult,
    incomeResult,
    recurrencesResult,
    ignoredPayerVendorSnap
  ]=await Promise.all([
    getList('students',false),
    getList('services',false),
    getList('obligations',false),
    getList('charterSchools',false),
    getList('payments'),
    getList('expenses'),
    getList('income'),
    getList('recurrences',false),
    getDoc(vendorDoc())
  ]);

  students=studentsResult;
  services=servicesResult;
  obligations=obligationsResult;
  charterSchools=charterSchoolsResult;
  payments=paymentsResult;
  expenses=expensesResult;
  income=incomeResult;
  recurrences=recurrencesResult;

  const ignoredPayerVendorData=
    ignoredPayerVendorSnap.exists()
      ? ignoredPayerVendorSnap.data()
      : {};

  ignoredStatementPayers=
    Array.isArray(
      ignoredPayerVendorData
        .ignoredStatementPayers
    )
      ? ignoredPayerVendorData
          .ignoredStatementPayers
          .filter(
            rule=>
              rule &&
              rule.payerKey
          )
      : [];

  [certs,invoices]=await Promise.all([
    getList('certificates'),
    getList('invoices')
  ]);

  const createdInvoices=
    await createDueInvoices();

  if(createdInvoices>0){
    [invoices,certs]=await Promise.all([
      getList('invoices'),
      getList('certificates')
    ]);
  }

  [compliance,reviews,vaultFiles]=await Promise.all([
    getList('compliance'),
    getList('review'),
    getList('vaultFiles')
  ]);

  const removedLegacyReviews=
    await cleanupLegacyPaymentDuplicateReviews();

  if(removedLegacyReviews>0){
    reviews=await getList('review');
  }


  /*
   * Certificate operational issues are derived directly
   * from the certificate records. This makes them impossible
   * to forget and lets them clear automatically when fixed.
   */
  reviews=[
    ...reviews,
    ...certificateAttentionReviews(),
    ...paymentAttentionReviews()
  ];


  history=await getList('history');

  const repaired=
    await repairUnmatchedPayments();

  if(repaired>0){
    [payments,history]=await Promise.all([
      getList('payments'),
      getList('history')
    ]);
  }


  /*
   * Reconcile all currently known parent-payment and
   * certificate funding against dated obligations.
   *
   * This is idempotent: it calculates what the records
   * SHOULD look like and only writes actual differences.
   */
  const obligationChanges=
    await reconcileObligationFunding();

  if(obligationChanges>0){
    obligations=
      await getList(
        'obligations',
        false
      );
  }


  const queuedPaymentReminders=
    await queuePaymentReminderReviews();

  if(queuedPaymentReminders>0){
    reviews=await getList('review');
  }


  const chargedLateFees=
    await applyLateFees();

  if(chargedLateFees>0){
    obligations=await getList('obligations',false);
  }


  const queuedLateFeeApprovals=
    await queueLateFeeChargeApprovals();


  const queuedLateFeeNotices=
    await queueLateFeeChargedReviews();

  const queuedLateFeeRemovedNotices=
    await queueLateFeeRemovedReviews();

  const queuedFollowupReminders=
    await queueRecurringPaymentReminders();

  if(
    queuedLateFeeApprovals>0 ||
    queuedLateFeeNotices>0 ||
    queuedLateFeeRemovedNotices>0 ||
    queuedFollowupReminders>0
  ){
    reviews=await getList('review');
  }


  renderAll();
}


async function repairRosterCoreLinksOnce(){

  const vendorSnap=
    await getDoc(
      vendorDoc()
    );

  const vendorData=
    vendorSnap.exists()
      ? vendorSnap.data()
      : {};

  if(
    vendorData.rosterCoreBackfillV1
  ){
    return false;
  }


  for(const c of classes){

    const snap=
      await getDocs(
        collection(
          db,
          'vendors',
          user.uid,
          'classes',
          c.id,
          'students'
        )
      );

    const rows=
      snap.docs.map(
        d=>({
          id:d.id,
          ...d.data()
        })
      );

    if(rows.length){

      await syncRosterToCoreRecords(
        c,
        rows
      );
    }
  }


  await setDoc(
    vendorDoc(),
    {
      rosterCoreBackfillV1:true,
      rosterCoreBackfillAt:
        serverTimestamp()
    },
    {
      merge:true
    }
  );


  await log(
    'Roster accounts synchronized',
    'Existing group roster students were linked to Students & Services.',
    'VendorFlow'
  );


  return true;
}


