function vendorAddressParts(){

  let city=
    String(profile.city||'').trim();

  let state=
    String(profile.state||'').trim();

  let zip=
    String(profile.zip||'').trim();


  /*
   * Older onboarding stored these together as:
   * "Encinitas, CA 92024"
   */
  const legacy=
    String(profile.cityStateZip||'').trim();


  if(
    legacy &&
    (!city || !state || !zip)
  ){

    const match=
      legacy.match(
        /^(.+?),\s*([A-Za-z]{2})\s+(.+)$/
      );


    if(match){

      if(!city){
        city=match[1].trim();
      }

      if(!state){
        state=match[2].trim();
      }

      if(!zip){
        zip=match[3].trim();
      }

    }else if(!city){

      city=legacy;
    }
  }


  return {
    street:
      String(profile.address||'').trim(),

    city,
    state,
    zip
  };
}



function renderInboundVendorEmail(){

  const el=
    $('#accountInboundEmail');

  if(!el){
    return;
  }


  el.textContent=
    profile.inboundEmail ||
    'Creating your address...';


  const copy=
    $('#copyInboundEmail');


  if(copy){

    copy.disabled=
      !profile.inboundEmail;


    copy.onclick=
      async()=>{

        if(!profile.inboundEmail){
          return;
        }


        try{

          await navigator.clipboard.writeText(
            profile.inboundEmail
          );

          const old=
            copy.textContent;

          copy.textContent=
            'Copied';

          setTimeout(
            ()=>{
              copy.textContent=
                old;
            },
            1200
          );


        }catch{

          prompt(
            'Copy your VendorFlow email address:',
            profile.inboundEmail
          );
        }
      };
  }
}


/*
 * Runs the address creation attempt and, on failure, shows a clear
 * error plus a "Try again" button instead of leaving the Account
 * page stuck on "Creating your address..." with no way forward.
 */
async function vfAttemptInboundVendorEmail(){

  const retryButton=
    $('#retryInboundEmail');

  if(retryButton){
    hide(retryButton);
  }

  try{

    await ensureInboundVendorEmail();

  }catch(error){

    console.error(
      'VendorFlow inbound email:',
      error
    );

    const el=
      $('#accountInboundEmail');

    if(el){
      el.textContent=
        error?.message ||
        'Could not create address.';
    }

    if(retryButton){
      show(retryButton);
    }
  }
}


if($('#retryInboundEmail')){

  $('#retryInboundEmail').onclick=()=>{

    /*
     * The failed attempt already reset inboundEmailPromise to null
     * inside ensureInboundVendorEmail()'s own catch block, so a
     * fresh call here genuinely retries instead of returning the
     * same rejected promise.
     */
    renderInboundVendorEmail();
    vfAttemptInboundVendorEmail();
  };
}


/*
 * The only way back to a setup checklist the vendor removed. The
 * header nudge used to do this job; the checklist floats on its own
 * now, so this lives somewhere permanent instead.
 */
if($('#vfShowSetupChecklist')){

  $('#vfShowSetupChecklist').onclick=()=>{

    if(typeof vfReopenSetupChecklist==='function'){
      vfReopenSetupChecklist();
      toast('Setup checklist is back, bottom right.');
    }
  };
}


async function ensureInboundVendorEmail(){

  if(!user){
    return;
  }


  if(inboundEmailPromise){
    return inboundEmailPromise;
  }


  inboundEmailPromise=
    (async()=>{

      const token=
        await user.getIdToken();


      /*
       * Without a timeout, a request that never resolves or rejects
       * (a dropped connection, a Worker that hangs) leaves the
       * Account page stuck on "Creating your address..." forever,
       * with no error and no way to retry short of a full reload.
       */
      const timeoutController=
        new AbortController();

      const timeoutId=
        setTimeout(
          ()=>timeoutController.abort(),
          20000
        );

      let response;

      try{

        response=
          await fetch(
            `${VENDORFLOW_API}/inbound/address`,
            {
              method:'POST',

              signal:
                timeoutController.signal,

              headers:{
                Authorization:
                  `Bearer ${token}`,

                'Content-Type':
                  'application/json'
              },

              body:
                JSON.stringify({
                  businessName:
                  profile.businessName ||
                  profile.ownerName ||
                  'vendor'
              })
          }
        );

      }catch(fetchError){

        if(fetchError?.name==='AbortError'){

          throw new Error(
            'VendorFlow could not create your email address in time. Please try again.'
          );
        }

        throw fetchError;

      }finally{

        clearTimeout(timeoutId);
      }


      let data={};


      try{

        data=
          await response.json();

      }catch{}


      if(
        !response.ok ||
        !data.email
      ){

        throw new Error(
          data.detail ||
          data.error ||
          'VendorFlow email address could not be created.'
        );
      }


      const email=
        String(
          data.email
        ).trim();


      if(
        profile.inboundEmail !==
        email
      ){

        profile.inboundEmail=
          email;


        await setDoc(
          vendorDoc(),
          {
            inboundEmail:
              email,

            updatedAt:
              serverTimestamp()
          },
          {
            merge:true
          }
        );
      }


      renderInboundVendorEmail();


      return email;
    })();


  try{

    return await inboundEmailPromise;

  }catch(error){

    inboundEmailPromise=null;

    throw error;
  }
}


function renderAccountPage(){

  renderInboundVendorEmail();
  vfAttemptInboundVendorEmail();


  const subscription=
    profile.subscriptionLevel ||
    profile.subscription ||
    'VendorFlow Beta';


  const address=
    vendorAddressParts();


  const subscriptionEl=
    $('#accountSubscription');

  const emailEl=
    $('#accountEmail');


  if(subscriptionEl){
    subscriptionEl.textContent=
      subscription;
  }


  if(emailEl){
    emailEl.textContent=
      user?.email ||
      'Not available';
  }


  const initialEl=
    $('#accountInitial');

  if(initialEl){

    const source=
      profile.businessName ||
      profile.ownerName ||
      user?.email ||
      'V';

    initialEl.textContent=
      String(source)
        .trim()
        .charAt(0)
        .toUpperCase() || 'V';
  }


  const fields={

    accountOwnerInput:
      profile.ownerName ||
      user?.displayName ||
      '',

    accountBusinessInput:
      profile.businessName || '',

    accountStreetInput:
      address.street,

    accountCityInput:
      address.city,

    accountStateInput:
      address.state,

    accountZipInput:
      address.zip,

    accountPhoneInput:
      profile.phone || ''
  };


  for(
    const [id,value]
    of Object.entries(fields)
  ){

    const el=
      document.getElementById(id);

    if(el){
      el.value=value;
    }
  }
}


