function openCharterEditor(id=''){

  resetCharterForm();

  if(id){

    const charter=
      charterSchools.find(
        c=>c.id===id
      );

    if(!charter)return;

    editingCharterSchoolId=id;

    $('#charterFormTitle').textContent=
      'Edit charter school';

    $('#charterName').value=
      charter.name||'';

    $('#charterBillingEmail').value=
      charter.billingEmail||'';

    $('#charterPhone').value=
      charter.phone||'';

    $('#charterContactName').value=
      charter.contactName||'';

    $('#charterContactEmail').value=
      charter.contactEmail||'';

    $('#charterAddress').value=
      charter.address||'';

    $('#charterCity').value=
      charter.city||'';

    $('#charterState').value=
      charter.state||'';

    $('#charterZip').value=
      charter.zip||'';

    $('#charterInvoiceDays').value=
      Number.isFinite(
        Number(charter.invoiceDaysAfterStart)
      )
        ? Number(charter.invoiceDaysAfterStart)
        : 14;


    if($('#charterPaymentTerms')){

      $('#charterPaymentTerms').value=
        String(
          invoicePaymentTermsDays(
            charter.paymentTermsDays
          )
        );
    }


    $('#charterNotes').value=
      charter.notes||'';

    $('#saveCharterSchool').textContent=
      'Save changes';
  }

  show($('#charterForm'));
  $('#charterName').focus();
}


function sharedCharterAlreadySaved(record){

  return charterSchools.some(charter=>
    !charter.archived &&
    (
      String(charter.sharedBankId||'')===String(record.id||'') ||
      String(charter.name||'').trim().toLowerCase()===
        String(record.name||'').trim().toLowerCase()
    )
  );
}


function renderSharedCharterSchoolBank(){

  const list=$('#charterBankResults');
  const status=$('#charterBankStatus');
  const search=$('#charterBankSearch');

  if(!list || !status || !search){
    return;
  }

  const query=String(search.value||'').trim().toLowerCase();

  const matches=sharedCharterSchoolBank
    .filter(record=>{
      if(!query)return true;
      return [
        record.name,
        record.network,
        record.county,
        record.serviceCounties
      ].some(value=>String(value||'').toLowerCase().includes(query));
    })
    .slice(0);

  status.textContent=sharedCharterSchoolBank.length
    ? `${sharedCharterSchoolBank.length} verified California school record${sharedCharterSchoolBank.length===1?'':'s'}.`
    : 'Loading verified schools...';

  if(!matches.length){
    list.innerHTML='<div class="vf-charter-bank-empty">No verified school matches that search yet.</div>';
    return;
  }

  list.innerHTML=matches.map(record=>{
    const saved=sharedCharterAlreadySaved(record);
    return `
      <div class="vf-charter-bank-result">
        <div class="vf-charter-bank-result-copy">
          <strong>${esc(record.name)}</strong>
          <span>${esc(record.network||record.authorizer||'California charter school')}</span>
          <small>${esc(record.serviceCounties||record.county||'California')}</small>
          <small>Verified ${esc(record.verifiedAt||'')} · CDS ${esc(record.cdsCode||'')}</small>

          <div class="vf-charter-bank-emails">

            <small>
              <span>Invoices to</span>
              ${
                record.accountsPayableEmail
                  ? esc(record.accountsPayableEmail)
                  : '<em>not on file yet</em>'
              }
            </small>

            <small>
              <span>Vendor services</span>
              ${
                record.vendorEmail
                  ? esc(record.vendorEmail)
                  : '<em>not on file yet</em>'
              }
            </small>

          </div>
        </div>
        <button
          type="button"
          data-add-bank-charter="${esc(record.id)}"
          ${saved?'disabled':''}>
          ${saved?'Already Added':'Add to My Schools'}
        </button>
      </div>
    `;
  }).join('');

  $$('[data-add-bank-charter]').forEach(button=>{
    button.onclick=()=>{
      const record=sharedCharterSchoolBank.find(item=>item.id===button.dataset.addBankCharter);
      if(!record)return;

      openCharterEditor();
      selectedSharedCharterBankRecord=record;

      $('#charterFormTitle').textContent='Review verified charter school';
      $('#charterName').value=record.name||'';
      $('#charterBillingEmail').value=record.accountsPayableEmail||'';
      $('#charterPhone').value=record.vendorPhone||'';
      $('#charterContactName').value=record.network||'';
      $('#charterContactEmail').value=record.vendorEmail||'';
      $('#charterAddress').value=record.address||'';
      $('#charterCity').value=record.city||'';
      $('#charterState').value=record.state||'CA';
      $('#charterZip').value=record.zip||'';
      $('#charterNotes').value=[
        record.vendorProcess||'',
        record.sourceUrl ? `Verified source: ${record.sourceUrl}` : ''
      ].filter(Boolean).join('\n\n');

      $('#charterForm').scrollIntoView({behavior:'smooth',block:'start'});
    };
  });
}


async function loadSharedCharterSchoolBank(){

  if(sharedCharterSchoolBank.length){
    renderSharedCharterSchoolBank();
    return;
  }

  if(sharedCharterBankPromise){
    return sharedCharterBankPromise;
  }

  sharedCharterBankPromise=(async()=>{
    const status=$('#charterBankStatus');
    if(status)status.textContent='Loading verified schools...';

    try{
      const token=await user.getIdToken();
      const response=await fetch(
        `${VENDORFLOW_API}/charter-schools/bank`,
        {headers:{Authorization:`Bearer ${token}`}}
      );
      const data=await response.json();
      if(!response.ok){
        throw new Error(data.detail||data.error||'charter directory could not be loaded.');
      }
      sharedCharterSchoolBank=Array.isArray(data.schools)?data.schools:[];
      renderSharedCharterSchoolBank();
    }catch(error){
      console.error('Shared charter-school directory failed:',error);
      if(status)status.textContent='The verified charter-school directory could not be loaded. Manual entry still works.';
    }finally{
      sharedCharterBankPromise=null;
    }
  })();

  return sharedCharterBankPromise;
}


function organizeCharterSchoolPage(){

  const view=$('#chartersView');
  const list=$('#charterSchoolList');
  const bank=$('#charterBankSearch')?.closest('.vf-charter-bank');
  const form=$('#charterForm');

  if(!view || !list || !bank || !form){
    return;
  }

  let affiliations=$('#charterAffiliationsSection');

  if(!affiliations){
    affiliations=document.createElement('section');
    affiliations.id='charterAffiliationsSection';
    affiliations.className='vf-charter-affiliations';
    affiliations.innerHTML=`
      <div class="vf-charter-section-heading">
        <h3>My Charter School Affiliations</h3>
      </div>
    `;
  }

  const topHeading=view.querySelector(':scope > .row.between');

  if(topHeading){
    topHeading.insertAdjacentElement('afterend',affiliations);
  }

  affiliations.appendChild(list);
  affiliations.insertAdjacentElement('afterend',bank);
  bank.insertAdjacentElement('afterend',form);
}


function renderCharterSchools(){

  organizeCharterSchoolPage();

  loadSharedCharterSchoolBank();

  const list=
    $('#charterSchoolList');

  if(!list)return;

  const active=
    charterSchools
      .filter(c=>!c.archived)
      .sort(
        (a,b)=>
          (a.name||'')
            .localeCompare(b.name||'')
      );

  if(!active.length){

    list.innerHTML=`
      <div class="card vf-empty-charters">
        <strong>No charter schools saved yet.</strong>
      </div>
    `;

  }else{

    list.innerHTML=
      active.map(charter=>{

        const days=
          Number.isFinite(
            Number(charter.invoiceDaysAfterStart)
          )
            ? Number(charter.invoiceDaysAfterStart)
            : 14;

        return `
          <div class="card vf-charter-card">

            <div class="vf-charter-card-main">

              <h3>${esc(charter.name||'Unnamed charter')}</h3>

              <div class="vf-charter-card-head-actions">

                <button
                  data-edit-charter="${charter.id}">
                  Edit
                </button>

                <button
                  data-archive-charter="${charter.id}">
                  Archive
                </button>

              </div>

            </div>

            <div class="vf-charter-details">

              <div>
                <small>Billing email</small>
                <strong>
                  ${esc(charter.billingEmail||'Not entered')}
                </strong>
              </div>

              <div>
                <small>Invoice address</small>
                <strong>
                  ${esc(charterDisplayAddress(charter)||'Not entered')}
                </strong>
              </div>

              <div>
                <small>Invoice timing</small>
                <strong>
                  ${days} day${days===1?'':'s'} after certificate start
                </strong>
              </div>

              <div>
                <small>Contact</small>
                <strong>
                  ${esc(
                    charter.contactName ||
                    charter.contactEmail ||
                    charter.phone ||
                    'Not entered'
                  )}
                </strong>
              </div>

            </div>

          </div>
        `;
      }).join('');
  }

  $$('[data-edit-charter]')
    .forEach(button=>{

      button.onclick=()=>{

        openCharterEditor(
          button.dataset.editCharter
        );
      };
    });


  $$('[data-archive-charter]')
    .forEach(button=>{

      button.onclick=async()=>{

        const charter=
          charterSchools.find(
            c=>c.id===button.dataset.archiveCharter
          );

        if(!charter)return;

        const ok=
          confirm(
            `Archive ${charter.name}?\n\n` +
            `Certificates and invoice history will remain. ` +
            `You can restore the charter later.`
          );

        if(!ok)return;

        await setDoc(
          doc(
            db,
            'vendors',
            user.uid,
            'charterSchools',
            charter.id
          ),
          {
            archived:true,
            archivedAt:serverTimestamp(),
            updatedAt:serverTimestamp()
          },
          {
            merge:true
          }
        );

        await log(
          'Charter school archived',
          charter.name,
          'Manual'
        );

        await refreshAll();

        toast(
          'Charter school archived.'
        );
      };
    });


  renderArchivedCharterSchools();
}


function renderArchivedCharterSchools(){

  const list=
    $('#archivedCharterList');

  if(!list)return;

  const archived=
    charterSchools
      .filter(c=>c.archived)
      .sort(
        (a,b)=>
          (a.name||'')
            .localeCompare(b.name||'')
      );

  if(!archived.length){

    list.innerHTML=
      '<div class="empty">No archived charter schools.</div>';

    return;
  }

  list.innerHTML=
    archived.map(charter=>`
      <div class="vf-archived-charter">

        <div>
          <strong>
            ${esc(charter.name||'Unnamed charter')}
          </strong>

          <span>
            ${esc(
              charterDisplayAddress(charter) ||
              charter.billingEmail ||
              ''
            )}
          </span>
        </div>

        <button
          data-restore-charter="${charter.id}">
          Restore
        </button>

      </div>
    `).join('');


  $$('[data-restore-charter]')
    .forEach(button=>{

      button.onclick=async()=>{

        const charter=
          charterSchools.find(
            c=>c.id===button.dataset.restoreCharter
          );

        if(!charter)return;

        await setDoc(
          doc(
            db,
            'vendors',
            user.uid,
            'charterSchools',
            charter.id
          ),
          {
            archived:false,
            restoredAt:serverTimestamp(),
            updatedAt:serverTimestamp()
          },
          {
            merge:true
          }
        );

        await log(
          'Charter school restored',
          charter.name,
          'Manual'
        );

        await refreshAll();

        toast(
          'Charter school restored.'
        );
      };
    });
}





function selectedCertificateStudent(){

  const id=
    $('#certStudentId')?.value || '';

  if(!id){
    return null;
  }

  return students.find(
    student=>student.id===id
  ) || null;
}


function clearCertificateStudentLink(
  keepText=true
){

  if($('#certStudentId')){
    $('#certStudentId').value='';
  }

  if($('#certStudentLinked')){
    $('#certStudentLinked').innerHTML='';
    hide($('#certStudentLinked'));
  }

  if($('#certStudentMatches')){
    $('#certStudentMatches').innerHTML='';
    hide($('#certStudentMatches'));
  }

  if(!keepText && $('#certStudent')){
    $('#certStudent').value='';
  }
}


function linkCertificateStudent(
  student
){

  if(!student){
    return;
  }

  $('#certStudentId').value=
    student.id;

  $('#certStudent').value=
    student.studentName||'';


  const linked=
    $('#certStudentLinked');

  linked.innerHTML=`
    <div>
      <strong>
        Linked to ${esc(student.studentName||'Student')}
      </strong>

      <span>
        ${
          student.parentName
            ? esc(student.parentName)
            : 'Parent not entered'
        }
        ${
          student.parentEmail
            ? ' · '+esc(student.parentEmail)
            : ''
        }
        ${
          student.parentPhone
            ? ' · '+esc(student.parentPhone)
            : ''
        }
      </span>
    </div>

    <button
      type="button"
      id="changeCertificateStudent">
      Change
    </button>
  `;

  show(linked);

  hide(
    $('#certStudentMatches')
  );


  $('#changeCertificateStudent').onclick=()=>{

    clearCertificateStudentLink(
      true
    );

    $('#certStudent').focus();

    renderCertificateStudentMatches();
  };
}


function certificateStudentMatches(){

  const query=
    String(
      $('#certStudent')?.value || ''
    )
      .trim()
      .toLowerCase();

  if(!query){
    return [];
  }

  return students
    .filter(
      student=>
        studentSearchHaystack(
          student
        ).includes(query)
    )
    .sort(
      (a,b)=>
        String(a.studentName||'')
          .localeCompare(
            String(b.studentName||'')
          )
    )
    .slice(0,8);
}


function renderCertificateStudentMatches(){

  const input=
    $('#certStudent');

  const box=
    $('#certStudentMatches');

  if(!input || !box){
    return;
  }


  if(selectedCertificateStudent()){

    hide(box);
    return;
  }


  const typed=
    input.value.trim();

  if(!typed){

    box.innerHTML='';
    hide(box);
    return;
  }


  const matches=
    certificateStudentMatches();


  if(!matches.length){

    box.innerHTML=`
      <div class="vf-cert-student-no-match">
        <strong>No student found.</strong>
        <span>
          Add the student on the Students page, or choose
          "I'll match this student later" to save this certificate
          now and connect it once the student exists.
        </span>
      </div>
    `;

    show(box);
    return;
  }


  box.innerHTML=
    matches.map(
      student=>`
        <button
          type="button"
          class="vf-cert-student-match"
          data-cert-student-id="${student.id}">

          <strong>
            ${esc(student.studentName||'Unnamed student')}
          </strong>

          <span>
            ${esc(student.parentName||'')}
            ${
              student.parentEmail
                ? ' · '+esc(student.parentEmail)
                : ''
            }
            ${
              student.parentPhone
                ? ' · '+esc(student.parentPhone)
                : ''
            }
          </span>

        </button>
      `
    ).join('');


  $$('[data-cert-student-id]')
    .forEach(button=>{

      button.onclick=()=>{

        const student=
          students.find(
            item=>
              item.id===
              button.dataset.certStudentId
          );

        if(student){

          linkCertificateStudent(
            student
          );
        }
      };
    });


  show(box);
}


function tryExactCertificateStudentLink(){

  if(selectedCertificateStudent()){
    return;
  }

  const typed=
    normalizedName(
      $('#certStudent')?.value || ''
    );

  if(!typed){
    return;
  }

  const exact=
    students.find(
      student=>
        normalizedName(
          student.studentName
        )===typed
    );

  if(exact){

    linkCertificateStudent(
      exact
    );
  }
}


if($('#certStudent')){

  $('#certStudent').addEventListener(
    'input',
    ()=>{

      const linked=
        selectedCertificateStudent();

      if(
        linked &&
        normalizedName(
          $('#certStudent').value
        )!==
        normalizedName(
          linked.studentName
        )
      ){

        clearCertificateStudentLink(
          true
        );
      }

      renderCertificateStudentMatches();
    }
  );


  $('#certStudent').addEventListener(
    'focus',
    renderCertificateStudentMatches
  );


  $('#certStudent').addEventListener(
    'blur',
    ()=>{

      setTimeout(
        tryExactCertificateStudentLink,
        150
      );
    }
  );
}


function selectedCertificateCharter(){

  const id=
    $('#certCharterSchoolId')?.value || '';

  if(!id){
    return null;
  }

  return charterSchools.find(
    charter=>
      charter.id===id &&
      !charter.archived
  ) || null;
}


function clearCertificateCharterLink(
  keepText=true
){

  const hidden=
    $('#certCharterSchoolId');

  const linked=
    $('#certCharterLinked');

  const matches=
    $('#certCharterMatches');

  if(hidden){
    hidden.value='';
  }

  if(linked){
    linked.innerHTML='';
    hide(linked);
  }

  if(matches){
    matches.innerHTML='';
    hide(matches);
  }

  if(!keepText && $('#certSchool')){
    $('#certSchool').value='';
  }
}


function linkCertificateCharter(
  charter
){

  if(!charter){
    return;
  }

  $('#certCharterSchoolId').value=
    charter.id;

  $('#certSchool').value=
    charter.name||'';

  /*
   * Saved charter billing information becomes the default.
   * A certificate-specific billing email can still be edited.
   */
  if(
    charter.billingEmail &&
    !$('#certBillingEmail').value.trim()
  ){
    $('#certBillingEmail').value=
      charter.billingEmail;
  }


  const linked=
    $('#certCharterLinked');

  linked.innerHTML=`
    <div>
      <strong>
        Linked to ${esc(charter.name||'Charter school')}
      </strong>

      <span>
        ${
          charter.billingEmail
            ? esc(charter.billingEmail)
            : 'No billing email saved'
        }
        ·
        ${
          Number.isFinite(
            Number(charter.invoiceDaysAfterStart)
          )
            ? Number(charter.invoiceDaysAfterStart)
            : 14
        } day invoice timing
      </span>
    </div>

    <button
      type="button"
      id="changeCertificateCharter">
      Change
    </button>
  `;

  show(linked);

  hide(
    $('#certCharterMatches')
  );


  $('#changeCertificateCharter').onclick=()=>{

    clearCertificateCharterLink(
      true
    );

    $('#certSchool').focus();

    renderCertificateCharterMatches();
  };
}


function certificateCharterMatches(){

  const query=
    normalizedCharterName(
      $('#certSchool')?.value || ''
    );

  if(!query){
    return [];
  }

  return charterSchools
    .filter(
      charter=>
        !charter.archived &&
        normalizedCharterName(
          charter.name
        ).includes(query)
    )
    .sort(
      (a,b)=>
        String(a.name||'')
          .localeCompare(
            String(b.name||'')
          )
    )
    .slice(0,8);
}


function renderCertificateCharterMatches(){

  const input=
    $('#certSchool');

  const box=
    $('#certCharterMatches');

  if(!input || !box){
    return;
  }


  if(selectedCertificateCharter()){

    hide(box);
    return;
  }


  const typed=
    input.value.trim();

  if(!typed){

    box.innerHTML='';
    hide(box);
    return;
  }


  const matches=
    certificateCharterMatches();


  const matchHTML=
    matches.map(
      charter=>`
        <button
          type="button"
          class="vf-cert-charter-match"
          data-cert-charter-id="${charter.id}">

          <strong>
            ${esc(charter.name||'Unnamed charter')}
          </strong>

          <span>
            ${esc(
              charterDisplayAddress(charter) ||
              charter.billingEmail ||
              'Saved charter'
            )}
          </span>

        </button>
      `
    ).join('');


  box.innerHTML=`
    ${matchHTML}

    <button
      type="button"
      class="vf-cert-charter-add"
      id="addCertificateCharter">

      <strong>
        + Add new charter school
      </strong>

      <span>
        ${typed
          ? `Create “${esc(typed)}” in your charter directory`
          : 'Add a charter school'
        }
      </span>

    </button>
  `;


  $$('[data-cert-charter-id]')
    .forEach(button=>{

      button.onclick=()=>{

        const charter=
          charterSchools.find(
            item=>
              item.id===
              button.dataset.certCharterId
          );

        if(charter){
          linkCertificateCharter(
            charter
          );
        }
      };
    });


  $('#addCertificateCharter').onclick=()=>{

    const name=
      $('#certSchool').value.trim();

    /*
     * Preserve the certificate form while the vendor adds
     * a charter record in the Charter Schools section.
     */
    sessionStorage.setItem(
      'vendorflowPendingCertificateCharter',
      JSON.stringify({
        name,
        student:
          $('#certStudent')?.value || '',
        amount:
          $('#certAmount')?.value || '',
        number:
          $('#certNumber')?.value || '',
        issueDate:
          $('#certIssueDate')?.value || '',
        serviceStart:
          $('#certServiceStart')?.value || '',
        serviceEnd:
          $('#certServiceEnd')?.value || '',
        billingEmail:
          $('#certBillingEmail')?.value || '',
        serviceDescription:
          $('#certServiceDescription')?.value || '',
        invoiceInstructions:
          $('#certInvoiceInstructions')?.value || '',
        notes:
          $('#certNotes')?.value || ''
      })
    );


    switchView(
      'charters'
    );


    openCharterEditor();


    $('#charterName').value=
      name;
  };


  show(box);
}


function restorePendingCertificateAfterCharterSave(
  charter
){

  const raw=
    sessionStorage.getItem(
      'vendorflowPendingCertificateCharter'
    );

  if(!raw){
    return;
  }


  let pending=null;

  try{
    pending=JSON.parse(raw);
  }catch{
    pending=null;
  }


  sessionStorage.removeItem(
    'vendorflowPendingCertificateCharter'
  );


  if(!pending){
    return;
  }


  switchView(
    'certificates'
  );


  show(
    $('#certificateForm')
  );


  $('#certStudent').value=
    pending.student||'';

  $('#certAmount').value=
    pending.amount||'';

  $('#certNumber').value=
    pending.number||'';

  $('#certIssueDate').value=
    pending.issueDate||'';

  $('#certServiceStart').value=
    pending.serviceStart||'';

  $('#certServiceEnd').value=
    pending.serviceEnd||'';

  $('#certBillingEmail').value=
    pending.billingEmail||'';

  $('#certServiceDescription').value=
    pending.serviceDescription||'';

  $('#certInvoiceInstructions').value=
    pending.invoiceInstructions||'';

  $('#certNotes').value=
    pending.notes||'';


  linkCertificateCharter(
    charter
  );


  toast(
    'Charter school added and linked to this certificate.'
  );
}


if($('#certSchool')){

  $('#certSchool').addEventListener(
    'input',
    ()=>{

      /*
       * Editing the text after a selection breaks the link
       * until the vendor explicitly selects a charter again.
       */
      const linked=
        selectedCertificateCharter();

      if(
        linked &&
        normalizedCharterName(
          $('#certSchool').value
        )!==
        normalizedCharterName(
          linked.name
        )
      ){
        clearCertificateCharterLink(
          true
        );
      }

      renderCertificateCharterMatches();
    }
  );


  $('#certSchool').addEventListener(
    'focus',
    renderCertificateCharterMatches
  );
}


function normalizedCharterName(value){

  return String(value||'')
    .trim()
    .toLowerCase()
    .replace(/\s+/g,' ');
}


/*
 * Strong comparison form used only for matching.
 *
 * Examples:
 *
 * Pacific Coast Academy
 * Pacific Coast Academy (PCA)
 *
 * both become:
 *
 * pacific coast academy
 *
 * We deliberately remove only a TRAILING parenthetical
 * abbreviation/name note. We do not broadly delete words.
 */
function comparableCharterName(value){

  return normalizedCharterName(
    value
  )
    .replace(
      /\s*\([^)]{1,30}\)\s*$/,
      ''
    )
    .replace(
      /[.,]/g,
      ''
    )
    .replace(
      /\s+/g,
      ' '
    )
    .trim();
}


function savedCharterAliases(
  charter
){

  const raw=
    Array.isArray(
      charter?.aliases
    )
      ? charter.aliases
      : [];


  return raw
    .map(
      alias=>
        String(alias||'').trim()
    )
    .filter(Boolean);
}


function resolveSavedCharterMatch(
  name
){

  const typed=
    String(name||'').trim();

  const normalized=
    normalizedCharterName(
      typed
    );

  const comparable=
    comparableCharterName(
      typed
    );


  if(!normalized){

    return {
      charter:null,
      type:'none',
      candidates:[]
    };
  }


  const active=
    charterSchools.filter(
      charter=>
        !charter.archived
    );


  /*
   * 1. Exact saved charter name.
   */
  const exact=
    active.filter(
      charter=>
        normalizedCharterName(
          charter.name
        )===normalized
    );


  if(exact.length===1){

    return {
      charter:exact[0],
      type:'exact',
      candidates:exact
    };
  }


  /*
   * 2. Exact remembered alias.
   */
  const aliasMatches=
    active.filter(
      charter=>
        savedCharterAliases(
          charter
        ).some(
          alias=>
            normalizedCharterName(
              alias
            )===normalized
        )
    );


  if(aliasMatches.length===1){

    return {
      charter:aliasMatches[0],
      type:'alias',
      candidates:aliasMatches
    };
  }


  /*
   * 3. Strong canonical match.
   *
   * This safely handles cases such as:
   *
   * Pacific Coast Academy
   * Pacific Coast Academy (PCA)
   */
  const comparableMatches=
    comparable
      ? active.filter(
          charter=>
            comparableCharterName(
              charter.name
            )===comparable ||
            savedCharterAliases(
              charter
            ).some(
              alias=>
                comparableCharterName(
                  alias
                )===comparable
            )
        )
      : [];


  if(comparableMatches.length===1){

    return {
      charter:comparableMatches[0],
      type:'strong',
      candidates:comparableMatches
    };
  }


  /*
   * 4. Suggestions only.
   *
   * These are NOT automatically accepted. If more than one
   * school could plausibly be intended, the vendor chooses.
   */
  const suggestions=
    comparable
      ? active.filter(
          charter=>{

            const candidate=
              comparableCharterName(
                charter.name
              );


            if(!candidate){
              return false;
            }


            return (
              candidate.includes(
                comparable
              ) ||
              comparable.includes(
                candidate
              )
            );
          }
        )
      : [];


  return {
    charter:null,
    type:
      suggestions.length
        ? 'suggestions'
        : 'none',
    candidates:
      suggestions.slice(0,6)
  };
}


function findSavedCharterByName(name){

  return (
    resolveSavedCharterMatch(
      name
    ).charter ||
    null
  );
}


async function rememberCharterAlias(
  charter,
  alias
){

  if(
    !charter ||
    !charter.id ||
    !user
  ){
    return;
  }


  const clean=
    String(alias||'').trim();


  if(!clean){
    return;
  }


  const normalized=
    normalizedCharterName(
      clean
    );


  if(
    normalizedCharterName(
      charter.name
    )===normalized
  ){
    return;
  }


  const existing=
    savedCharterAliases(
      charter
    );


  if(
    existing.some(
      value=>
        normalizedCharterName(
          value
        )===normalized
    )
  ){
    return;
  }


  const aliases=[
    ...existing,
    clean
  ];


  await setDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'charterSchools',
      charter.id
    ),
    {
      aliases,
      updatedAt:
        serverTimestamp()
    },
    {
      merge:true
    }
  );


  charter.aliases=
    aliases;
}


function parseVendorDate(value){

  const text=
    String(value||'').trim();

  if(!text){
    return null;
  }


  /*
   * ISO date: 2026-09-14
   */
  let match=
    text.match(
      /^(\d{4})-(\d{1,2})-(\d{1,2})$/
    );

  if(match){

    const year=Number(match[1]);
    const month=Number(match[2]);
    const day=Number(match[3]);

    const date=
      new Date(
        year,
        month-1,
        day,
        12,
        0,
        0,
        0
      );

    if(
      date.getFullYear()===year &&
      date.getMonth()===month-1 &&
      date.getDate()===day
    ){
      return date;
    }

    return null;
  }


  /*
   * US date: 9/14/2026
   */
  match=
    text.match(
      /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/
    );

  if(match){

    const month=Number(match[1]);
    const day=Number(match[2]);
    const year=Number(match[3]);

    const date=
      new Date(
        year,
        month-1,
        day,
        12,
        0,
        0,
        0
      );

    if(
      date.getFullYear()===year &&
      date.getMonth()===month-1 &&
      date.getDate()===day
    ){
      return date;
    }

    return null;
  }


  /*
   * Certificate extraction may return a readable date such as
   * "September 14, 2026". Use browser parsing only as a final
   * fallback, then normalize it to local noon.
   */
  const fallback=
    new Date(text);

  if(
    Number.isNaN(
      fallback.getTime()
    )
  ){
    return null;
  }

  return new Date(
    fallback.getFullYear(),
    fallback.getMonth(),
    fallback.getDate(),
    12,
    0,
    0,
    0
  );
}


function dateToLocalISO(date){

  if(
    !date ||
    Number.isNaN(date.getTime())
  ){
    return '';
  }

  const year=
    date.getFullYear();

  const month=
    String(
      date.getMonth()+1
    ).padStart(2,'0');

  const day=
    String(
      date.getDate()
    ).padStart(2,'0');

  return `${year}-${month}-${day}`;
}


function formatVendorDate(value){

  const date=
    value instanceof Date
      ? value
      : parseVendorDate(value);

  if(!date){
    return '';
  }

  return date.toLocaleDateString(
    undefined,
    {
      month:'short',
      day:'numeric',
      year:'numeric'
    }
  );
}


function uniqueTutoringClassForStudent(
  studentId
){

  if(!studentId){
    return null;
  }


  const tutoringServices=
    services.filter(
      service=>
        service.studentId===studentId &&
        service.status!=='Dropped' &&
        service.status!=='Removed' &&
        service.classId
    );


  const ids=[
    ...new Set(
      tutoringServices
        .map(
          service=>service.classId
        )
        .filter(Boolean)
    )
  ];


  const tutoringClasses=
    ids
      .map(
        id=>
          classes.find(
            c=>
              c.id===id &&
              c.classType==='Tutoring' &&
              !c.archived
          )
      )
      .filter(Boolean);


  /*
   * Never guess between multiple tutoring classes.
   */
  return tutoringClasses.length===1
    ? tutoringClasses[0]
    : null;
}


function uniqueActiveClassForStudent(
  studentId
){

  if(!studentId){
    return null;
  }


  const activeServices=
    services.filter(
      service=>
        service.studentId===studentId &&
        service.status!=='Dropped' &&
        service.status!=='Removed' &&
        service.classId
    );


  const ids=[
    ...new Set(
      activeServices
        .map(
          service=>service.classId
        )
        .filter(Boolean)
    )
  ];


  const activeClasses=
    ids
      .map(
        id=>
          classes.find(
            c=>
              c.id===id &&
              !c.archived
          )
      )
      .filter(Boolean);


  /*
   * Never guess between multiple classes -- same rule as
   * uniqueTutoringClassForStudent above, just not restricted to
   * Tutoring-type classes, so a per-class invoice-timing override
   * (classInvoiceDaysAfterStart) can also apply to a regular
   * roster class, not only 1:1 tutoring.
   */
  return activeClasses.length===1
    ? activeClasses[0]
    : null;
}


function certificateInvoiceSchedule(
  serviceStartDate,
  charter,
  studentId=''
){

  const start=
    parseVendorDate(
      serviceStartDate
    );

  if(!start){

    return {
      readyDate:'',
      days:null,
      valid:false,
      source:''
    };
  }


  const studentClass=
    uniqueActiveClassForStudent(
      studentId
    );


  const classInvoiceDaysRaw=
    studentClass?.invoiceDaysAfterStart;


  /*
   * A class only "counts" here if a vendor actually set an
   * invoice-timing value on it -- null/undefined (an older class
   * saved before this field existed, or simply never touched)
   * falls back to the charter's own setting instead. Number(null)
   * is 0, which would wrongly look like a real "0 days" setting,
   * so the raw value is checked before ever coercing to a number.
   */
  const classDaysSet=
    classInvoiceDaysRaw!==null &&
    classInvoiceDaysRaw!==undefined &&
    Number.isFinite(Number(classInvoiceDaysRaw));


  const charterDays=
    Number(
      charter?.invoiceDaysAfterStart
    );


  const accountDefaultRaw=
    profile?.invoiceDaysAfterStartDefault;

  const accountDefaultSet=
    accountDefaultRaw!==null &&
    accountDefaultRaw!==undefined &&
    Number.isFinite(Number(accountDefaultRaw));


  /*
   * A class's own invoice-timing setting -- if the vendor actually
   * set one -- always wins. This used to only exist for Tutoring
   * classes; the wizard now asks every class for this, so any
   * class type can carry its own override. Falls back to the
   * charter school's own default next, then the vendor's
   * account-wide default (Settings > Invoicing), then 14 days.
   */
  const rawDays=
    classDaysSet
      ? Number(classInvoiceDaysRaw)
      : Number.isFinite(charterDays)
        ? charterDays
        : accountDefaultSet
          ? Number(accountDefaultRaw)
          : NaN;


  const days=
    Number.isFinite(rawDays)
      ? Math.max(
          0,
          Math.min(
            365,
            Math.round(rawDays)
          )
        )
      : 14;


  const ready=
    new Date(
      start.getFullYear(),
      start.getMonth(),
      start.getDate(),
      12,
      0,
      0,
      0
    );


  ready.setDate(
    ready.getDate()+days
  );


  return {
    readyDate:
      dateToLocalISO(ready),

    days,

    valid:true,

    source:
      studentClass && classDaysSet
        ? (
            studentClass.classType==='Tutoring'
              ? 'Tutoring group'
              : 'Group settings'
          )
        : 'Charter school settings',

    tutoringClassId:
      studentClass?.id || '',

    tutoringClassName:
      studentClass?.name || ''
  };
}


function certificateIsInvoiceReady(cert){

  if(
    cert.status!=='Received - Not Billed'
  ){
    return false;
  }

  if(!cert.invoiceReadyDate){
    return false;
  }

  const ready=
    parseVendorDate(
      cert.invoiceReadyDate
    );

  if(!ready){
    return false;
  }

  const today=
    new Date();

  const todayOnly=
    new Date(
      today.getFullYear(),
      today.getMonth(),
      today.getDate(),
      12,
      0,
      0,
      0
    );

  return ready<=todayOnly;
}


function invoiceReadyCertificates(){

  return certs.filter(
    certificateIsInvoiceReady
  );
}




function smartTitleCase(value){

  const text=
    String(value||'').trim();

  if(!text){
    return '';
  }

  return text
    .toLowerCase()
    .replace(
      /\b([a-z])/g,
      match=>match.toUpperCase()
    );
}


function formatState(value){

  return String(value||'')
    .trim()
    .toUpperCase();
}


function formattedInvoiceCityLine(
  city,
  state,
  zip
){

  const cityText=
    smartTitleCase(city);

  const stateZip=
    [
      formatState(state),
      String(zip||'').trim()
    ]
      .filter(Boolean)
      .join(' ');

  return [
    cityText,
    stateZip
  ]
    .filter(Boolean)
    .join(', ');
}


function invoiceCreatedDate(invoice){

  if(
    invoice?.createdAt?.toDate
  ){
    return invoice.createdAt.toDate();
  }

  if(invoice?.invoiceDate){

    return parseVendorDate(
      invoice.invoiceDate
    );
  }

  return null;
}


function formatInvoiceDate(invoice){

  const date=
    invoiceCreatedDate(invoice);

  if(!date){
    return '';
  }

  return date.toLocaleDateString(
    undefined,
    {
      month:'short',
      day:'numeric',
      year:'numeric'
    }
  );
}


function invoiceServicePeriod(invoice){

  const start=
    formatVendorDate(
      invoice.serviceStartDate
    );

  const end=
    formatVendorDate(
      invoice.serviceEndDate
    );

  if(start && end){
    return `${start} – ${end}`;
  }

  return start || end || '';
}



function incrementInvoiceSequenceNumber(
  value
){

  const text=
    String(value||'').trim();

  /*
   * Preserve everything around the FINAL run of digits.
   *
   * 26-57      -> 26-58
   * 2026-0057  -> 2026-0058
   * INV-099-A  -> INV-100-A
   */
  const match=
    text.match(
      /^(.*?)(\d+)(\D*)$/
    );


  if(!match){
    return '';
  }


  const prefix=
    match[1];

  const digits=
    match[2];

  const suffix=
    match[3];


  const nextNumber=
    String(
      Number(digits)+1
    )
      .padStart(
        digits.length,
        '0'
      );


  return (
    prefix +
    nextNumber +
    suffix
  );
}


function invoiceNumberSequenceValid(
  value
){

  const text=
    String(value||'').trim();

  return Boolean(
    text &&
    incrementInvoiceSequenceNumber(
      text
    )
  );
}


function updateInvoiceNumberingUI(){

  const auto=
    $('#invoiceNumberAuto');

  const custom=
    $('#invoiceNumberCustom');

  const fields=
    $('#invoiceNumberCustomFields');

  const input=
    $('#invoiceNumberNext');

  const preview=
    $('#invoiceNumberPreview');


  if(
    !auto ||
    !custom ||
    !fields ||
    !input ||
    !preview
  ){
    return;
  }


  if(custom.checked){

    show(fields);


    const current=
      input.value.trim();

    const next=
      incrementInvoiceSequenceNumber(
        current
      );


    if(current && next){

      preview.innerHTML=
        `<strong>Next invoice:</strong>
         ${esc(current)}
         <span>then ${esc(next)}</span>`;

    }else if(current){

      preview.innerHTML=
        `<strong>Check this format.</strong>
         VendorFlow needs an invoice number containing
         a number it can increment.`;

    }else{

      preview.innerHTML=
        `Example:
         <strong>26-57</strong>
         becomes 26-58, 26-59, and so on.`;
    }


  }else{

    hide(fields);

    preview.innerHTML='';
  }
}


function renderInvoiceNumberingSettings(){

  const auto=
    $('#invoiceNumberAuto');

  const custom=
    $('#invoiceNumberCustom');

  const input=
    $('#invoiceNumberNext');


  if(
    !auto ||
    !custom ||
    !input
  ){
    return;
  }


  const mode=
    String(
      profile.invoiceNumberMode||''
    );


  auto.checked=
    mode==='auto';

  custom.checked=
    mode==='custom';


  input.value=
    profile.invoiceNumberNext||'';


  updateInvoiceNumberingUI();
}


function defaultOverdueInvoiceSettings(){

  return {

    graceDays:
      10,

    repeatEnabled:
      false,

    repeatInterval:
      7,

    repeatUnit:
      'days'
  };
}


function renderOverdueInvoiceSettings(){

  const graceField=
    $('#overdueGraceDays');

  const repeatEnabledField=
    $('#overdueRepeatEnabled');

  const intervalField=
    $('#overdueRepeatInterval');

  const unitField=
    $('#overdueRepeatUnit');


  if(
    !graceField ||
    !repeatEnabledField ||
    !intervalField ||
    !unitField
  ){
    return;
  }


  const saved=
    profile.overdueInvoiceSettings ||
    {};

  const defaults=
    defaultOverdueInvoiceSettings();


  graceField.value=
    Number.isFinite(
      Number(saved.graceDays)
    )
      ? Number(saved.graceDays)
      : defaults.graceDays;

  repeatEnabledField.checked=
    saved.repeatEnabled ??
    defaults.repeatEnabled;

  intervalField.value=
    Number.isFinite(
      Number(saved.repeatInterval)
    )
      ? Number(saved.repeatInterval)
      : defaults.repeatInterval;

  unitField.value=
    saved.repeatUnit ||
    defaults.repeatUnit;


  intervalField.disabled=
    !repeatEnabledField.checked;

  unitField.disabled=
    !repeatEnabledField.checked;
}


