function invoiceEmailPlaceholderValues(invoice){

  const charter=
    charterSchools.find(
      item=>
        item.id===
        invoice.charterSchoolId
    ) || {};

  const dueDate=
    invoice.dueDate ||
    invoiceDueDateForTerms(
      invoice.paymentTermsDays ??
      charter.paymentTermsDays
    );

  return {

    invoiceNumber:
      invoice.invoiceNumber||'',

    businessName:
      invoice.vendorBusinessName ||
      profile.businessName ||
      '',

    ownerName:
      invoice.vendorOwnerName ||
      profile.ownerName ||
      '',

    charterSchool:
      invoice.charterSchoolName ||
      charter.name ||
      '',

    studentName:
      invoice.studentName||'',

    certificateNumber:
      invoice.certificateNumber||'',

    serviceName:
      invoice.serviceName ||
      'Educational services',

    amount:
      money(
        invoice.amount||0
      ),

    invoiceDate:
      invoice.invoiceDate||'',

    dueDate:
      dueDate||''
  };
}


function fillInvoiceEmailTemplate(text,values){

  return String(text||'')
    .replace(
      /\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g,
      (match,key)=>
        (
          values[key] !== undefined &&
          values[key] !== null &&
          values[key] !== ''
        )
          ? String(values[key])
          : ''
    );
}


function buildInvoiceEmailPreview(invoice){

  const charter=
    charterSchools.find(
      item=>
        item.id===
        invoice.charterSchoolId
    ) || {};

  const to=
    String(
      invoice.charterBillingEmail ||
      charter.billingEmail ||
      charter.contactEmail ||
      ''
    ).trim();

  const saved=
    profile.invoiceEmailTemplate ||
    {};

  const defaults=
    defaultInvoiceEmailTemplate();

  const values=
    invoiceEmailPlaceholderValues(
      invoice
    );

  const subject=
    fillInvoiceEmailTemplate(
      saved.subject ||
      defaults.subject,
      values
    );

  const body=
    fillInvoiceEmailTemplate(
      saved.body ||
      defaults.body,
      values
    );

  return {
    to,
    subject,
    body
  };
}


