function nextAutomaticInvoiceSequence(){

  const year=
    new Date().getFullYear();


  const used=
    invoices
      .map(
        invoice=>
          String(
            invoice.invoiceNumber||''
          )
      )
      .map(number=>{

        const match=
          number.match(
            new RegExp(
              `^VF-${year}-(\\d+)$`
            )
          );

        return match
          ? Number(match[1])
          : null;
      })
      .filter(
        value=>
          Number.isFinite(value)
      );


  return used.length
    ? Math.max(...used)+1
    : 1;
}


async function reserveNextInvoiceNumber(){

  const ref=
    vendorDoc();


  return await runTransaction(
    db,
    async transaction=>{

      const snap=
        await transaction.get(
          ref
        );

      const data=
        snap.exists()
          ? snap.data()
          : {};


      const mode=
        String(
          data.invoiceNumberMode||''
        );


      if(mode==='custom'){

        const current=
          String(
            data.invoiceNumberNext||''
          ).trim();


        const next=
          incrementInvoiceSequenceNumber(
            current
          );


        if(!current || !next){

          throw new Error(
            'Invoice numbering needs setup.'
          );
        }


        transaction.set(
          ref,
          {
            invoiceNumberNext:
              next,

            invoiceNumberLastUsed:
              current,

            invoiceNumberUpdatedAt:
              serverTimestamp()
          },
          {
            merge:true
          }
        );


        /*
         * Keep in-memory profile aligned so additional
         * invoices created during this same refresh know
         * the newly reserved next number.
         */
        profile.invoiceNumberNext=
          next;

        profile.invoiceNumberLastUsed=
          current;


        return current;
      }


      if(mode==='auto'){

        const year=
          new Date().getFullYear();


        let sequence=
          Number(
            data.invoiceAutoNextNumber
          );


        if(
          !Number.isFinite(sequence) ||
          sequence<1
        ){

          sequence=
            nextAutomaticInvoiceSequence();
        }


        const number=
          `VF-${year}-${String(sequence).padStart(4,'0')}`;


        transaction.set(
          ref,
          {
            invoiceAutoNextNumber:
              sequence+1,

            invoiceNumberLastUsed:
              number,

            invoiceNumberUpdatedAt:
              serverTimestamp()
          },
          {
            merge:true
          }
        );


        profile.invoiceAutoNextNumber=
          sequence+1;

        profile.invoiceNumberLastUsed=
          number;


        return number;
      }


      throw new Error(
        'Choose your invoice numbering before VendorFlow prepares an invoice.'
      );
    }
  );
}


function invoiceStatus(invoice){

  return String(
    invoice?.status||'Ready to Send'
  ).trim();
}


function invoiceCharter(cert){

  if(cert.charterSchoolId){

    const exact=
      charterSchools.find(
        charter=>
          charter.id===cert.charterSchoolId
      );

    if(exact){
      return exact;
    }
  }


  const target=
    normalizedCharterName(
      cert.school
    );


  return charterSchools.find(
    charter=>
      normalizedCharterName(
        charter.name
      )===target
  ) || null;
}


function invoiceStudent(cert){

  if(cert.studentId){

    const exact=
      students.find(
        student=>
          student.id===cert.studentId
      );

    if(exact){
      return exact;
    }
  }


  const target=
    normalizedName(
      cert.student
    );


  return students.find(
    student=>
      normalizedName(
        student.studentName
      )===target
  ) || null;
}


function invoiceService(cert,student){

  const possible=
    services.filter(
      service=>
        service.studentId===student?.id &&
        serviceCountsAsActive(service)
    );


  if(!possible.length){
    return null;
  }


  if(possible.length===1){
    return possible[0];
  }


  const certStart=
    String(
      cert.serviceStartDate||''
    );


  return possible.find(
    service=>
      String(service.startDate||'')===
      certStart
  ) || possible[0];
}


function invoiceNumberForCertificate(cert){

  const year=
    new Date().getFullYear();

  const existingNumbers=
    invoices
      .map(
        invoice=>
          String(invoice.invoiceNumber||'')
      )
      .map(number=>{

        const match=
          number.match(
            /^VF-(\d{4})-(\d+)$/
          );

        if(
          !match ||
          Number(match[1])!==year
        ){
          return null;
        }

        return Number(match[2]);
      })
      .filter(
        number=>
          Number.isFinite(number)
      );


  const next=
    (
      existingNumbers.length
        ? Math.max(...existingNumbers)
        : 0
    )+1;


  return `VF-${year}-${String(next).padStart(4,'0')}`;
}



function invoicePaymentTermsDays(
  value
){

  const raw=
    Number(value);

  if(!Number.isFinite(raw)){
    return 30;
  }

  return Math.max(
    0,
    Math.min(
      365,
      Math.round(raw)
    )
  );
}


function invoicePaymentTermsLabel(
  value
){

  const days=
    invoicePaymentTermsDays(
      value
    );

  return days===0
    ? 'Due upon receipt'
    : `Net ${days}`;
}


function invoiceDueDateForTerms(
  invoiceDate,
  paymentTermsDays
){

  const date=
    parseVendorDate(
      invoiceDate
    );

  if(!date){
    return '';
  }

  const result=
    new Date(
      date.getFullYear(),
      date.getMonth(),
      date.getDate() +
        invoicePaymentTermsDays(
          paymentTermsDays
        ),
      12,
      0,
      0
    );

  return dateToLocalISO(
    result
  );
}


async function createDueInvoices(){

  const due=
    invoiceReadyCertificates();


  /*
   * Invoice numbering is a one-time vendor choice.
   * Never invent a numbering system for a vendor who
   * may already have invoices outside VendorFlow.
   */
  if(
    due.length &&
    !profile.invoiceNumberMode
  ){
    return 0;
  }

  if(!due.length){
    return 0;
  }


  let created=0;


  for(const cert of due){

    const alreadyExists=
      invoices.some(
        invoice=>
          invoice.certificateId===cert.id
      );


    if(alreadyExists){
      continue;
    }


    const charter=
      invoiceCharter(cert);

    const student=
      invoiceStudent(cert);


    /*
     * VendorFlow never quietly guesses when required billing
     * relationships are missing.
     */
    if(
      !charter ||
      !student
    ){
      continue;
    }


    const service=
      invoiceService(
        cert,
        student
      );


    const vendorAddress=
      vendorAddressParts();


    const invoiceRef=
      doc(
        sub('invoices')
      );


    const invoice={
      invoiceNumber:
        await reserveNextInvoiceNumber(),

      status:
        'Ready to Send',

      certificateId:
        cert.id,

      certificateNumber:
        cert.number||'',

      certificateAmount:
        Number(cert.amount||0),

      serviceAmount:
        Number(
          cert.serviceAmount ||
          Math.max(
            0,
            Number(cert.amount||0) -
            Number(cert.materialsFee||0)
          )
        ),

      materialsFee:
        Math.max(
          0,
          Number(cert.materialsFee||0)
        ),

      amount:
        Number(cert.amount||0),

      studentId:
        student.id,

      studentName:
        student.studentName ||
        cert.student ||
        '',

      parentName:
        student.parentName||'',

      serviceId:
        service?.id||'',

      serviceName:
        cert.serviceDescription ||
        service?.name ||
        service?.serviceName ||
        service?.type ||
        'Educational services',

      serviceStartDate:
        cert.serviceStartDate ||
        service?.startDate ||
        '',

      serviceEndDate:
        cert.serviceEndDate ||
        service?.endDate ||
        '',

      invoiceDate:
        dateToLocalISO(
          new Date()
        ),

      paymentTermsDays:
        invoicePaymentTermsDays(
          charter.paymentTermsDays
        ),

      paymentTermsLabel:
        invoicePaymentTermsLabel(
          charter.paymentTermsDays
        ),

      dueDate:
        invoiceDueDateForTerms(
          dateToLocalISO(
            new Date()
          ),
          charter.paymentTermsDays
        ),

      charterSchoolId:
        charter.id,

      charterSchoolName:
        charter.name||cert.school||'',

      charterAddress:
        charter.address||'',

      charterCity:
        charter.city||'',

      charterState:
        charter.state||'',

      charterZip:
        charter.zip||'',

      charterBillingEmail:
        charter.billingEmail ||
        charter.contactEmail ||
        '',

      vendorBusinessName:
        profile.businessName||'',

      vendorOwnerName:
        profile.ownerName||'',

      vendorStreet:
        vendorAddress.street||'',

      vendorCity:
        vendorAddress.city||'',

      vendorState:
        vendorAddress.state||'',

      vendorZip:
        vendorAddress.zip||'',

      vendorPhone:
        profile.phone||'',

      vendorEmail:
        user?.email||'',

      invoiceReadyDate:
        cert.invoiceReadyDate||'',

      preparedBy:
        'VendorFlow',

      createdAt:
        serverTimestamp(),

      updatedAt:
        serverTimestamp()
    };


    await setDoc(
      invoiceRef,
      invoice
    );


    await setDoc(
      doc(
        db,
        'vendors',
        user.uid,
        'certificates',
        cert.id
      ),
      {
        invoiceId:
          invoiceRef.id,

        invoiceNumber:
          invoice.invoiceNumber,

        status:
          'Invoiced - Ready to Send',

        invoicedAt:
          serverTimestamp(),

        updatedAt:
          serverTimestamp()
      },
      {
        merge:true
      }
    );


    await log(
      'Invoice prepared',
      `${invoice.invoiceNumber} for ${invoice.studentName} — ${money(invoice.amount)} — ${invoice.charterSchoolName}.`,
      'VendorFlow',
      {
        type:'invoice',
        id:invoiceRef.id
      }
    );


    created++;

    /*
     * "Send invoices to charter schools" (Settings > Automations).
     * Creating the invoice record above always happens automatically
     * -- this only decides whether VendorFlow also emails it to the
     * charter school right away, the same send this cert's invoice
     * would otherwise wait in "Ready to Send" for the vendor to
     * trigger by hand from the Invoices page. Skips quietly (leaves
     * it Ready to Send) if there's no billing email on file, rather
     * than showing an alert() with nobody there to see it.
     */
    if(profile?.automations?.sendCharterInvoices){

      const invoiceForAutoSend={
        id:invoiceRef.id,
        ...invoice
      };

      const autoSendFields=
        buildInvoiceEmailPreview(
          invoiceForAutoSend
        );

      if(autoSendFields.to){

        try{

          await sendInvoiceThroughVendorFlow(
            invoiceForAutoSend,
            autoSendFields
          );

        }catch(error){

          console.error(
            'Could not auto-send invoice:',
            error
          );
        }
      }
    }
  }


  return created;
}


