async function dismissOverdueInvoiceReminder(invoiceId){

  const invoice=
    invoices.find(
      item=>item.id===invoiceId
    );

  if(!invoice || !user){
    return;
  }


  const settings=
    profile.overdueInvoiceSettings ||
    defaultOverdueInvoiceSettings();

  const today=
    new Date();

  today.setHours(0,0,0,0);

  let dismissedUntilDate=
    new Date(today);

  if(settings.repeatEnabled){

    const intervalUnitDays=
      settings.repeatUnit==='weeks'
        ? 7
        : 1;

    const intervalDays=
      Math.max(
        1,
        Number(settings.repeatInterval||1)
      ) * intervalUnitDays;

    dismissedUntilDate.setDate(
      dismissedUntilDate.getDate()+intervalDays
    );

  } else {

    dismissedUntilDate.setFullYear(
      dismissedUntilDate.getFullYear()+50
    );
  }

  const dismissedUntil=
    dateToLocalISO(
      dismissedUntilDate
    );

  await setDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'invoices',
      invoice.id
    ),
    {
      overdueReminder:{
        dismissedUntil,
        lastDismissedAt:
          serverTimestamp()
      }
    },
    {
      merge:true
    }
  );

  invoice.overdueReminder=
    {dismissedUntil};

  await log(
    'Overdue reminder dismissed',
    settings.repeatEnabled
      ? `${invoice.invoiceNumber} — reminder dismissed until ${invoiceLedgerDate(dismissedUntil)}.`
      : `${invoice.invoiceNumber} — reminder dismissed.`,
    'Manual'
  );

  toast(
    settings.repeatEnabled
      ? "Reminder dismissed. VendorFlow will remind you again if it's still unpaid."
      : 'Reminder dismissed.'
  );

  renderReviews();
}


function renderInvoices(){

  renderInvoiceNumberingSettings();

  renderInvoiceEmailTemplateSettings();

  renderOverdueInvoiceSettings();

  installInvoiceNumberingPopup();

  installInvoiceEmailTemplatePopup();

  installOverdueInvoiceSettingsPopup();

  populateInvoiceLedgerFilters();


  const list=
    $('#invoiceList');

  if(!list){
    return;
  }


  const ready=
    invoices.filter(
      invoice=>
        invoiceStatus(invoice)==='Ready to Send'
    );

  const sent=
    invoices.filter(
      invoice=>
        invoiceStatus(invoice)==='Sent'
    );

  const paid=
    invoices.filter(
      invoice=>
        invoiceStatus(invoice)==='Paid'
    );


  if($('#invoiceAllCount')){
    $('#invoiceAllCount').textContent=
      `(${ready.length+sent.length})`;
  }

  if($('#invoiceReadyCount')){
    $('#invoiceReadyCount').textContent=
      `(${ready.length})`;
  }

  if($('#invoiceSentCount')){
    $('#invoiceSentCount').textContent=
      `(${sent.length})`;
  }

  if($('#invoicePaidCount')){
    $('#invoicePaidCount').textContent=
      `(${paid.length})`;
  }


  $$('[data-invoice-filter]')
    .forEach(button=>{

      button.classList.toggle(
        'active',
        button.dataset.invoiceFilter===
          invoiceStatusFilter
      );


      button.onclick=()=>{

        invoiceStatusFilter=
          button.dataset.invoiceFilter;

        renderInvoices();
      };
    });


  const search=
    $('#invoiceSearch');


  if(search){

    search.value=
      invoiceSearchQuery;


    search.oninput=()=>{

      invoiceSearchQuery=
        search.value
          .trim()
          .toLowerCase();

      renderInvoices();
    };
  }


  const toggle=
    $('#toggleInvoiceFilters');


  if(toggle){

    toggle.onclick=()=>{

      $('#invoiceAdvancedFilters')
        ?.classList.toggle(
          'hidden'
        );
    };
  }


  const fields=[
    ['#invoiceFilterCharter','charter'],
    ['#invoiceFilterStudent','student'],
    ['#invoiceFilterService','service'],
    ['#invoiceFilterDateFrom','dateFrom'],
    ['#invoiceFilterDateTo','dateTo'],
    ['#invoiceFilterAmountMin','amountMin'],
    ['#invoiceFilterAmountMax','amountMax']
  ];


  fields.forEach(
    ([selector,key])=>{

      const el=
        $(selector);

      if(!el){
        return;
      }


      el.value=
        invoiceAdvancedFilters[key]||'';


      const update=()=>{

        invoiceAdvancedFilters[key]=
          el.value;

        renderInvoices();
      };


      el.onchange=
        update;


      if(el.type==='number'){
        el.oninput=
          update;
      }
    }
  );


  const clear=
    $('#clearInvoiceFilters');


  if(clear){

    clear.classList.remove(
      'hidden'
    );


    clear.disabled=
      !invoiceLedgerFiltersActive();


    clear.onclick=()=>{

      invoiceStatusFilter='all';

      invoiceSearchQuery='';

      invoiceAdvancedFilters={
        charter:'',
        student:'',
        service:'',
        dateFrom:'',
        dateTo:'',
        amountMin:'',
        amountMax:''
      };

      renderInvoices();
    };
  }


  let visible=
    [...ready,...sent];


  if(invoiceStatusFilter==='ready'){
    visible=ready;
  }

  if(invoiceStatusFilter==='sent'){
    visible=sent;
  }

  if(invoiceStatusFilter==='paid'){
    visible=paid;
  }


  if(invoiceSearchQuery){

    visible=
      visible.filter(
        invoice=>
          invoiceLedgerSearchText(
            invoice
          ).includes(
            invoiceSearchQuery
          )
      );
  }


  visible=
    visible.filter(
      invoiceLedgerMatchesFilters
    );


  visible.sort(
    (a,b)=>
      String(
        b.invoiceDate||''
      ).localeCompare(
        String(a.invoiceDate||'')
      )
  );


  if(!visible.length){

    list.innerHTML=
      '<div class="vf-invoice-ledger-empty">No invoices match these filters.</div>';

    return;
  }


  list.innerHTML=`
    <div class="vf-invoice-ledger-header">

      <span>Invoice</span>
      <span>Charter</span>
      <span>Student</span>
      <span>Service</span>
      <span>Invoice Date</span>
      <span class="right">Amount</span>
      <span>Status</span>

    </div>

    ${visible.map(invoice=>{

      const status=
        invoiceStatus(invoice);

      return `
        <div
          role="button"
          tabindex="0"
          class="vf-invoice-ledger-row"
          data-ledger-invoice="${invoice.id}">

          <span class="vf-ledger-number">
            ${esc(invoice.invoiceNumber||'Invoice')}
          </span>

          <span>
            ${esc(invoice.charterSchoolName||'—')}
          </span>

          <span>
            ${esc(invoice.studentName||'—')}
          </span>

          <span>
            ${esc(invoice.serviceName||'Educational services')}
          </span>

          <span>
            ${esc(invoiceLedgerDate(invoice.invoiceDate)||'—')}
          </span>

          <span class="right">
            ${money(invoice.amount)}
          </span>

          <span class="vf-ledger-status-cell">
            <span class="vf-ledger-status ${invoiceLedgerStatusClass(status)}">
              ${esc(status.toUpperCase())}
            </span>

            ${status==='Sent'
              ? `<button
                  type="button"
                  class="vf-secondary-button vf-ledger-mark-paid"
                  data-mark-paid-invoice="${invoice.id}">
                  Mark Paid
                </button>`
              : ''}

            ${status==='Paid'
              ? `<button
                  type="button"
                  class="vf-secondary-button vf-ledger-mark-unpaid"
                  data-mark-unpaid-invoice="${invoice.id}">
                  Mark Unpaid
                </button>`
              : ''}
          </span>

        </div>
      `;
    }).join('')}
  `;


  $$('[data-ledger-invoice]')
    .forEach(row=>{

      row.onclick=()=>{

        const invoice=
          invoices.find(
            item=>
              item.id===
              row.dataset.ledgerInvoice
          );

        if(invoice){

          showInvoiceLedgerDetail(
            invoice
          );
        }
      };
    });


  $$('[data-mark-paid-invoice]')
    .forEach(button=>{

      button.onclick=event=>{

        event.stopPropagation();

        const invoice=
          invoices.find(
            item=>
              item.id===
              button.dataset.markPaidInvoice
          );

        if(invoice){
          markInvoicePaidManually(invoice);
        }
      };
    });


  $$('[data-mark-unpaid-invoice]')
    .forEach(button=>{

      button.onclick=event=>{

        event.stopPropagation();

        const invoice=
          invoices.find(
            item=>
              item.id===
              button.dataset.markUnpaidInvoice
          );

        if(invoice){
          markInvoiceUnpaidManually(invoice);
        }
      };
    });


  const close=
    $('#closeInvoiceDetail');

  if(close){

    close.onclick=
      closeInvoiceLedgerDetail;
  }


  const modal=
    $('#invoiceDetailModal');

  if(modal){

    modal.onclick=
      event=>{

        if(event.target===modal){
          closeInvoiceLedgerDetail();
        }
      };
  }
}


function renderCertificateCharterOptions(){

  const list=
    $('#certCharterSchoolOptions');

  if(!list){
    return;
  }

  list.innerHTML=
    charterSchools
      .filter(
        charter=>!charter.archived
      )
      .sort(
        (a,b)=>
          String(a.name||'')
            .localeCompare(
              String(b.name||'')
            )
      )
      .map(
        charter=>
          `<option value="${esc(charter.name||'')}"></option>`
      )
      .join('');
}



function wireDashboardStatCards(){

  const cards=[
    {
      value:'#statClasses',
      view:'classes',
      title:'Open Groups'
    },
    {
      value:'#statStudents',
      view:'students',
      title:'Open Students & Services'
    },
    {
      value:'#statReview',
      view:'review',
      title:'Open Needs Review'
    },
    {
      value:'#statHistory',
      view:'history',
      title:'Open VendorFlow Actions'
    }
  ];


  cards.forEach(item=>{

    const value=
      $(item.value);

    if(!value){
      return;
    }


    const card=
      value.closest('.stat');

    if(!card){
      return;
    }


    card.classList.add(
      'vf-clickable-stat'
    );

    card.setAttribute(
      'role',
      'button'
    );

    card.setAttribute(
      'tabindex',
      '0'
    );

    card.setAttribute(
      'title',
      item.title
    );


    const activate=()=>{

      switchView(
        item.view
      );
    };


    card.onclick=
      activate;


    card.onkeydown=
      event=>{

        if(
          event.key==='Enter' ||
          event.key===' '
        ){

          event.preventDefault();

          activate();
        }
      };
  });
}


function renderDashboard(){

  wireDashboardStatCards();

  const activeClasses=
    classes.filter(
      c=>!c.archived
    );

  const readyInvoices=
    invoices.filter(
      invoice=>
        invoiceStatus(invoice)==='Ready to Send'
    );


  const invoicesWaitingForNumbering=
    !profile.invoiceNumberMode
      ? invoiceReadyCertificates()
      : [];


  const needsReviewItems=
    allNeedsReviewItems();


  $('#statClasses').textContent=
    activeClasses.length;


  $('#statStudents').textContent=
    students.filter(
      studentVisibleInServices
    ).length;


  $('#statReview').textContent=
    needsReviewItems.length;


  $('#statHistory').textContent=
    history.length;


  $('#reviewBadge').textContent=
    needsReviewItems.length;


  const count=
    $('#dashboardAttentionCount');

  const title=
    $('#dashboardAttentionTitle');

  const text=
    $('#dashboardAttentionText');

  const reviewButton=
    $('#dashboardAttentionButton');

  const setupButton=
    $('#dashboardSetupButton');

  const tutorialButton=
    $('#dashboardTutorialButton');



  /*
   * --------------------------------------------------------
   * INVOICE NUMBERING SETUP
   *
   * A certificate has reached its billing date, but the
   * vendor has not yet told VendorFlow how invoices should
   * be numbered.
   * --------------------------------------------------------
   */

  if(invoicesWaitingForNumbering.length){

    hide(
      setupButton
    );

    hide(
      tutorialButton
    );


    count.textContent=
      invoicesWaitingForNumbering.length;


    title.textContent=
      'Set your invoice numbering.';


    text.textContent=
      `${invoicesWaitingForNumbering.length} certificate${
        invoicesWaitingForNumbering.length===1?' has':'s have'
      } reached the billing date. Tell VendorFlow whether to continue your existing invoice sequence or create numbers automatically.`;


    show(
      reviewButton
    );


    reviewButton.textContent=
      'Set invoice numbering';


    reviewButton.onclick=()=>{

      switchView(
        'invoices'
      );

      renderInvoiceNumberingSettings();

      $('#invoiceNumberingSettings')
        ?.scrollIntoView({
          behavior:'smooth',
          block:'start'
        });
    };


    renderHistoryInto(
      $('#recentHistory'),
      history.slice(0,6)
    );


    return;
  }


  /*
   * --------------------------------------------------------
   * BRAND-NEW VENDOR
   *
   * Before there is anything operational to review,
   * use this space to guide the vendor to the next best step.
   * --------------------------------------------------------
   */

  /*
   * Setup guidance is only appropriate when there is
   * truly nothing operational that needs attention.
   *
   * Financial/review work always outranks onboarding.
   */
  if(
    !activeClasses.length &&
    !readyInvoices.length &&
    !invoicesWaitingForNumbering.length &&
    !needsReviewItems.length
  ){

    count.textContent='1';


    title.textContent=
      'Welcome to VendorFlow.';


    text.textContent=
      'Start by setting up your first group. Go to Groups to create it, then upload your roster from the Students page.';


    hide(
      reviewButton
    );


    show(
      setupButton
    );


    show(
      tutorialButton
    );


    setupButton.onclick=()=>{

      switchView(
        'classes'
      );
    };


    tutorialButton.onclick=()=>{

      toast(
        'VendorFlow tutorial coming soon.'
      );
    };


    renderHistoryInto(
      $('#recentHistory'),
      history.slice(0,6)
    );


    return;
  }


  /*
   * --------------------------------------------------------
   * NORMAL OPERATION
   * --------------------------------------------------------
   */

  hide(
    setupButton
  );


  hide(
    tutorialButton
  );


  const attentionTotal=
    readyInvoices.length +
    needsReviewItems.length;

  count.textContent=
    attentionTotal;


  if(readyInvoices.length){

    const charterCount=
      new Set(
        readyInvoices.map(
          cert=>
            cert.charterSchoolId ||
            normalizedCharterName(
              cert.charterSchoolName
            )
        )
      ).size;


    title.textContent=
      `${readyInvoices.length} invoice${
        readyInvoices.length===1?' is':'s are'
      } ready to send.`;


    text.textContent=
      `VendorFlow prepared ${
        readyInvoices.length
      } invoice${
        readyInvoices.length===1?'':'s'
      } across ${
        charterCount
      } charter school${
        charterCount===1?'':'s'
      }. Review the finished invoice${
        readyInvoices.length===1?'':'s'
      } and send when ready.`;


    show(
      reviewButton
    );


    reviewButton.textContent=
      'View invoices';


    reviewButton.onclick=()=>{

      switchView(
        'invoices'
      );
    };


  }else if(needsReviewItems.length){

    title.textContent=
      `${needsReviewItems.length} item${needsReviewItems.length===1?'':'s'} need your attention.`;


    text.textContent=
      'VendorFlow has held these items for you instead of making a questionable decision.';


    show(
      reviewButton
    );


    reviewButton.textContent=
      'Review items';


    reviewButton.onclick=()=>{

      switchView(
        'review'
      );
    };


  }else{

    title.textContent=
      `You're all caught up.`;


    text.textContent=
      'VendorFlow has nothing urgent flagged right now.';


    hide(
      reviewButton
    );
  }


  renderHistoryInto(
    $('#recentHistory'),
    history.slice(0,6)
  );
}

function renderClassSelect(){
  let sel=$('#classSelect'),v=sel.value;

  sel.innerHTML='<option value="">Choose a group</option>'+
    classes
      .filter(c=>!c.archived)
      .sort((a,b)=>(a.name||'').localeCompare(b.name||''))
      .map(c=>`<option value="${c.id}">${esc(c.name)}${c.term?' — '+esc(c.term):''}</option>`)
      .join('');

  if(classes.some(c=>c.id===v&&!c.archived))sel.value=v;
  updateRosterUploadTarget();
}


function classIsArchived(classId){

  if(!classId){
    return false;
  }

  const c=
    classes.find(
      item=>item.id===classId
    );

  return Boolean(
    c?.archived
  );
}


function serviceCountsAsActive(service){

  if(!service){
    return false;
  }

  /*
   * Dropped is retained for older imported records.
   * Removed services keep only the obligation already earned,
   * so their adjusted totalPrice still counts financially.
   */
  if(
    String(service.status||'')
      .toLowerCase()==='dropped'
  ){
    return false;
  }

  if(
    service.classId &&
    classIsArchived(service.classId)
  ){
    return false;
  }

  return true;
}


function serviceKeepsStudentVisible(service){

  if(!service){
    return false;
  }

  const status=
    String(service.status||'')
      .trim()
      .toLowerCase();

  if(
    status==='removed' ||
    status==='dropped'
  ){
    return false;
  }

  if(
    service.classId &&
    classIsArchived(service.classId)
  ){
    return false;
  }

  return true;
}


function studentVisibleInServices(student){

  /*
   * An archived student stays hidden, full stop. This used to fall
   * through to the service checks below, which meant a manually
   * added student with no service record kept showing in the
   * directory even after being archived -- the one existing path
   * for this (roster reconciliation) silently did nothing for those
   * students.
   */
  if(vfStudentIsArchived(student)){
    return false;
  }

  /*
   * An active student always shows up in the directory, no matter
   * what any individual service record says -- a bad or stale
   * service status should never be able to hide a real, active
   * student.
   */
  if(student && student.active!==false){
    return true;
  }

  const list=
    services.filter(
      service=>
        service.studentId===student.id
    );

  /*
   * Standalone/manual students with no service yet remain visible.
   */
  if(!list.length){
    return true;
  }

  return list.some(
    serviceKeepsStudentVisible
  );
}


const currentClass=()=>classes.find(c=>c.id===$('#classSelect').value);

async function loadRoster(){
  let c=currentClass();

  if(!c){
    roster=[];
    return;
  }

  let s=await getDocs(
    collection(db,'vendors',user.uid,'classes',c.id,'students')
  );

  roster=s.docs.map(d=>({id:d.id,...d.data()}));
}



let editingClassId='';


function classDateLabel(value){

  const text=
    String(value||'').trim();

  if(!text){
    return '';
  }

  const parts=
    text.split('-')
      .map(Number);

  if(parts.length!==3){
    return text;
  }

  const [year,month,day]=parts;

  const date=
    new Date(
      year,
      month-1,
      day,
      12,0,0,0
    );

  if(Number.isNaN(date.getTime())){
    return text;
  }

  return date.toLocaleDateString(
    undefined,
    {
      month:'short',
      day:'numeric',
      year:'numeric'
    }
  );
}


function addCalendarDays(
  isoDate,
  days
){

  const parts=
    String(isoDate||'')
      .split('-')
      .map(Number);

  if(parts.length!==3){
    return '';
  }

  const [year,month,day]=parts;

  const date=
    new Date(
      year,
      month-1,
      day,
      12,0,0,0
    );

  if(Number.isNaN(date.getTime())){
    return '';
  }

  date.setDate(
    date.getDate()+
    Number(days||0)
  );

  const y=date.getFullYear();

  const m=
    String(date.getMonth()+1)
      .padStart(2,'0');

  const d=
    String(date.getDate())
      .padStart(2,'0');

  return `${y}-${m}-${d}`;
}


/*
 * Grace-day rule:
 *
 * Due Jan 1 + 3 grace days means:
 * Jan 2, Jan 3 and Jan 4 are grace days.
 * Late fee is added Jan 5.
 */
function classLateFeeDate(
  dueDate,
  graceDays
){

  return addCalendarDays(
    dueDate,
    Number(graceDays||0)+1
  );
}


function automaticLateFeeReminderText(
  classRecord,
  dueDate
){

  const lateFee=
    Number(classRecord?.lateFee||0);

  if(
    !(lateFee>0) ||
    !dueDate
  ){
    return '';
  }

  const feeDate=
    classLateFeeDate(
      dueDate,
      classRecord.lateFeeGraceDays
    );

  if(!feeDate){
    return '';
  }

  return (
    `If payment has not been received by the end of `+
    `${classDateLabel(addCalendarDays(feeDate,-1))}, `+
    `a ${money(lateFee)} late fee will be added on `+
    `${classDateLabel(feeDate)}.`
  );
}


function firstClassPaymentDueDate(
  classRecord
){

  if(!classRecord){
    return '';
  }

  if(
    classRecord.paymentSchedule==='Full'
  ){
    return classRecord.paymentDueDate||'';
  }

  if(
    classRecord.paymentSchedule==='Monthly'
  ){

    const installments=
      Array.isArray(
        classRecord.monthlyInstallments
      )
        ? classRecord.monthlyInstallments
        : [];

    return installments
      .filter(item=>item?.dueDate)
      .sort(
        (a,b)=>
          String(a.dueDate)
            .localeCompare(
              String(b.dueDate)
            )
      )[0]?.dueDate ||
      classRecord.monthlyFirstDueDate ||
      '';
  }


  if(
    classRecord.paymentSchedule==='Custom'
  ){

    const installments=
      Array.isArray(
        classRecord.customInstallments
      )
        ? classRecord.customInstallments
        : [];

    return installments
      .filter(item=>item?.dueDate)
      .sort(
        (a,b)=>
          String(a.dueDate)
            .localeCompare(
              String(b.dueDate)
            )
      )[0]?.dueDate || '';
  }

  return '';
}


function classPaymentScheduleHTML(
  classRecord
){

  const schedule=
    classRecord?.paymentSchedule ||
    'Full';

  if(schedule==='Custom'){

    const installments=
      Array.isArray(
        classRecord.customInstallments
      )
        ? [...classRecord.customInstallments]
        : [];

    if(!installments.length){
      return '<span>No installments saved.</span>';
    }

    return `
      <div class="vf-saved-installments">
        ${installments
          .sort(
            (a,b)=>
              String(a.dueDate||'')
                .localeCompare(
                  String(b.dueDate||'')
                )
          )
          .map(
            (item,index)=>`
              <div>
                <span>
                  Payment ${index+1}
                </span>

                <strong>
                  ${money(item.amount)}
                </strong>

                <span>
                  ${esc(
                    classDateLabel(
                      item.dueDate
                    )
                  )}
                </span>
              </div>
            `
          )
          .join('')}
      </div>
    `;
  }

  if(schedule==='Monthly'){

    const installments=
      Array.isArray(
        classRecord.monthlyInstallments
      )
        ? [...classRecord.monthlyInstallments]
        : [];


    if(!installments.length){

      return `
        <span>
          Monthly payment schedule not yet set.
        </span>
      `;
    }


    return `
      <div class="vf-saved-installments">

        ${installments
          .sort(
            (a,b)=>
              String(a.dueDate||'')
                .localeCompare(
                  String(b.dueDate||'')
                )
          )
          .map(
            (item,index)=>`
              <div>

                <span>
                  Payment ${index+1}
                </span>

                <strong>
                  ${money(item.amount)}
                </strong>

                <span>
                  ${esc(
                    classDateLabel(
                      item.dueDate
                    )
                  )}
                </span>

              </div>
            `
          )
          .join('')}

      </div>
    `;
  }

  return `
    <span>
      Pay in full
      ${
        classRecord.paymentDueDate
          ? ' · due '+
            esc(
              classDateLabel(
                classRecord.paymentDueDate
              )
            )
          : ''
      }
    </span>
  `;
}


