/*
 * Loads a saved class into the create-class form exactly like Edit
 * does, then clears editingClassId so Save creates a brand new class
 * instead of overwriting the original. Lets a vendor start a new
 * class from one that's close to what they need instead of typing
 * everything from scratch.
 */
function duplicateSavedClass(classId){
  const original=classes.find(item=>item.id===classId);

  editSavedClass(classId);

  editingClassId='';

  if($('#classCreateFormTitle')){
    $('#classCreateFormTitle').textContent='Duplicate group';
  }

  if($('#className')){
    $('#className').value=
      original?.name
        ? `${original.name} (Copy)`
        : $('#className').value;
    $('#className').focus();
    $('#className').select();
  }

  $('#saveClass').textContent='Save as new group';

  /*
   * A duplicated class needs its own roster -- clear out whatever
   * roster preview/upload state belonged to the class being copied
   * from, so it's obvious this is a fresh class, not a continuation
   * of the original's roster.
   */
  preview=[];
  hide($('#previewCard'));

  if($('#csvStatus')){
    $('#csvStatus').textContent='';
  }

  if($('#csv')){
    $('#csv').value='';
  }

  hide($('#warnings'));

  toast(`Duplicating ${original?.name||'group'} as a new group.`);
}


/*
 * Canonical default text for a class's payment-reminder email body.
 * Kept in one place instead of duplicated at every spot that
 * populates #classReminderBody (previously copy-pasted twice).
 */
function defaultReminderBodyTemplate(){
  return `Hi {{parentName}},

Just a quick reminder that {{amountDue}} is due on {{dueDate}} for {{studentName}} — {{serviceName}}. If you've already sent this in, thank you -- it's possible it just hasn't been recorded yet.

Payment instructions:
{{paymentInstructions}}

{{lateFeeWarning}}

I'm testing a new tool that's helping me keep payments and charter certificates organized, so these emails may look a little different for now. If anything here doesn't look right, please don't hesitate to let me know and I'll check into it more carefully. Thank you for your understanding as I work through this new way of handling payments and charter funds.

Please reach out if you have any questions -- I'm happy to help!

Thank you,
{{businessName}}`;
}

/*
 * Strips the {{lateFeeWarning}} token (and the blank line it sits
 * on) out of a reminder-email body whenever the class currently has
 * no late fee -- so the template editor never shows a token that
 * reads as an active warning line for a class that will never
 * generate one. Left untouched when a late fee IS set, so a
 * vendor's own placement choice for that sentence is never
 * second-guessed.
 */
function reminderBodyForDisplay(
  bodyText,
  hasLateFee
){

  const text=
    String(bodyText||'');

  if(hasLateFee){
    return text;
  }

  return text
    .replace(/\{\{lateFeeWarning\}\}/g,'')
    .replace(/\n{3,}/g,'\n\n')
    .trim();
}

/*
 * True only when `text` is exactly one of the two canonical default
 * reminder bodies (with the {{lateFeeWarning}} token, or without
 * it) -- i.e. the vendor hasn't customized this field at all. Used
 * to decide whether it's safe to auto-update the body as the late
 * fee changes; a genuinely custom message is never touched.
 */
function isDefaultReminderBody(text){

  const t=
    String(text||'').trim();

  const withToken=
    defaultReminderBodyTemplate().trim();

  const withoutToken=
    reminderBodyForDisplay(
      defaultReminderBodyTemplate(),
      false
    ).trim();

  return (
    t===withToken ||
    t===withoutToken
  );
}

/*
 * Keeps #classReminderBody's default text in sync with #classLateFee
 * as the vendor types, so setting a real late fee on a still-open
 * class-create/edit form immediately shows the warning line instead
 * of requiring a save-and-reopen round trip to pick it up. Only
 * acts while the body still matches one of the two canonical
 * defaults (see isDefaultReminderBody) -- a vendor's own custom
 * message is never rewritten out from under them.
 */
function syncReminderBodyLateFeeToken(){

  const bodyEl=
    $('#classReminderBody');

  const feeEl=
    $('#classLateFee');

  if(!bodyEl || !feeEl){
    return;
  }

  if(!isDefaultReminderBody(bodyEl.value)){
    return;
  }

  const hasLateFee=
    Number(feeEl.value||0)>0;

  bodyEl.value=
    hasLateFee
      ? defaultReminderBodyTemplate()
      : reminderBodyForDisplay(
          defaultReminderBodyTemplate(),
          false
        );
}

if($('#classLateFee')){

  $('#classLateFee')
    .addEventListener(
      'input',
      syncReminderBodyLateFeeToken
    );
}


function editSavedClass(
  classId
){

  const c=
    classes.find(
      item=>item.id===classId
    );

  if(!c){
    return toast(
      'Group could not be found.'
    );
  }


  editingClassId=
    c.id;

  clearClassSaveError();

  show($('#classCreateFormWrap'));

  if($('#classCreateFormTitle')){
    $('#classCreateFormTitle').textContent='Edit group';
  }


  $('#className').value=
    c.name||'';


  if($('#classType')){

    $('#classType').value=
      c.classType==='Tutoring'
        ? 'Tutoring'
        : 'Class';
  }


  if($('#classSessionLength')){

    $('#classSessionLength').value=
      Number(c.sessionLengthMinutes||60);
  }


  if($('#classSessionRate')){

    $('#classSessionRate').value=
      Number(c.ratePerSession||0) || '';
  }


  if($('#classInvoiceDaysAfterStart')){

    $('#classInvoiceDaysAfterStart').value=
      (
        c.invoiceDaysAfterStart!==null &&
        c.invoiceDaysAfterStart!==undefined &&
        Number.isFinite(Number(c.invoiceDaysAfterStart))
      )
        ? Number(c.invoiceDaysAfterStart)
        : 14;
  }


  $('#classTerm').value=
    c.term||'';

  $('#classTuition').value=
    Number(c.tuition||0) || '';

  $('#classLocation').value=
    c.location||'';

  $('#classPaymentSchedule').value=
    c.paymentSchedule||'Full';

  $('#classPaymentDueDate').value=
    c.paymentDueDate||'';

  $('#classMonthlyFirstDueDate').value=
    c.monthlyFirstDueDate || '';

  $('#classMonthlyPaymentCount').value=
    Number(c.monthlyPaymentCount||4);

  $('#classLateFee').value=
    Number(c.lateFee||0);

  $('#classLateFeeGraceDays').value=
    Number(c.lateFeeGraceDays||0);

  $('#classVendorAlertDays').value=
    Number(c.vendorAlertDays||0);

  $('#classParentReminderEnabled').checked=
    Boolean(c.parentReminderEnabled);

  $('#classParentReminderDays').value=
    Number(c.parentReminderDays||0);

  $('#classLateFeeChargedReminderEnabled').checked=
    Boolean(c.lateFeeChargedReminderEnabled);

  $('#classLateFeeRemovedReminderEnabled').checked=
    Boolean(c.lateFeeRemovedReminderEnabled);

  $('#classPaymentReceivedEmailEnabled').checked=
    c.paymentReceivedEmailEnabled===undefined
      ? true
      : Boolean(c.paymentReceivedEmailEnabled);

  $('#classCertificateReceivedEmailEnabled').checked=
    c.certificateReceivedEmailEnabled===undefined
      ? true
      : Boolean(c.certificateReceivedEmailEnabled);

  $('#classRecurringReminderEnabled').checked=
    Boolean(c.recurringReminderEnabled);

  $('#classRecurringReminderDays').value=
    Number(c.recurringReminderDays||0);

  $('#classReminderSubject').value=
    c.reminderSubject ||
    'Payment reminder for {{studentName}}';

  $('#classReminderBody').value=
    reminderBodyForDisplay(
      c.reminderBody ||
        defaultReminderBodyTemplate(),
      Number(c.lateFee||0)>0
    );


  const monthlyList=
    $('#classMonthlyInstallments');

  if(monthlyList){
    monthlyList.innerHTML='';
  }


  if(
    c.paymentSchedule==='Monthly'
  ){

    const monthlyInstallments=
      Array.isArray(
        c.monthlyInstallments
      )
        ? c.monthlyInstallments
        : [];


    if(monthlyInstallments.length){

      monthlyInstallments.forEach(
        item=>
          addClassMonthlyInstallment(
            Number(item.amount||0)
              .toFixed(2),
            item.dueDate
          )
      );

    }else{

      rebuildClassMonthlyInstallments();
    }
  }


  const list=
    $('#classCustomInstallments');

  if(list){
    list.innerHTML='';
  }


  if(
    c.paymentSchedule==='Custom'
  ){

    const installments=
      Array.isArray(
        c.customInstallments
      )
        ? c.customInstallments
        : [];

    if(installments.length){

      installments.forEach(
        item=>
          addClassCustomInstallment(
            item.amount,
            item.dueDate
          )
      );

    }else{

      resetClassCustomInstallments();
    }

  }else{

    resetClassCustomInstallments();
  }


  updateClassTypeUI();
  updateClassPaymentUI();
  updateClassParentReminderUI();
  updateClassCustomInstallmentTotal();


  $('#saveClass').textContent=
    'Save changes';


  $('#className')
    .scrollIntoView({
      behavior:'smooth',
      block:'center'
    });

  $('#className').focus();


  toast(
    `Editing ${c.name}.`
  );
}



function clearClassSaveError(){

  const box=
    $('#classSaveError');

  if(!box){
    return;
  }

  box.textContent='';
  hide(box);
}


function showClassSaveError(
  message
){

  const box=
    $('#classSaveError');

  if(!box){
    toast(message);
    return;
  }

  box.textContent=
    String(message||'');

  show(box);

  box.scrollIntoView({
    behavior:'smooth',
    block:'nearest'
  });
}


function classTuitionAmount(){

  return Number(
    $('#classTuition')?.value || 0
  );
}



function classMonthlyInstallmentRows(){

  return [
    ...document.querySelectorAll(
      '#classMonthlyInstallments .vf-monthly-installment-row'
    )
  ];
}


function monthlyInstallmentDate(
  firstDate,
  monthOffset
){

  const parts=
    String(firstDate||'')
      .split('-')
      .map(Number);

  if(parts.length!==3){
    return '';
  }

  const [year,month,day]=parts;

  if(
    !year ||
    !month ||
    !day
  ){
    return '';
  }

  const targetMonthIndex=
    (month-1)+Number(monthOffset||0);

  const targetYear=
    year+
    Math.floor(targetMonthIndex/12);

  const normalizedMonth=
    ((targetMonthIndex%12)+12)%12;

  const lastDay=
    new Date(
      targetYear,
      normalizedMonth+1,
      0,
      12,0,0,0
    ).getDate();

  const targetDay=
    Math.min(
      day,
      lastDay
    );

  return (
    `${targetYear}-`+
    `${String(normalizedMonth+1).padStart(2,'0')}-`+
    `${String(targetDay).padStart(2,'0')}`
  );
}


function generatedMonthlyInstallments(){

  const tuition=
    classTuitionAmount();

  const firstDate=
    $('#classMonthlyFirstDueDate')
      ?.value || '';

  const count=
    Math.max(
      0,
      Math.floor(
        Number(
          $('#classMonthlyPaymentCount')
            ?.value || 0
        )
      )
    );

  if(
    !(tuition>0) ||
    !firstDate ||
    !(count>0)
  ){
    return [];
  }


  /*
   * Work in pennies so installment totals always
   * equal tuition exactly.
   */
  const totalCents=
    Math.round(
      tuition*100
    );

  const baseCents=
    Math.floor(
      totalCents/count
    );

  let extraPennies=
    totalCents-
    baseCents*count;


  return Array.from(
    {
      length:count
    },
    (_,index)=>{

      const cents=
        baseCents+
        (
          extraPennies>0
            ? 1
            : 0
        );

      if(extraPennies>0){
        extraPennies--;
      }

      return {
        amount:
          cents/100,

        dueDate:
          monthlyInstallmentDate(
            firstDate,
            index
          )
      };
    }
  );
}


function addClassMonthlyInstallment(
  amount='',
  dueDate=''
){

  const list=
    $('#classMonthlyInstallments');

  if(!list){
    return;
  }

  const row=
    document.createElement('div');

  row.className=
    'vf-custom-installment-row vf-monthly-installment-row';

  row.innerHTML=`
    <label class="vf-field-label">
      <span>Amount</span>
      <div class="vf-money-field">
        <span>$</span>
        <input
          class="input"
          type="number"
          min="0"
          step=".01"
          data-monthly-installment-amount
          value="${esc(amount)}">
      </div>
    </label>

    <label class="vf-field-label">
      <span>Due date</span>
      <input
        class="input"
        type="date"
        data-monthly-installment-date
        value="${esc(dueDate)}">
    </label>
  `;

  list.appendChild(row);


  row.querySelector(
    '[data-monthly-installment-amount]'
  )?.addEventListener(
    'input',
    ()=>{

      clearClassSaveError();
      updateClassMonthlyInstallmentTotal();
    }
  );


  row.querySelector(
    '[data-monthly-installment-date]'
  )?.addEventListener(
    'input',
    clearClassSaveError
  );
}


function readClassMonthlyInstallments(){

  return classMonthlyInstallmentRows()
    .map(
      row=>({
        amount:
          Number(
            row.querySelector(
              '[data-monthly-installment-amount]'
            )?.value || 0
          ),

        dueDate:
          row.querySelector(
            '[data-monthly-installment-date]'
          )?.value || ''
      })
    );
}


function updateClassMonthlyInstallmentTotal(){

  const box=
    $('#classMonthlyInstallmentTotal');

  if(!box){
    return;
  }

  const tuition=
    classTuitionAmount();

  const installments=
    readClassMonthlyInstallments();

  const total=
    installments.reduce(
      (sum,item)=>
        sum+
        Number(item.amount||0),
      0
    );

  box.classList.remove(
    'vf-installment-total-good',
    'vf-installment-total-bad'
  );


  if(!installments.length){

    box.textContent=
      'Enter the first payment date and number of payments.';

    return;
  }


  if(
    tuition>0 &&
    Math.abs(total-tuition)<0.005
  ){

    box.classList.add(
      'vf-installment-total-good'
    );

    box.textContent=
      `Payment total: $${total.toFixed(2)} — matches tuition.`;

    return;
  }


  box.classList.add(
    'vf-installment-total-bad'
  );

  box.textContent=
    `Payment total: $${total.toFixed(2)} · Tuition: $${tuition.toFixed(2)}`;
}


function rebuildClassMonthlyInstallments(){

  const list=
    $('#classMonthlyInstallments');

  if(!list){
    return;
  }

  list.innerHTML='';


  const generated=
    generatedMonthlyInstallments();


  generated.forEach(
    item=>
      addClassMonthlyInstallment(
        item.amount.toFixed(2),
        item.dueDate
      )
  );


  updateClassMonthlyInstallmentTotal();
}


function validateClassMonthlyInstallments(){

  const tuition=
    classTuitionAmount();

  const firstDate=
    $('#classMonthlyFirstDueDate')
      ?.value || '';

  const count=
    Math.floor(
      Number(
        $('#classMonthlyPaymentCount')
          ?.value || 0
      )
    );


  if(!firstDate){

    showClassSaveError(
      'Enter the first monthly payment due date.'
    );

    return null;
  }


  if(!(count>0)){

    showClassSaveError(
      'Enter the number of monthly payments.'
    );

    return null;
  }


  const installments=
    readClassMonthlyInstallments();


  if(
    installments.length!==count
  ){

    showClassSaveError(
      'The monthly payment schedule is incomplete. Re-enter the first payment date or number of payments.'
    );

    return null;
  }


  if(
    installments.some(
      item=>
        !(item.amount>0) ||
        !item.dueDate
    )
  ){

    showClassSaveError(
      'Every monthly payment needs both an amount and a due date.'
    );

    return null;
  }


  const total=
    installments.reduce(
      (sum,item)=>
        sum+
        Number(item.amount||0),
      0
    );


  if(
    !tuition ||
    Math.abs(total-tuition)>=0.005
  ){

    showClassSaveError(
      `Monthly payments total $${total.toFixed(2)}, but tuition is $${tuition.toFixed(2)}. Adjust the amounts so they match exactly.`
    );

    return null;
  }


  return installments;
}


function classCustomInstallmentRows(){

  return [
    ...document.querySelectorAll(
      '#classCustomInstallments .vf-custom-installment-row'
    )
  ];
}


function updateClassCustomInstallmentTotal(){

  const box=
    $('#classCustomInstallmentTotal');

  if(!box){
    return;
  }

  const tuition=
    classTuitionAmount();

  const total=
    classCustomInstallmentRows()
      .reduce(
        (sum,row)=>
          sum+
          Number(
            row.querySelector(
              '[data-installment-amount]'
            )?.value || 0
          ),
        0
      );

  const difference=
    tuition-total;

  box.classList.remove(
    'vf-installment-total-good',
    'vf-installment-total-bad'
  );

  if(!tuition && !total){

    box.textContent=
      'Enter tuition above to compare the installment total.';

    return;
  }

  if(Math.abs(difference)<0.005){

    box.classList.add(
      'vf-installment-total-good'
    );

    box.textContent=
      `Installment total: $${total.toFixed(2)} — matches tuition.`;

    return;
  }

  box.classList.add(
    'vf-installment-total-bad'
  );

  box.textContent=
    `Installment total: $${total.toFixed(2)} · Tuition: $${tuition.toFixed(2)}`;
}


function addClassCustomInstallment(
  amount='',
  dueDate=''
){

  const list=
    $('#classCustomInstallments');

  if(!list){
    return;
  }

  const row=
    document.createElement('div');

  row.className=
    'vf-custom-installment-row';

  row.innerHTML=`
    <label class="vf-field-label">
      <span>Amount</span>
      <div class="vf-money-field">
        <span>$</span>
        <input
          class="input"
          type="number"
          min="0"
          step=".01"
          data-installment-amount
          value="${esc(amount)}">
      </div>
    </label>

    <label class="vf-field-label">
      <span>Due date</span>
      <input
        class="input"
        type="date"
        data-installment-date
        value="${esc(dueDate)}">
    </label>

    <button
      type="button"
      class="vf-remove-installment"
      data-remove-installment>
      Remove
    </button>
  `;

  list.appendChild(row);

  row.querySelector(
    '[data-installment-amount]'
  )?.addEventListener(
    'input',
    ()=>{

      clearClassSaveError();
      updateClassCustomInstallmentTotal();
    }
  );


  row.querySelector(
    '[data-installment-date]'
  )?.addEventListener(
    'input',
    clearClassSaveError
  );

  row.querySelector(
    '[data-remove-installment]'
  )?.addEventListener(
    'click',
    ()=>{

      row.remove();

      if(
        classCustomInstallmentRows()
          .length===0
      ){
        addClassCustomInstallment();
      }

      updateClassCustomInstallmentTotal();
    }
  );

  updateClassCustomInstallmentTotal();
}


function resetClassCustomInstallments(){

  const list=
    $('#classCustomInstallments');

  if(!list){
    return;
  }

  list.innerHTML='';

  addClassCustomInstallment();
  addClassCustomInstallment();

  updateClassCustomInstallmentTotal();
}


function readClassCustomInstallments(){

  return classCustomInstallmentRows()
    .map(row=>({
      amount:Number(
        row.querySelector(
          '[data-installment-amount]'
        )?.value || 0
      ),
      dueDate:
        row.querySelector(
          '[data-installment-date]'
        )?.value || ''
    }));
}


function validateClassCustomInstallments(){

  const tuition=
    classTuitionAmount();

  const installments=
    readClassCustomInstallments();

  if(!installments.length){

    showClassSaveError(
      'Add at least one custom installment before saving.'
    );

    return null;
  }

  if(
    installments.some(
      item=>
        !(item.amount>0) ||
        !item.dueDate
    )
  ){

    showClassSaveError(
      'Each installment needs both an amount and a due date.'
    );

    return null;
  }

  const total=
    installments.reduce(
      (sum,item)=>sum+item.amount,
      0
    );

  if(
    !tuition ||
    Math.abs(total-tuition)>=0.005
  ){

    showClassSaveError(
      `Installments total $${total.toFixed(2)}, but tuition is $${tuition.toFixed(2)}. Adjust the installment amounts so they match exactly.`
    );

    return null;
  }

  return installments;
}



function selectedClassIsTutoring(){

  return (
    $('#classType')?.value ===
    'Tutoring'
  );
}


function updateClassTypeUI(){

  const tutoring=
    selectedClassIsTutoring();

  const settings=
    $('#classTutoringSettings');

  const tuition=
    $('#classTuition');

  const payment=
    $('#classPaymentSchedule');


  if(settings){

    tutoring
      ? show(settings)
      : hide(settings);
  }


  /*
   * Existing regular-class payment behavior is preserved.
   * Tutoring has no predetermined tuition obligation.
   */
  if(tuition){

    tuition.disabled=
      tutoring;

    tuition.placeholder=
      tutoring
        ? 'No fixed tuition for tutoring'
        : 'Tuition';

    if(tutoring){
      tuition.value='';
    }
  }


  if(payment){

    payment.disabled=
      tutoring;
  }


  const paymentSection=
    payment?.closest(
      '.vf-class-section'
    );


  if(paymentSection){

    tutoring
      ? hide(paymentSection)
      : show(paymentSection);
  }


  const options=
    document.querySelector(
      '.vf-class-options'
    );


  if(options){

    tutoring
      ? hide(options)
      : show(options);
  }
}


if($('#classType')){

  $('#classType')
    .addEventListener(
      'change',
      ()=>{

        clearClassSaveError();
        updateClassTypeUI();
        updateClassPaymentUI();
      }
    );


  updateClassTypeUI();
}


function updateClassPaymentUI(){

  const schedule=
    $('#classPaymentSchedule')?.value ||
    'Full';

  const dueDate=
    $('#classDueDateWrap');

  const monthlySetup=
    $('#classMonthlySetupWrap');

  const monthlySchedule=
    $('#classMonthlyInstallmentsWrap');

  const custom=
    $('#classCustomInstallmentsWrap');


  if(schedule==='Monthly'){

    hide(dueDate);
    show(monthlySetup);
    show(monthlySchedule);
    hide(custom);

    if(
      classMonthlyInstallmentRows()
        .length===0
    ){
      rebuildClassMonthlyInstallments();
    }

    updateClassMonthlyInstallmentTotal();

  }else if(schedule==='Custom'){

    hide(dueDate);
    hide(monthlySetup);
    hide(monthlySchedule);
    show(custom);

    if(
      classCustomInstallmentRows()
        .length===0
    ){
      resetClassCustomInstallments();
    }

    updateClassCustomInstallmentTotal();

  }else{

    show(dueDate);
    hide(monthlySetup);
    hide(monthlySchedule);
    hide(custom);
  }
}


