function renderRoster(){
  let c=currentClass();

  if(!c){
    show($('#rosterEmpty'));
    hide($('#rosterWrap'));
    hide($('#addStudent'));

    /*
     * #archiveClass now lives inside the group details card, which is
     * only rendered when a group is selected -- so it is legitimately
     * absent here. Null-guarded rather than removed, because this
     * function runs on every group change and show(null) throws.
     */
    if($('#archiveClass'))hide($('#archiveClass'));
    return;
  }

  show($('#addStudent'));
  if($('#archiveClass'))show($('#archiveClass'));

  if(!roster.length){
    $('#rosterEmpty').textContent='No saved roster yet.';
    show($('#rosterEmpty'));
    hide($('#rosterWrap'));
    return;
  }

  hide($('#rosterEmpty'));
  show($('#rosterWrap'));

  $('#rosterBody').innerHTML=
    roster.map(s=>
      `<tr>
        <td>${esc(s.studentName)}</td>
        <td>${esc(s.parentName)}</td>
        <td>${esc(s.parentEmail)}</td>
        <td>${esc(s.parentPhone||'')}</td>
        <td>${esc(s.status)}</td>
        <td>${esc(s.grade)}</td>
        <td>
          <div class="vf-roster-actions">

            <button
              class="primary"
              data-edit-student="${s.id}">
              Edit
            </button>

            <button
              class="vf-cert-delete-button"
              data-delete-student="${s.id}">
              Delete
            </button>

          </div>
        </td>
      </tr>`
    ).join('');

  $$('[data-edit-student]').forEach(
    b=>b.onclick=()=>editRosterStudent(b.dataset.editStudent)
  );

  $$('[data-delete-student]').forEach(
    b=>b.onclick=()=>deleteRosterStudent(b.dataset.deleteStudent)
  );

}


async function dropStudentFromClass(id){

  const s=
    roster.find(x=>x.id===id);

  const c=
    currentClass();

  if(!s || !c){
    return;
  }

  const ok=
    confirm(
      `Remove ${s.studentName} from ${c.name}?\n\n` +
      `VendorFlow will mark this enrollment Dropped. ` +
      `The student's payment, certificate and account history will NOT be deleted.`
    );

  if(!ok){
    return;
  }

  await updateDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'classes',
      c.id,
      'students',
      id
    ),
    {
      status:'Dropped',
      droppedAt:serverTimestamp(),
      updatedAt:serverTimestamp()
    }
  );

  await loadRoster();

  const count=
    roster.filter(active).length;

  await updateDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'classes',
      c.id
    ),
    {
      activeStudentCount:count,
      rosterCount:roster.length
    }
  );

  /*
   * Preserve the core student and all financial records.
   * If a linked class service exists, mark only that
   * service/enrollment inactive rather than deleting it.
   */
  const core=
    students.find(
      x=>
        normalizedName(x.studentName)===
        normalizedName(s.studentName)
    );

  if(core){

    const linked=
      services.filter(
        service=>
          service.studentId===core.id &&
          service.classId===c.id &&
          norm(service.status)!=='dropped'
      );

    for(const service of linked){

      await updateDoc(
        doc(
          db,
          'vendors',
          user.uid,
          'services',
          service.id
        ),
        {
          status:'Dropped',
          droppedAt:serverTimestamp(),
          updatedAt:serverTimestamp()
        }
      );
    }
  }

  await log(
    'Student dropped from group',
    `${s.studentName} removed from ${c.name}. Financial history preserved.`,
    'Manual'
  );

  await refreshAll();

  $('#classSelect').value=c.id;

  await loadRoster();
  renderRoster();
  updateRosterUploadTarget();

  toast(`${s.studentName} marked Dropped.`);
}


async function deleteRosterStudent(id){

  const s=
    roster.find(x=>x.id===id);

  const c=
    currentClass();

  if(!s || !c){
    return;
  }

  const core=
    students.find(
      x=>
        normalizedName(x.studentName)===
        normalizedName(s.studentName)
    );

  const hasLinkedService=
    core
      ? services.some(
          service=>
            service.studentId===core.id &&
            service.classId===c.id &&
            norm(service.status)!=='dropped'
        )
      : false;

  if(hasLinkedService){

    const dropInstead=
      confirm(
        `${s.studentName} already has payment or certificate activity in ${c.name}, ` +
        `so VendorFlow can't permanently delete this roster entry -- that history needs to stay intact.\n\n` +
        `Click OK to mark this enrollment Dropped instead (keeps the history, removes them from the active roster). ` +
        `Click Cancel to do nothing.`
      );

    if(dropInstead){
      await dropStudentFromClass(id);
    }

    return;
  }

  const ok=
    confirm(
      `Permanently delete ${s.studentName} from ${c.name}'s roster?\n\n` +
      `This removes the roster entry completely -- use this to fix a mistake, ` +
      `such as an accidental duplicate. There's no payment or certificate history ` +
      `tied to this entry yet, so nothing else will be affected.`
    );

  if(!ok){
    return;
  }

  await deleteDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'classes',
      c.id,
      'students',
      id
    )
  );

  await loadRoster();

  const count=
    roster.filter(active).length;

  await updateDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'classes',
      c.id
    ),
    {
      activeStudentCount:count,
      rosterCount:roster.length
    }
  );

  await log(
    'Roster entry deleted',
    `${s.studentName} was permanently removed from ${c.name}'s roster.`,
    'Manual'
  );

  await refreshAll();

  $('#classSelect').value=c.id;

  await loadRoster();
  renderRoster();
  updateRosterUploadTarget();

  toast(`${s.studentName} deleted from the roster.`);
}


async function changeStatus(id){
  let s=roster.find(x=>x.id===id);

  let n=prompt(
    `Status for ${s.studentName}:`,
    s.status
  );

  if(!n)return;

  let c=currentClass();

  await updateDoc(
    doc(db,'vendors',user.uid,'classes',c.id,'students',id),
    {status:n}
  );

  await loadRoster();

  let count=roster.filter(active).length;

  await updateDoc(
    doc(db,'vendors',user.uid,'classes',c.id),
    {activeStudentCount:count}
  );

  await log(
    'Student status changed',
    `${s.studentName}: ${s.status} → ${n} in ${c.name}.`,
    'Manual'
  );

  await refreshAll();

  $('#classSelect').value=c.id;
  updateRosterUploadTarget();

  await loadRoster();
  renderRoster();
}




function updateStudentStatusHelp(){

  const box=
    $('#studentStatusHelp');

  if(!box){
    return;
  }

  const status=
    $('#ss').value;


  if(status==='Inactive'){

    box.className=
      'vf-student-status-help vf-status-warning';

    box.innerHTML=`
      <strong>Inactive:</strong>
      The student is no longer participating, but the existing
      group payment obligation remains.
    `;

    return;
  }


  if(status==='Removed'){

    box.className=
      'vf-student-status-help vf-status-danger';

    box.innerHTML=`
      <strong>Removed:</strong>
      The student leaves the active group roster and VendorFlow
      removes the remaining unpaid group obligation.
      Prior payments, certificates and history are preserved.
    `;

    return;
  }


  box.className=
    'vf-student-status-help vf-status-normal';

  box.innerHTML=`
    <strong>Active:</strong>
    The student is participating and the normal group
    payment obligation remains.
  `;
}


if($('#ss')){

  $('#ss').addEventListener(
    'change',
    updateStudentStatusHelp
  );
}


let vfPendingStudentNamePrefill='';


/*
 * Entry point for the "Add student" button on a Notifications card
 * for a certificate that has no matching student yet. A student in
 * VendorFlow always belongs to a class roster, so this can't create
 * the student directly -- it sends the vendor to Class Rosters with
 * the extracted name ready to drop into the add-student form the
 * moment they pick (or have already picked) the right class.
 */
function openAddStudentForCertificate(certificateId){

  const cert=
    certs.find(
      item=>item.id===certificateId
    );

  if(!cert){
    return toast(
      'Certificate could not be found.'
    );
  }

  vfPendingStudentNamePrefill=
    String(cert.student||'').trim();

  switchView('classes');

  const hasClassSelected=
    Boolean($('#classSelect')?.value);

  if(hasClassSelected){
    $('#addStudent')?.click();
  }else{
    toast(
      'Choose the group this student belongs to, then click "Add student manually" to add them.'
    );
  }
}


/*
 * Same idea as openAddStudentForCertificate, for a payment that was
 * imported without a matched student.
 */
function openAddStudentForPayment(paymentId){

  const payment=
    payments.find(
      item=>item.id===paymentId
    );

  if(!payment){
    return toast(
      'Payment could not be found.'
    );
  }

  vfPendingStudentNamePrefill=
    String(
      payment.payer ||
      payment.student ||
      ''
    ).trim();

  switchView('classes');

  const hasClassSelected=
    Boolean($('#classSelect')?.value);

  if(hasClassSelected){
    $('#addStudent')?.click();
  }else{
    toast(
      'Choose the group this student belongs to, then click "Add student manually" to add them. Afterward, come back to Notifications to match this payment.'
    );
  }
}


/*
 * Attaches an already-existing student to a payment that was
 * imported with "connect later" checked (or otherwise saved with no
 * student match). Clears the Notifications flag automatically, since
 * paymentAttentionIssue() only fires while studentId is empty.
 */
async function dismissCertificateMatchWarning(certificateId){

  const cert=
    certs.find(
      item=>item.id===certificateId
    );

  if(!cert){
    return toast(
      'Could not find that certificate.'
    );
  }

  await updateDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'certificates',
      certificateId
    ),
    {
      dismissedMatchWarning:true,
      updatedAt:serverTimestamp()
    }
  );

  await log(
    'Certificate match warning dismissed',
    `${cert.student||'A certificate'} — ${money(cert.amount)} — VendorFlow will stop asking for a student match on this one.`,
    'Manual'
  );

  await refreshAll();

  toast('Dismissed. You can still match it manually from the certificate itself later.');
}


async function dismissPaymentMatchWarning(paymentId){

  const payment=
    payments.find(
      item=>item.id===paymentId
    );

  if(!payment){
    return toast(
      'Could not find that payment.'
    );
  }

  await updateDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'payments',
      paymentId
    ),
    {
      dismissedMatchWarning:true,
      updatedAt:serverTimestamp()
    }
  );

  await log(
    'Payment match warning dismissed',
    `${money(payment.amount)} payment (${payment.payer||payment.student||'unmatched'}) — VendorFlow will stop asking for a student match on this one.`,
    'Manual'
  );

  await refreshAll();

  toast('Dismissed. You can still match it manually from the payment itself later.');
}


async function matchStudentToPendingPayment(paymentId,studentId){

  const payment=
    payments.find(
      item=>item.id===paymentId
    );

  const student=
    students.find(
      item=>item.id===studentId
    );

  if(!payment || !student){
    return toast(
      'Could not find that payment or student.'
    );
  }

  await updateDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'payments',
      paymentId
    ),
    {
      studentId:student.id,
      student:student.studentName||'',
      parentName:student.parentName||'',
      parentEmail:student.parentEmail||'',
      matchedBy:'Vendor matched from Notifications',
      updatedAt:serverTimestamp()
    }
  );

  await log(
    'Payment matched to student',
    `${money(payment.amount)} payment matched to ${student.studentName||'student'}.`,
    'Manual'
  );

  await refreshAll();

  toast('Payment matched.');
}


function resetRosterStudentForm(){

  editingRosterStudentId=null;

  $('#sf').value='';
  $('#sl').value='';
  $('#pn').value='';
  $('#pe').value='';
  $('#pp').value='';
  $('#sg').value='';
  $('#ss').value='Active';

  updateStudentStatusHelp();

  $('#saveStudent').textContent=
    'Save student';
}


function editRosterStudent(id){

  const s=
    roster.find(
      student=>student.id===id
    );

  if(!s){
    return;
  }

  editingRosterStudentId=id;

  $('#sf').value=
    s.studentFirst||'';

  $('#sl').value=
    s.studentLast||'';

  $('#pn').value=
    s.parentName||'';

  $('#pe').value=
    s.parentEmail||'';

  $('#pp').value=
    s.parentPhone||'';

  $('#sg').value=
    s.grade||'';

  const oldStatus=
    String(s.status||'Active')
      .trim()
      .toLowerCase();

  $('#ss').value=
    oldStatus==='active'
      ? 'Active'
      : (
          oldStatus==='removed' ||
          oldStatus==='dropped'
            ? 'Removed'
            : 'Inactive'
        );

  updateStudentStatusHelp();

  $('#saveStudent').textContent=
    'Save changes';

  show(
    $('#studentForm')
  );

  $('#sf').focus();
}


$('#cancelStudent').onclick=()=>{

  resetRosterStudentForm();

  hide(
    $('#studentForm')
  );
};


/*
 * The Students action row.
 *
 * Uploading a roster and reconciling one are things a vendor does
 * occasionally, so they open on demand instead of sitting on the page
 * permanently pushing the directory below the fold. Each one closes
 * the others, so only one panel is ever open.
 */
function vfCloseStudentPanels(){

  [
    '#rosterCsvCard',
    '#previewCard',
    '#rosterReconcileCard',
    '#coreStudentForm'
  ].forEach(selector=>{

    const panel=$(selector);

    if(panel){
      panel.classList.add('hidden');
    }
  });
}


/*
 * The roster CSV upload moved here from Class Rosters, but the code
 * behind it still asks currentClass() which group to import into, and
 * currentClass() reads #classSelect over on that page. Rather than
 * rewrite that shared path -- it is the same code that saves the
 * roster, so getting it wrong loses student data -- this picker
 * mirrors #classSelect: same options, cloned straight from it, and
 * choosing here sets the value there and fires its change handler, so
 * the app behaves exactly as if the vendor had picked the group on the
 * old page.
 */
function vfSyncRosterUploadGroup(){

  const source=$('#classSelect');
  const picker=$('#rosterUploadGroup');

  if(!source || !picker){
    return;
  }

  picker.innerHTML=source.innerHTML;
  picker.value=source.value;
}


if($('#vfRosterUploadToggle')){

  $('#vfRosterUploadToggle').onclick=()=>{

    const card=$('#rosterCsvCard');

    if(!card){
      return;
    }

    const wasOpen=!card.classList.contains('hidden');

    vfCloseStudentPanels();

    if(wasOpen){
      return;
    }

    vfSyncRosterUploadGroup();
    card.classList.remove('hidden');
    card.scrollIntoView({behavior:'smooth',block:'nearest'});
  };
}


if($('#rosterUploadGroup')){

  $('#rosterUploadGroup').onchange=()=>{

    const source=$('#classSelect');
    const picker=$('#rosterUploadGroup');

    if(!source || !picker){
      return;
    }

    source.value=picker.value;
    source.dispatchEvent(new Event('change'));
  };
}


if($('#vfRosterReconcileToggle')){

  $('#vfRosterReconcileToggle').onclick=()=>{

    const card=$('#rosterReconcileCard');

    if(!card){
      return;
    }

    const wasOpen=!card.classList.contains('hidden');

    vfCloseStudentPanels();

    if(wasOpen){
      return;
    }

    card.classList.remove('hidden');
    card.scrollIntoView({behavior:'smooth',block:'nearest'});
  };
}


/*
 * Added as a listener rather than folded into #addCoreStudent's own
 * onclick, so that handler stays exactly as it was.
 */
if($('#addCoreStudent')){

  $('#addCoreStudent').addEventListener('click',()=>{

    ['#rosterCsvCard','#previewCard','#rosterReconcileCard']
      .forEach(selector=>$(selector)?.classList.add('hidden'));
  });
}


$('#addStudent').onclick=()=>{

  resetRosterStudentForm();

  show(
    $('#studentForm')
  );

  if(vfPendingStudentNamePrefill){

    const nameParts=
      vfPendingStudentNamePrefill.split(/\s+/);

    $('#sf').value=nameParts[0]||'';
    $('#sl').value=nameParts.slice(1).join(' ')||'';

    vfPendingStudentNamePrefill='';

    $('#sl').focus();
  }else{
    $('#sf').focus();
  }
};


async function applyRosterFinancialStatus(
  classRecord,
  rosterRecord,
  newStatus
){

  const coreId=
    rosterRecord?.coreStudentId ||
    students.find(
      student=>
        normalizedName(student.studentName)===
        normalizedName(rosterRecord.studentName)
    )?.id ||
    '';

  if(!coreId){
    return;
  }


  const coreStudent=
    students.find(
      student=>student.id===coreId
    );

  const linked=
    services.filter(
      service=>
        service.studentId===coreId &&
        service.classId===classRecord.id
    );


  if(!linked.length){
    return;
  }


  /*
   * Active / Inactive:
   * participation changes but obligation remains intact.
   */
  if(
    newStatus==='Active' ||
    newStatus==='Inactive'
  ){

    for(const service of linked){

      let update={
        status:newStatus,
        updatedAt:serverTimestamp()
      };


      /*
       * If a Removed student is restored, restore the
       * original class price as well.
       */
      if(
        String(service.status||'')
          .toLowerCase()==='removed' &&
        Number(service.originalTotalPrice)>0
      ){

        update.totalPrice=
          Number(service.originalTotalPrice);

        update.waivedAmount=0;

        update.financialDisposition=
          'Normal obligation restored';
      }


      await setDoc(
        doc(
          db,
          'vendors',
          user.uid,
          'services',
          service.id
        ),
        update,
        {
          merge:true
        }
      );
    }

    return;
  }


  if(newStatus!=='Removed'){
    return;
  }


  /*
   * REMOVED:
   *
   * Waive only the REMAINING UNPAID portion.
   * This avoids creating an artificial refund for money
   * the family already paid or funded with a certificate.
   */
  const account=
    coreStudent
      ? studentAccountTotals(coreStudent)
      : null;

  let remainingUnpaid=
    Math.max(
      0,
      Number(
        account?.parentBalance||0
      )
    );


  for(const service of linked){

    const currentPrice=
      Number(service.totalPrice||0);

    const originalPrice=
      Number(
        service.originalTotalPrice ||
        currentPrice
      );

    const waiver=
      Math.min(
        currentPrice,
        remainingUnpaid
      );

    const adjustedPrice=
      Math.max(
        0,
        currentPrice-waiver
      );


    remainingUnpaid=
      Math.max(
        0,
        remainingUnpaid-waiver
      );


    await setDoc(
      doc(
        db,
        'vendors',
        user.uid,
        'services',
        service.id
      ),
      {
        status:'Removed',

        originalTotalPrice:
          originalPrice,

        totalPrice:
          adjustedPrice,

        waivedAmount:
          Number(service.waivedAmount||0)+waiver,

        financialDisposition:
          'Remaining unpaid obligation removed',

        removedAt:
          serverTimestamp(),

        updatedAt:
          serverTimestamp()
      },
      {
        merge:true
      }
    );
  }
}


$('#saveStudent').onclick=async()=>{

  const c=
    currentClass();

  const sf=
    $('#sf').value.trim();

  const sl=
    $('#sl').value.trim();


  if(
    !c ||
    !sf ||
    !sl
  ){
    return toast(
      'Enter student first and last name.'
    );
  }


  const requestedStatus=
    $('#ss').value;


  if(
    editingRosterStudentId &&
    requestedStatus==='Inactive'
  ){

    const ok=
      confirm(
        'Mark this student Inactive?\n\n' +
        'The student will no longer be participating, but their ' +
        'existing group payment obligation will remain.'
      );

    if(!ok){
      return;
    }
  }


  if(
    editingRosterStudentId &&
    requestedStatus==='Removed'
  ){

    const ok=
      confirm(
        'Remove this student from the group?\n\n' +
        'VendorFlow will remove the remaining unpaid group obligation. ' +
        'Prior payments, certificates and history will be preserved.'
      );

    if(!ok){
      return;
    }
  }


  const data={

    studentFirst:sf,

    studentLast:sl,

    studentName:
      `${sf} ${sl}`,

    parentName:
      $('#pn').value.trim(),

    parentEmail:
      $('#pe').value.trim(),

    parentPhone:
      $('#pp').value.trim(),

    grade:
      $('#sg').value.trim(),

    status:
      $('#ss').value,

    source:'Manual',

    updatedAt:
      serverTimestamp()
  };


  if(editingRosterStudentId){

    const existing=
      roster.find(
        student=>
          student.id===
          editingRosterStudentId
      );


    if(!existing){
      return toast(
        'Student record was not found.'
      );
    }


    await setDoc(
      doc(
        db,
        'vendors',
        user.uid,
        'classes',
        c.id,
        'students',
        existing.id
      ),
      data,
      {
        merge:true
      }
    );


    const coreId=
      existing.coreStudentId;


    if(coreId){

      await setDoc(
        doc(
          db,
          'vendors',
          user.uid,
          'students',
          coreId
        ),
        {
          studentFirst:
            data.studentFirst,

          studentLast:
            data.studentLast,

          studentName:
            data.studentName,

          parentName:
            data.parentName,

          parentEmail:
            data.parentEmail,

          parentPhone:
            data.parentPhone,

          grade:
            data.grade,

          active:
            active(data),

          updatedAt:
            serverTimestamp()
        },
        {
          merge:true
        }
      );


      const linkedServices=
        services.filter(
          service=>
            service.studentId===coreId
        );


      for(
        const service of
        linkedServices
      ){

        await setDoc(
          doc(
            db,
            'vendors',
            user.uid,
            'services',
            service.id
          ),
          {
            studentName:
              data.studentName,

            updatedAt:
              serverTimestamp()
          },
          {
            merge:true
          }
        );
      }

    }else{

      await syncRosterToCoreRecords(
        c,
        [{
          id:existing.id,
          ...existing,
          ...data
        }]
      );
    }


    await applyRosterFinancialStatus(
      c,
      {
        ...existing,
        ...data
      },
      data.status
    );


    await log(
      'Student updated',
      `${existing.studentName} updated in ${c.name}.`,
      'Manual'
    );


  }else{

    const ref=
      await addDoc(
        collection(
          db,
          'vendors',
          user.uid,
          'classes',
          c.id,
          'students'
        ),
        {
          ...data,
          createdAt:
            serverTimestamp()
        }
      );


    await syncRosterToCoreRecords(
      c,
      [{
        id:ref.id,
        ...data
      }]
    );


    await log(
      'Student added',
      `${data.studentName} added to ${c.name}.`,
      'Manual'
    );
  }


  await loadRoster();


  await updateDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'classes',
      c.id
    ),
    {
      activeStudentCount:
        roster.filter(active).length,

      rosterCount:
        roster.length,

      updatedAt:
        serverTimestamp()
    }
  );


  await refreshAll();

  $('#classSelect').value=
    c.id;
  updateRosterUploadTarget();

  await loadRoster();

  renderRoster();

  const wasEditing=
    Boolean(editingRosterStudentId);

  resetRosterStudentForm();

  hide(
    $('#studentForm')
  );


  toast(
    wasEditing
      ? 'Student updated.'
      : 'Student saved.'
  );
};



/*
 * Was an inline handler assigned at module load. It is a function now
 * because the button it belongs to is rendered fresh with the group
 * details card, so the binding has to be reapplied rather than made
 * once. The body is unchanged.
 */
async function vfArchiveSelectedGroup(){

  const c=
    currentClass();

  if(!c){
    return;
  }


  const ok=
    confirm(
      `Archive ${c.name}?\n\n` +
      `This will remove the group from your active Groups. ` +
      `Students whose only active service is this group will no longer ` +
      `appear in Students & Services.\n\n` +
      `Payments, certificates, financial history and the full roster ` +
      `will NOT be deleted. You can unarchive the group later.`
    );


  if(!ok){
    return;
  }


  await updateDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'classes',
      c.id
    ),
    {
      archived:true,
      archivedAt:serverTimestamp(),
      updatedAt:serverTimestamp()
    }
  );


  await log(
    'Group archived',
    `${c.name} was archived. Roster and financial history preserved.`,
    'Manual'
  );


  $('#classSelect').value='';
  updateRosterUploadTarget();

  roster=[];

  await refreshAll();

  renderArchivedClasses();

  toast(
    `${c.name} archived.`
  );
}






/* ==========================================================
   STUDENTS, SERVICES & FUNDING
   ========================================================== */

/*
 * INCOME RECORDED BY HAND
 *
 * Everything VendorFlow bills through students, services and
 * certificates already lands in `payments`, and the Summary page's
 * gross income is a sum of that collection. This is for the money
 * that never went through any of it: an afternoon helping at a
 * learning center, a tutoring session with no certificate behind it,
 * anything earned before VendorFlow existed.
 *
 * Kept in its own collection rather than written into `payments` as
 * a fake one. A payment with no student is something the matching,
 * reminder and statement-import machinery would all have to be
 * taught to ignore, and one of them would eventually forget.
 *
 * Schedule C has no categories for income -- it is one line, gross
 * receipts -- so these exist for the vendor's own recall, not the
 * IRS's. They still get summed by category on the Summary page,
 * because "where did $9,400 come from" is a question worth being
 * able to answer in April.
 */
/* ==========================================================
   RECURRENCE ENGINE
   ==========================================================

   One rule shape, three kinds of thing it can repeat: a to-do,
   an expense, a charge.

   Everything here is pure date arithmetic on YYYY-MM-DD strings.
   No Date-with-timezone anywhere: a rule that says "the 8th"
   means the 8th wherever the vendor is, and running this on a
   Cloudflare worker in UTC must not turn that into the 7th.
   ========================================================== */

function vfRecurParseDate(value){

  const match=
    /^(\d{4})-(\d{2})-(\d{2})$/.exec(
      String(value||'').trim()
    );

  if(!match){
    return null;
  }

  const year=Number(match[1]);
  const month=Number(match[2]);
  const day=Number(match[3]);

  if(month<1 || month>12 || day<1 || day>31){
    return null;
  }

  if(day>vfRecurDaysInMonth(year,month)){
    return null;
  }

  return {year,month,day};
}


function vfRecurFormatDate(parts){

  return (
    String(parts.year).padStart(4,'0')+'-'+
    String(parts.month).padStart(2,'0')+'-'+
    String(parts.day).padStart(2,'0')
  );
}


function vfRecurDaysInMonth(year,month){

  return [
    31,
    (year%4===0 && year%100!==0) || year%400===0 ? 29 : 28,
    31,30,31,30,31,31,30,31,30,31
  ][month-1];
}


/* Days since 1970-01-01, so two dates can be compared and stepped
   without constructing a Date and inheriting a timezone. */
function vfRecurDayNumber(parts){

  let days=0;

  for(let y=1970;y<parts.year;y++){
    days += ((y%4===0 && y%100!==0) || y%400===0) ? 366 : 365;
  }

  for(let m=1;m<parts.month;m++){
    days += vfRecurDaysInMonth(parts.year,m);
  }

  return days + parts.day - 1;
}


function vfRecurFromDayNumber(dayNumber){

  let remaining=dayNumber;
  let year=1970;

  for(;;){

    const size=
      ((year%4===0 && year%100!==0) || year%400===0) ? 366 : 365;

    if(remaining<size){
      break;
    }

    remaining-=size;
    year++;
  }

  let month=1;

  for(;;){

    const size=vfRecurDaysInMonth(year,month);

    if(remaining<size){
      break;
    }

    remaining-=size;
    month++;
  }

  return {year,month,day:remaining+1};
}


/* 0 = Sunday. 1970-01-01 was a Thursday. */
function vfRecurWeekday(parts){

  return ((vfRecurDayNumber(parts)+4)%7+7)%7;
}


function vfRecurAddDays(parts,count){

  return vfRecurFromDayNumber(
    vfRecurDayNumber(parts)+count
  );
}


/*
 * Add months, clamping the day to the end of the target month.
 *
 * This is the classic recurrence bug. "The 31st of every month"
 * has no meaning in February, and rolling over to March 3rd is
 * wrong in a way nobody notices until an insurance payment lands
 * in the wrong month. Clamp to the last real day instead, and --
 * importantly -- clamp from the rule's ORIGINAL day each time, so
 * a January 31st rule gives Feb 28, Mar 31, Apr 30 rather than
 * collapsing to the 28th forever.
 */
function vfRecurAddMonths(parts,count,anchorDay){

  const target=
    (parts.year*12 + (parts.month-1)) + count;

  const year=Math.floor(target/12);
  const month=(target%12)+1;

  const wanted=
    anchorDay || parts.day;

  return {
    year,
    month,
    day:Math.min(wanted,vfRecurDaysInMonth(year,month))
  };
}


function vfRecurCompare(a,b){

  return vfRecurDayNumber(a)-vfRecurDayNumber(b);
}


/*
 * The first occurrence on or after `from`.
 *
 * Deliberately "on or after" rather than "after": a rule created
 * today, starting today, should fire today, not in a month.
 */
function vfRecurFirstOnOrAfter(rule,from){

  const start=
    vfRecurParseDate(rule.startDate);

  const after=
    vfRecurParseDate(from) || start;

  if(!start || !after){
    return null;
  }

  const interval=
    Math.max(1,Number(rule.interval||1));

  const floor=
    vfRecurCompare(start,after)>=0 ? start : after;

  if(rule.freq==='daily'){

    const gap=
      vfRecurDayNumber(floor)-vfRecurDayNumber(start);

    const steps=
      Math.max(0,Math.ceil(gap/interval));

    return vfRecurAddDays(start,steps*interval);
  }

  if(rule.freq==='weekly'){

    /*
     * Anchor on the requested weekday, not on whatever day the
     * rule happened to be created. "Every Sunday" set up on a
     * Wednesday means this coming Sunday.
     */
    const wanted=
      Number.isInteger(rule.weekday)
        ? rule.weekday
        : vfRecurWeekday(start);

    const startShift=
      (wanted-vfRecurWeekday(start)+7)%7;

    const firstHit=
      vfRecurAddDays(start,startShift);

    const gapWeeks=
      Math.ceil(
        (vfRecurDayNumber(floor)-vfRecurDayNumber(firstHit))/7
      );

    const steps=
      Math.max(0,Math.ceil(gapWeeks/interval));

    return vfRecurAddDays(firstHit,steps*interval*7);
  }

  if(rule.freq==='monthly'){

    const anchorDay=
      Number.isInteger(rule.monthDay) && rule.monthDay>0
        ? rule.monthDay
        : start.day;

    let candidate=
      vfRecurAddMonths(
        {year:start.year,month:start.month,day:1},
        0,
        anchorDay
      );

    if(vfRecurCompare(candidate,start)<0){
      candidate=vfRecurAddMonths(candidate,interval,anchorDay);
    }

    let guard=0;

    while(vfRecurCompare(candidate,floor)<0 && guard<1200){
      candidate=vfRecurAddMonths(candidate,interval,anchorDay);
      guard++;
    }

    return candidate;
  }

  return null;
}


function vfRecurNextAfter(rule,current){

  const parts=
    vfRecurParseDate(current);

  if(!parts){
    return null;
  }

  return vfRecurFirstOnOrAfter(
    rule,
    vfRecurFormatDate(vfRecurAddDays(parts,1))
  );
}


/*
 * Has this rule finished? Checked before creating anything, so a
 * rule that has run its course never produces one extra.
 */
function vfRecurIsFinished(rule,occurrenceDate){

  if(rule.endMode==='afterCount'){

    const limit=
      Number(rule.maxOccurrences||0);

    if(limit>0 && Number(rule.occurrencesCreated||0)>=limit){
      return true;
    }
  }

  if(rule.endMode==='onDate'){

    const end=vfRecurParseDate(rule.endDate);
    const when=vfRecurParseDate(occurrenceDate);

    if(end && when && vfRecurCompare(when,end)>0){
      return true;
    }
  }

  return false;
}


/*
 * Every occurrence a rule owes between its nextRunAt and today,
 * inclusive. Returns them in order so a vendor who has been away
 * for two months gets each month's expense on its own date rather
 * than two months of them stamped today.
 *
 * Capped, because a daily rule left alone for years should not
 * produce thousands of rows in one pass.
 */
function vfRecurDueOccurrences(rule,today,cap){

  const limit=
    Number.isInteger(cap) ? cap : 60;

  if(rule.active===false){
    return [];
  }

  const out=[];

  let cursor=
    rule.nextRunAt ||
    rule.startDate;

  let created=
    Number(rule.occurrencesCreated||0);

  const todayParts=
    vfRecurParseDate(today);

  if(!todayParts){
    return [];
  }

  let guard=0;

  while(out.length<limit && guard<5000){

    guard++;

    const parts=
      vfRecurParseDate(cursor);

    if(!parts){
      break;
    }

    if(vfRecurCompare(parts,todayParts)>0){
      break;
    }

    const probe={
      ...rule,
      occurrencesCreated:created
    };

    if(vfRecurIsFinished(probe,cursor)){
      break;
    }

    out.push(cursor);
    created++;

    const next=
      vfRecurNextAfter(rule,cursor);

    if(!next){
      break;
    }

    cursor=vfRecurFormatDate(next);
  }

  return out;
}


/* ==========================================================
   REPEAT CONTROLS
   ==========================================================

   The same block of markup appears on the expense form and the
   to-do form, with an id prefix. One set of functions drives both.

   The engine above is a byte-for-byte copy of the one in the
   worker. It has to be: the browser decides what nextRunAt should
   be when a rule is created or edited, and the worker advances it
   every night afterwards. If the two disagreed about what "the
   31st" means in February, a rule would drift the moment it was
   saved. The shared test suite is run against BOTH copies.
   ========================================================== */

const VF_REPEAT_FORMS={
  exp:{
    type:'expense',
    listId:'#expenseRepeatList',
    noun:'expense'
  },
  comp:{
    type:'task',
    listId:'#complianceRepeatList',
    noun:'task'
  }
};


let vfEditingRecurrenceId=null;


function vfRepeatEl(prefix,suffix){
  return $(`#${prefix}Repeat${suffix}`);
}


function vfRepeatReadForm(prefix,startDate){

  const on=
    vfRepeatEl(prefix,'On')?.checked;

  if(!on){
    return null;
  }

  const freq=
    vfRepeatEl(prefix,'Freq')?.value || 'monthly';

  const endMode=
    vfRepeatEl(prefix,'EndMode')?.value || 'never';

  const rule={
    freq,
    interval:
      Math.max(1,Number(vfRepeatEl(prefix,'Interval')?.value||1)),
    startDate,
    endMode
  };

  if(freq==='weekly'){
    rule.weekday=
      Number(vfRepeatEl(prefix,'Weekday')?.value||0);
  }

  if(freq==='monthly'){
    rule.monthDay=
      Math.min(
        31,
        Math.max(
          1,
          Number(vfRepeatEl(prefix,'MonthDay')?.value||1)
        )
      );
  }

  if(endMode==='onDate'){
    rule.endDate=
      vfRepeatEl(prefix,'EndDate')?.value || '';
  }

  if(endMode==='afterCount'){
    rule.maxOccurrences=
      Math.max(1,Number(vfRepeatEl(prefix,'Count')?.value||1));
  }

  return rule;
}


function vfRepeatDescribe(rule){

  const every=
    Number(rule.interval||1);

  const unit=
    rule.freq==='daily'
      ? (every===1?'day':`${every} days`)
      : rule.freq==='weekly'
        ? (every===1?'week':`${every} weeks`)
        : (every===1?'month':`${every} months`);

  let text=`Every ${unit}`;

  if(rule.freq==='weekly'){

    text+=
      ` on ${
        ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']
          [Number(rule.weekday||0)]
      }`;
  }

  if(rule.freq==='monthly'){
    text+=` on day ${Number(rule.monthDay||1)}`;
  }

  if(rule.endMode==='onDate' && rule.endDate){
    text+=`, until ${rule.endDate}`;
  }

  if(rule.endMode==='afterCount' && rule.maxOccurrences){
    text+=`, ${rule.maxOccurrences} times`;
  }

  return text;
}


/*
 * Live preview under the controls. Showing the next three real
 * dates is the cheapest way to catch a misunderstanding before it
 * becomes a year of wrong entries -- "day 31" quietly reading
 * Feb 28 is much easier to accept when you can see it.
 */
function vfRepeatUpdatePreview(prefix,startDate){

  const preview=
    vfRepeatEl(prefix,'Preview');

  if(!preview){
    return;
  }

  const rule=
    vfRepeatReadForm(prefix,startDate);

  if(!rule){
    preview.textContent='';
    return;
  }

  const dates=[];
  let cursor=rule.startDate;

  for(let i=0;i<3;i++){

    const next=
      i===0
        ? vfRecurFirstOnOrAfter(rule,cursor)
        : vfRecurNextAfter(rule,cursor);

    if(!next){
      break;
    }

    cursor=vfRecurFormatDate(next);

    if(vfRecurIsFinished({...rule,occurrencesCreated:i},cursor)){
      break;
    }

    dates.push(cursor);
  }

  preview.textContent=
    dates.length
      ? `${vfRepeatDescribe(rule)} — next: ${dates.join(', ')}`
      : `${vfRepeatDescribe(rule)} — no dates match this yet.`;
}


function vfRepeatSyncVisibility(prefix,startDate){

  const on=
    vfRepeatEl(prefix,'On')?.checked;

  const options=
    vfRepeatEl(prefix,'Options');

  if(options){
    options.classList.toggle('hidden',!on);
  }

  const freq=
    vfRepeatEl(prefix,'Freq')?.value || 'monthly';

  const endMode=
    vfRepeatEl(prefix,'EndMode')?.value || 'never';

  const toggle=(suffix,show)=>{
    const el=vfRepeatEl(prefix,suffix);
    if(el)el.classList.toggle('hidden',!show);
  };

  toggle('WeekdayWrap',freq==='weekly');
  toggle('MonthDayWrap',freq==='monthly');
  toggle('EndDateWrap',endMode==='onDate');
  toggle('CountWrap',endMode==='afterCount');

  vfRepeatUpdatePreview(prefix,startDate);
}


function vfRepeatClear(prefix){

  const on=vfRepeatEl(prefix,'On');

  if(on){
    on.checked=false;
  }

  const set=(suffix,value)=>{
    const el=vfRepeatEl(prefix,suffix);
    if(el)el.value=value;
  };

  set('Interval',1);
  set('Freq','monthly');
  set('Weekday','0');
  set('MonthDay',new Date().getDate());
  set('EndMode','never');
  set('EndDate','');
  set('Count',12);

  vfRepeatSyncVisibility(prefix,new Date().toISOString().slice(0,10));
}


function vfRepeatLoadRule(prefix,rule){

  const on=vfRepeatEl(prefix,'On');

  if(on){
    on.checked=true;
  }

  const set=(suffix,value)=>{
    const el=vfRepeatEl(prefix,suffix);
    if(el && value!==undefined && value!==null && value!==''){
      el.value=value;
    }
  };

  set('Interval',rule.interval||1);
  set('Freq',rule.freq||'monthly');
  set('Weekday',String(rule.weekday??0));
  set('MonthDay',rule.monthDay||1);
  set('EndMode',rule.endMode||'never');
  set('EndDate',rule.endDate||'');
  set('Count',rule.maxOccurrences||12);

  vfRepeatSyncVisibility(prefix,rule.startDate);
}


/*
 * Saves the rule for whatever was just entered.
 *
 * The item the vendor just filled in IS the first occurrence -- it
 * was created by the normal save path a moment ago -- so nextRunAt
 * is the next date AFTER today. Anything else would create today's
 * entry twice, once by hand and once by the cron tonight.
 */
async function vfRepeatSaveRule(prefix,template,startDate){

  const config=VF_REPEAT_FORMS[prefix];

  const editingRule=
    vfEditingRecurrenceId
      ? recurrences.find(r=>r.id===vfEditingRecurrenceId)
      : null;

  /*
   * startDate is the rule's ORIGIN and is set once, when the rule is
   * created. It must not be re-read from the form on an edit.
   *
   * vfEditRecurrence() puts the rule's pending nextRunAt into the
   * date field so the vendor can see when it next runs -- which
   * meant every edit quietly moved the origin forward to that date.
   * For "day 20 of every month" that is invisible, because the
   * anchor day governs. For "every 3 months" or "every 2 weeks" it
   * shifts the phase of the whole schedule each time it is touched.
   *
   * Caught live: a rule edited on 2026-09-10 reported its next run
   * as 2026-10-20 instead of 2026-09-20, because the origin had
   * already drifted to a previous nextRunAt of 2026-10-11.
   */
  const rule=
    vfRepeatReadForm(
      prefix,
      editingRule?.startDate || startDate
    );

  if(!config || !rule){

    /*
     * Unticking Repeat while editing an existing rule means "stop
     * repeating this" -- the rule is removed rather than silently
     * left running.
     */
    if(vfEditingRecurrenceId){

      await deleteDoc(
        doc(db,'vendors',user.uid,'recurrences',vfEditingRecurrenceId)
      );

      await log(
        'Repeat cancelled',
        `A scheduled ${config?config.noun:'item'} was set to stop repeating.`,
        'Manual'
      );

      vfEditingRecurrenceId=null;
    }

    return;
  }

  /*
   * Where the schedule resumes from.
   *
   * Creating: the item the vendor just filled in IS the first
   * occurrence, so the next one is the next date AFTER it.
   *
   * Editing: nothing was created just now, and startDate is the
   * rule's own pending nextRunAt. Advancing past it would silently
   * drop the occurrence the vendor is still waiting for -- edit a
   * monthly rule on the 2nd and October would never arrive. Take
   * the first date on or after today under the NEW schedule
   * instead.
   */
  const editing=
    Boolean(vfEditingRecurrenceId);

  const existing=editingRule;

  const next=
    editing
      ? vfRecurFirstOnOrAfter(
          rule,
          new Date().toISOString().slice(0,10)
        )
      : vfRecurNextAfter(rule,startDate);

  const record={
    type:config.type,
    label:
      String(
        template.task ||
        template.note ||
        vfExpenseCategoryLabel(template.category) ||
        'Scheduled item'
      ).slice(0,120),
    active:true,
    freq:rule.freq,
    interval:rule.interval,
    weekday:
      rule.freq==='weekly' ? Number(rule.weekday||0) : null,
    monthDay:
      rule.freq==='monthly' ? Number(rule.monthDay||1) : null,
    startDate:rule.startDate,
    endMode:rule.endMode,
    endDate:rule.endDate||'',
    maxOccurrences:Number(rule.maxOccurrences||0),
    nextRunAt:
      next ? vfRecurFormatDate(next) : '',
    lastRunAt:
      editing
        ? (existing?.lastRunAt || startDate)
        : startDate,

    /*
     * Creating counts the one just made by hand, so an "after 12
     * times" rule really does produce twelve in total. Editing must
     * carry the running total forward -- resetting it to 1 would
     * hand the rule eleven more goes every time it was edited.
     */
    occurrencesCreated:
      editing
        ? Number(existing?.occurrencesCreated||1)
        : 1,
    template:JSON.stringify(template),
    updatedAt:serverTimestamp()
  };

  if(vfEditingRecurrenceId){

    await setDoc(
      doc(db,'vendors',user.uid,'recurrences',vfEditingRecurrenceId),
      record,
      {merge:true}
    );

    await log(
      'Repeat updated',
      `${record.label} — ${vfRepeatDescribe(rule)}.`,
      'Manual'
    );

    vfEditingRecurrenceId=null;

  }else{

    await addDoc(
      sub('recurrences'),
      {
        ...record,
        createdAt:serverTimestamp()
      }
    );

    await log(
      'Repeat scheduled',
      `${record.label} — ${vfRepeatDescribe(rule)}. `+
      `Next on ${record.nextRunAt||'—'}.`,
      'Manual'
    );
  }
}


function vfRenderRepeatList(prefix){

  const config=VF_REPEAT_FORMS[prefix];
  const host=config ? $(config.listId) : null;

  if(!host){
    return;
  }

  const mine=
    recurrences.filter(r=>r.type===config.type);

  if(!mine.length){
    host.innerHTML='';
    return;
  }

  host.innerHTML=`
    <div class="vf-repeat-list">
      <div class="vf-repeat-list-head">
        <strong>Scheduled repeats</strong>
        <button
          type="button"
          class="vf-secondary-button"
          data-repeat-run-now="1">
          Run now
        </button>
      </div>
      <div class="muted vf-repeat-list-note">
        These run on their own once a day. "Run now" catches up
        anything already due without waiting.
      </div>
      ${
        mine.map(rule=>`
          <div class="vf-repeat-list-row ${rule.active===false?'vf-repeat-paused':''}">
            <div>
              <strong>${esc(rule.label||'Scheduled item')}</strong>
              <div class="muted">
                ${esc(vfRepeatDescribe(rule))}
                ${
                  rule.active===false
                    ? ' · paused'
                    : (
                        rule.nextRunAt
                          ? ` · next ${esc(rule.nextRunAt)}`
                          : ' · finished'
                      )
                }
              </div>
            </div>
            <div class="vf-repeat-list-actions">
              <button type="button" class="vf-secondary-button" data-repeat-edit="${esc(rule.id)}">Edit</button>
              <button type="button" class="vf-secondary-button" data-repeat-toggle="${esc(rule.id)}">
                ${rule.active===false?'Resume':'Pause'}
              </button>
              <button type="button" class="vf-secondary-button" data-repeat-delete="${esc(rule.id)}">Stop</button>
            </div>
          </div>
        `).join('')
      }
    </div>
  `;

  host.querySelectorAll('[data-repeat-toggle]').forEach(button=>{
    button.onclick=()=>vfToggleRecurrence(button.dataset.repeatToggle);
  });

  host.querySelectorAll('[data-repeat-delete]').forEach(button=>{
    button.onclick=()=>vfDeleteRecurrence(button.dataset.repeatDelete);
  });

  host.querySelectorAll('[data-repeat-edit]').forEach(button=>{
    button.onclick=()=>vfEditRecurrence(prefix,button.dataset.repeatEdit);
  });

  host.querySelectorAll('[data-repeat-run-now]').forEach(button=>{
    button.onclick=()=>vfRunScheduledNow(button);
  });
}


/*
 * Asks the worker to run this vendor's due rules immediately -- the
 * same code the nightly job runs, not a browser-side reimplementation
 * of it. Anything else would risk the two disagreeing, which is the
 * whole reason the engine is kept byte-identical in both places.
 */
async function vfRunScheduledNow(button){

  if(!user){
    return;
  }

  const original=button.textContent;

  button.disabled=true;
  button.textContent='Running…';

  try{

    const token=
      await user.getIdToken();

    const response=
      await fetch(
        `${VENDORFLOW_API}/recurrences/run`,
        {
          method:'POST',
          headers:{
            Authorization:`Bearer ${token}`
          }
        }
      );

    let data={};

    try{
      data=await response.json();
    }catch{}

    if(!response.ok){
      throw new Error(
        data?.detail ||
        data?.error ||
        `Scheduler returned ${response.status}.`
      );
    }

    const created=Number(data.created||0);
    const failed=Number(data.failed||0);

    await refreshAll();
    renderAll();

    if(failed){
      toast(
        `Created ${created}. ${failed} could not be created -- they will be retried.`
      );
    }else if(created){
      toast(
        `Created ${created} scheduled item${created===1?'':'s'}.`
      );
    }else{
      toast('Nothing was due. Everything is up to date.');
    }

  }catch(error){

    console.error('Manual recurrence run failed:',error);

    toast(
      error.message ||
      'Could not run your scheduled items.'
    );

  }finally{

    button.disabled=false;
    button.textContent=original;
  }
}


async function vfToggleRecurrence(ruleId){

  const rule=
    recurrences.find(r=>r.id===ruleId);

  if(!rule){
    return;
  }

  const nowActive=
    rule.active===false;

  await setDoc(
    doc(db,'vendors',user.uid,'recurrences',ruleId),
    {
      active:nowActive,
      updatedAt:serverTimestamp()
    },
    {merge:true}
  );

  await log(
    nowActive ? 'Repeat resumed' : 'Repeat paused',
    `${rule.label||'A scheduled item'} — ${
      nowActive ? 'will run again' : 'will not run until resumed'
    }.`,
    'Manual'
  );

  await refreshAll();
  vfRenderAllRepeatLists();

  toast(nowActive ? 'Repeat resumed.' : 'Repeat paused.');
}


async function vfDeleteRecurrence(ruleId){

  const rule=
    recurrences.find(r=>r.id===ruleId);

  if(!rule){
    return;
  }

  const ok=
    confirm(
      `Stop repeating "${rule.label||'this item'}"?\n\n`+
      `${vfRepeatDescribe(rule)}\n\n`+
      `Nothing already created is removed -- this only stops future `+
      `ones. Pause instead if you might want it back.`
    );

  if(!ok){
    return;
  }

  await deleteDoc(
    doc(db,'vendors',user.uid,'recurrences',ruleId)
  );

  await log(
    'Repeat stopped',
    `${rule.label||'A scheduled item'} will no longer repeat. `+
    `Entries already created were kept.`,
    'Manual'
  );

  await refreshAll();
  vfRenderAllRepeatLists();

  toast('Stopped repeating.');
}


function vfEditRecurrence(prefix,ruleId){

  const rule=
    recurrences.find(r=>r.id===ruleId);

  if(!rule){
    return;
  }

  vfEditingRecurrenceId=ruleId;

  let template={};

  try{
    template=JSON.parse(rule.template||'{}');
  }catch{
    template={};
  }

  if(prefix==='exp'){

    if($('#expCategory'))$('#expCategory').value=template.category||'other';
    if($('#expAmount'))$('#expAmount').value=template.amount||'';
    if($('#expDate'))$('#expDate').value=rule.nextRunAt||rule.startDate||'';
    if($('#expNote'))$('#expNote').value=template.note||'';
    show($('#expenseForm'));

  }else{

    if($('#compTask'))$('#compTask').value=template.task||'';
    if($('#compSchool'))$('#compSchool').value=template.school||'';
    if($('#compDue'))$('#compDue').value=rule.nextRunAt||rule.startDate||'';
    if($('#compNotes'))$('#compNotes').value=template.notes||'';
    show($('#complianceForm'));
  }

  vfRepeatLoadRule(prefix,rule);

  toast('Editing this repeat. Saving updates the schedule.');
}


function vfRenderAllRepeatLists(){
  vfRenderRepeatList('exp');
  vfRenderRepeatList('comp');
}


/*
 * Wiring. Every control re-runs the preview so the next dates are
 * always current.
 */
Object.keys(VF_REPEAT_FORMS).forEach(prefix=>{

  const startFor=()=>
    (prefix==='exp'
      ? $('#expDate')?.value
      : $('#compDue')?.value) ||
    new Date().toISOString().slice(0,10);

  [
    'On','Freq','Interval','Weekday','MonthDay',
    'EndMode','EndDate','Count'
  ].forEach(suffix=>{

    const el=vfRepeatEl(prefix,suffix);

    if(el){
      el.addEventListener('change',()=>
        vfRepeatSyncVisibility(prefix,startFor())
      );
      el.addEventListener('input',()=>
        vfRepeatUpdatePreview(prefix,startFor())
      );
    }
  });

  const dateField=
    prefix==='exp' ? $('#expDate') : $('#compDue');

  if(dateField){
    dateField.addEventListener('change',()=>
      vfRepeatUpdatePreview(prefix,startFor())
    );
  }
});


const VF_INCOME_CATEGORIES=[
  {key:'classes',    label:'Classes & programs'},
  {key:'tutoring',   label:'Tutoring'},
  {key:'charter',    label:'Charter school funds'},
  {key:'workshops',  label:'Workshops & events'},
  {key:'materials',  label:'Materials & supplies'},
  {key:'consulting', label:'Consulting & contract work'},
  {key:'other',      label:'Other income'}
];


function vfIncomeCategoryLabel(key){

  const found=
    VF_INCOME_CATEGORIES.find(c=>c.key===key);

  return found ? found.label : 'Other income';
}


let editingIncomeId=null;


function vfRenderIncomeCategoryOptions(){

  const select=$('#incCategory');

  if(!select || select.options.length){
    return;
  }

  select.innerHTML=
    VF_INCOME_CATEGORIES
      .map(c=>`<option value="${esc(c.key)}">${esc(c.label)}</option>`)
      .join('');
}


/* ============================================================
   THE VAULT

   Every file VendorFlow has ever stored, in one searchable place.
   Two things feed it:

     - certificates, which have always been stored and carry their
       own rich record (student, amount, invoice schedule)
     - anything else, recorded in the `vaultFiles` collection

   Certificate rows keep every badge and action they had on the old
   Certificates page. The Vault adds a shared search, filters,
   archive and delete over the top rather than replacing any of it.
   ============================================================ */

/*
 * Recording a stored file. Called the moment a statement is read,
 * not when its transactions are imported -- the vendor uploaded the
 * document, so the document belongs to them whether or not they
 * went on to import anything from it.
 */
async function vfRecordVaultFile(storedFile,kind,source){

  if(!storedFile || !storedFile.objectKey || !user){
    return null;
  }

  try{

    const ref=
      await addDoc(
        sub('vaultFiles'),
        {
          objectKey:
            String(storedFile.objectKey),
          name:
            String(storedFile.name||'Untitled file'),
          contentType:
            String(storedFile.contentType||''),
          size:
            Number(storedFile.size||0),
          kind:
            String(kind||'file'),
          source:
            String(source||'Uploaded'),
          uploadedAt:
            String(
              storedFile.uploadedAt ||
              new Date().toISOString()
            ),
          archived:false,
          createdAt:serverTimestamp(),
          updatedAt:serverTimestamp()
        }
      );

    return ref.id;

  }catch(error){

    console.error('Could not record a vault file:',error);
    return null;
  }
}


let vfVaultSearch='';
let vfVaultKindFilter='all';
let vfVaultShowArchived=false;


/*
 * One list covering everything stored. Certificates appear here
 * alongside statements -- a certificate is a document first, and
 * this is where a vendor looks for documents. The certificate
 * workflow below the list is untouched; this is the library, not a
 * replacement for it.
 */
function vfVaultItems(){

  const items=[];

  certs
    .filter(cert=>!cert.deleted && cert.pdfObjectKey)
    .forEach(cert=>{

      items.push({
        id:`cert:${cert.id}`,
        kind:'certificate',
        objectKey:cert.pdfObjectKey,
        name:
          `${cert.student||'Unnamed student'} — ${
            cert.school||'certificate'
          }`,
        detail:
          [
            cert.number ? `#${cert.number}` : '',
            Number.isFinite(Number(cert.amount))
              ? money(Number(cert.amount))
              : ''
          ].filter(Boolean).join(' · '),
        source:'Certificate',
        uploadedAt:
          String(
            cert.serviceStartDate ||
            cert.issueDate ||
            ''
          ).slice(0,10),
        size:0,

        /*
         * Certificates are archived and deleted through their own
         * record, which carries money with it. Offering those
         * buttons here would let a vendor erase a certificate --
         * and the charter credit it created -- from a file list.
         */
        canManage:false
      });
    });

  vaultFiles.forEach(file=>{

    items.push({
      id:`file:${file.id}`,
      fileId:file.id,
      kind:file.kind||'file',
      objectKey:file.objectKey,
      name:file.name||'Untitled file',
      detail:vfVaultFileSize(file.size),
      source:file.source||'Uploaded',
      uploadedAt:String(file.uploadedAt||'').slice(0,10),
      size:Number(file.size||0),
      archived:Boolean(file.archived),
      canManage:true
    });
  });

  return items;
}


function renderVault(){

  const list=$('#vaultFileList');

  if(!list){
    return;
  }

  const all=vfVaultItems();
  const query=vfVaultSearch.trim();

  let shown=
    all.filter(item=>{

      if(
        vfVaultKindFilter!=='all' &&
        item.kind!==vfVaultKindFilter
      ){
        return false;
      }

      /*
       * Archived files are hidden from the normal list but stay
       * findable: a search reaches them even with the toggle off,
       * which is the whole point of archiving rather than deleting.
       */
      if(item.archived && !vfVaultShowArchived && !query){
        return false;
      }

      return vfIncExpMatches(
        [
          item.name,
          item.detail,
          item.source,
          vfVaultKindLabel(item.kind),
          item.uploadedAt
        ],
        query
      );
    });

  /* Archived items always sort last, however the rest is ordered. */
  shown=shown.sort((x,y)=>{

    if(Boolean(x.archived)!==Boolean(y.archived)){
      return x.archived ? 1 : -1;
    }

    return String(y.uploadedAt||'')
      .localeCompare(String(x.uploadedAt||''));
  });

  if(!all.length){
    list.innerHTML=
      '<p class="muted">Nothing stored yet. Uploaded certificates '+
      'and statements will appear here.</p>';
    return;
  }

  if(!shown.length){
    list.innerHTML=
      `<p class="muted">No files match "${esc(query)}".</p>`;
    return;
  }

  const countNote=
    query || vfVaultKindFilter!=='all'
      ? `<p class="muted vf-incexp-count">${shown.length} of ${
          all.length
        } file${all.length===1?'':'s'} shown.</p>`
      : '';

  list.innerHTML=
    countNote+
    shown.map(item=>`
      <div class="vf-vault-row${item.archived?' vf-vault-archived':''}">

        <button
          type="button"
          class="vf-vault-open"
          data-vault-open="${esc(item.objectKey||'')}"
          data-vault-name="${esc(item.name)}"
          data-vault-file="${esc(item.fileId||'')}"
          title="Open this file">
          <strong>${esc(item.name)}${
            item.archived ? ' (Archived)' : ''
          }</strong>
          <span class="muted">
            ${esc(vfVaultKindLabel(item.kind))}${
              item.source ? ` · ${esc(item.source)}` : ''
            }${
              item.uploadedAt ? ` · ${esc(item.uploadedAt)}` : ''
            }${
              item.detail ? ` · ${esc(item.detail)}` : ''
            }
          </span>
        </button>

        ${
          item.canManage
            ? `<div class="vf-vault-actions">
                 <button
                   type="button"
                   class="vf-secondary-button"
                   data-vault-archive="${esc(item.fileId)}"
                   data-vault-archived="${item.archived?'1':'0'}">
                   ${item.archived?'Restore':'Archive'}
                 </button>
                 <button
                   type="button"
                   class="vf-secondary-button vf-vault-delete"
                   data-vault-delete="${esc(item.fileId)}">
                   Delete
                 </button>
               </div>`
            : `<div class="vf-vault-actions">
                 <span class="muted vf-vault-managed">
                   Managed with the certificate
                 </span>
               </div>`
        }

      </div>
    `).join('');

  list.querySelectorAll('[data-vault-open]').forEach(btn=>{
    btn.onclick=()=>
      vfOpenVaultFile(
        btn.dataset.vaultOpen,
        btn.dataset.vaultName,
        btn.dataset.vaultFile||''
      );
  });

  list.querySelectorAll('[data-vault-archive]').forEach(btn=>{
    btn.onclick=()=>
      vfArchiveVaultFile(
        btn.dataset.vaultArchive,
        btn.dataset.vaultArchived!=='1'
      );
  });

  list.querySelectorAll('[data-vault-delete]').forEach(btn=>{
    btn.onclick=()=>
      vfDeleteVaultFile(btn.dataset.vaultDelete);
  });
}


if($('#vaultSearch')){

  $('#vaultSearch').oninput=()=>{
    vfVaultSearch=$('#vaultSearch').value||'';
    renderVault();
  };
}


if($('#vaultKindFilter')){

  $('#vaultKindFilter').onchange=()=>{
    vfVaultKindFilter=$('#vaultKindFilter').value||'all';
    renderVault();
  };
}


if($('#vaultShowArchived')){

  $('#vaultShowArchived').onchange=()=>{
    vfVaultShowArchived=Boolean($('#vaultShowArchived').checked);
    renderVault();
  };
}


async function vfArchiveVaultFile(fileId,archived){

  const item=
    vaultFiles.find(f=>f.id===fileId);

  if(!item){
    return;
  }

  try{

    await updateDoc(
      doc(db,'vendors',user.uid,'vaultFiles',fileId),
      {
        archived:Boolean(archived),
        updatedAt:serverTimestamp()
      }
    );

    await log(
      archived ? 'File archived' : 'File restored',
      `${item.name||'A file'} was ${
        archived ? 'archived' : 'restored'
      } in the Vault.`,
      'Manual'
    );

    await refreshAll();
    renderVault();

    toast(archived ? 'Archived.' : 'Restored.');

  }catch(error){

    console.error('Vault archive failed:',error);
    toast('Could not change that file.');
  }
}


/*
 * A real deletion. The file is removed from storage and its record
 * is removed too, so unlike archiving there is nothing left to
 * restore. The warning says so plainly before anything happens.
 */
async function vfDeleteVaultFile(fileId){

  const item=
    vaultFiles.find(f=>f.id===fileId);

  if(!item){
    return;
  }

  const ok=
    confirm(
      `Delete ${item.name||'this file'} forever?\n\n`+
      `The file itself will be erased from storage. This cannot `+
      `be undone and there is no copy anywhere else.\n\n`+
      `If you only want it out of the way, use Archive instead — `+
      `archived files stay searchable.`
    );

  if(!ok){
    return;
  }

  try{

    if(item.objectKey){

      const token=
        await user.getIdToken();

      const response=
        await fetch(
          `${VENDORFLOW_API}/vault/file/`+
          encodeURIComponent(item.objectKey),
          {
            method:'DELETE',
            headers:{Authorization:`Bearer ${token}`}
          }
        );

      if(!response.ok){

        let data={};
        try{ data=await response.json(); }catch{}

        throw new Error(
          data?.detail ||
          data?.error ||
          `The file could not be deleted (${response.status}).`
        );
      }
    }

    /*
     * The record is removed only after the file is gone. If the
     * delete fails, the row stays so the vendor can see it still
     * exists rather than losing track of a file that is still
     * taking up space.
     */
    await deleteDoc(
      doc(db,'vendors',user.uid,'vaultFiles',fileId)
    );

    await log(
      'File deleted',
      `${item.name||'A file'} was permanently deleted from the Vault.`,
      'Manual'
    );

    await refreshAll();
    renderVault();

    toast('Deleted.');

  }catch(error){

    console.error('Vault delete failed:',error);
    toast(error.message||'Could not delete that file.');
  }
}


function vfVaultKindLabel(kind){

  return (
    {
      certificate:'Certificate',
      statement:'Statement',
      file:'File'
    }[String(kind||'file')] || 'File'
  );
}


function vfVaultFileSize(bytes){

  const n=Number(bytes||0);

  if(!(n>0)){
    return '';
  }

  if(n<1024){
    return `${n} B`;
  }

  if(n<1024*1024){
    return `${Math.round(n/1024)} KB`;
  }

  return `${(n/(1024*1024)).toFixed(1)} MB`;
}


/*
 * Open any stored file IN the app.
 *
 * Handing the blob to the browser in a new tab downloaded CSVs
 * instead of showing them -- browsers have no CSV viewer, so that
 * was never going to work, and even PDFs opened in a bare tab with
 * no way back. Both are now rendered here: PDFs through the pdf.js
 * already loaded for certificates, CSVs as a plain table.
 */
let vfVaultViewerUrl=null;


function vfCloseVaultViewer(){

  const modal=$('#vaultViewerModal');

  if(modal){
    hide(modal);
  }

  const docHost=$('#vaultViewerDoc');

  if(docHost){
    docHost.innerHTML='';
  }

  /* Release the downloaded copy so it is not held in memory. */
  if(vfVaultViewerUrl){
    URL.revokeObjectURL(vfVaultViewerUrl);
    vfVaultViewerUrl=null;
  }
}


/*
 * Very small CSV reader. Handles quoted fields and escaped quotes,
 * which is all a bank export needs -- this renders a preview, it is
 * not the importer, so it never has to be perfect about edge cases.
 */
function vfParseCsvPreview(text,maxRows){

  const rows=[];
  let row=[];
  let field='';
  let quoted=false;

  const push=()=>{ row.push(field); field=''; };
  const endRow=()=>{ row.push(field); rows.push(row); row=[]; field=''; };

  const s=String(text||'').replace(/\r\n/g,'\n');

  for(let i=0;i<s.length;i++){

    const ch=s[i];

    if(quoted){

      if(ch==='"'){

        if(s[i+1]==='"'){
          field+='"';
          i++;
        }else{
          quoted=false;
        }

      }else{
        field+=ch;
      }

      continue;
    }

    if(ch==='"'){ quoted=true; continue; }
    if(ch===','){ push(); continue; }

    if(ch==='\n'){
      endRow();
      if(rows.length>=maxRows){ return rows; }
      continue;
    }

    field+=ch;
  }

  if(field.length||row.length){
    endRow();
  }

  return rows;
}


/*
 * Transactions that came out of this file. Only rows imported after
 * the Vault existed carry a vaultFileId -- anything imported before
 * that has no link and cannot be matched retrospectively without
 * guessing, which would be worse than showing nothing.
 */
function vfVaultImportedRows(fileId){

  if(!fileId){
    return [];
  }

  const out=[];

  income
    .filter(x=>x.vaultFileId===fileId)
    .forEach(x=>out.push({
      kind:'Income',
      date:x.dateEarned||'',
      label:
        [vfIncomeCategoryLabel(x.category),x.payer]
          .filter(Boolean).join(' · '),
      amount:Number(x.amount||0)
    }));

  expenses
    .filter(x=>x.vaultFileId===fileId)
    .forEach(x=>out.push({
      kind:'Expense',
      date:x.date||'',
      label:
        [vfExpenseCategoryLabel(x.category),x.note]
          .filter(Boolean).join(' · '),
      amount:Number(x.amount||0)
    }));

  return out.sort(
    (a,b)=>String(a.date).localeCompare(String(b.date))
  );
}


async function vfOpenVaultFile(objectKey,name,fileId){

  if(!user || !objectKey){
    return;
  }

  const modal=$('#vaultViewerModal');
  const docHost=$('#vaultViewerDoc');
  const status=$('#vaultViewerStatus');

  if(!modal || !docHost){
    return;
  }

  vfCloseVaultViewer();

  if($('#vaultViewerTitle')){
    $('#vaultViewerTitle').textContent=name||'File';
  }

  /* What was imported from this file, shown above the document. */
  const imported=
    vfVaultImportedRows(fileId);

  const importedHost=$('#vaultViewerImported');

  if(importedHost){

    importedHost.innerHTML=
      imported.length
        ? `<div class="vf-vault-imported">
             <strong>${imported.length} transaction${
               imported.length===1?'':'s'
             } imported from this file</strong>
             ${imported.map(r=>`
               <div class="vf-vault-imported-row">
                 <span>${esc(r.date||'—')}</span>
                 <span>${esc(r.kind)}</span>
                 <span class="vf-vault-imported-label">${esc(r.label||'')}</span>
                 <span>${money(r.amount)}</span>
               </div>
             `).join('')}
           </div>`
        : (
            fileId
              ? `<p class="muted">Nothing recorded as imported from
                 this file. Statements imported before the Vault
                 existed were not linked to their document.</p>`
              : ''
          );
  }

  show(modal);

  if(status){
    status.textContent='Opening…';
  }

  try{

    const token=
      await user.getIdToken();

    const response=
      await fetch(
        `${VENDORFLOW_API}/vault/file/`+
        encodeURIComponent(objectKey),
        {headers:{Authorization:`Bearer ${token}`}}
      );

    if(!response.ok){

      let data={};
      try{ data=await response.json(); }catch{}

      throw new Error(
        data?.detail ||
        data?.error ||
        `That file could not be opened (${response.status}).`
      );
    }

    const blob=
      await response.blob();

    vfVaultViewerUrl=
      URL.createObjectURL(blob);

    const download=$('#vaultViewerDownload');

    if(download){
      download.href=vfVaultViewerUrl;
      download.download=name||'vendorflow-file';
    }

    const isCsv=
      /csv/i.test(blob.type||'') ||
      /\.csv$/i.test(String(objectKey||''));

    if(isCsv){

      const rows=
        vfParseCsvPreview(
          await blob.text(),
          400
        );

      docHost.innerHTML=
        rows.length
          ? `<div class="tablewrap">
               <table>
                 <tbody>
                   ${rows.map((r,rowIndex)=>`
                     <tr>${
                       r.map(cell=>
                         rowIndex===0
                           ? `<th>${esc(cell)}</th>`
                           : `<td>${esc(cell)}</td>`
                       ).join('')
                     }</tr>
                   `).join('')}
                 </tbody>
               </table>
             </div>`
          : '<p class="muted">That file appears to be empty.</p>';

      if(status){
        status.textContent=
          rows.length>=400
            ? 'Showing the first 400 rows.'
            : '';
      }

      return;
    }

    if(!window.pdfjsLib){

      if(status){
        status.textContent=
          'This file can be downloaded, but cannot be shown here.';
      }

      return;
    }

    const data=
      new Uint8Array(
        await blob.arrayBuffer()
      );

    const pdf=
      await window.pdfjsLib
        .getDocument({data})
        .promise;

    docHost.innerHTML='';

    for(let pageNumber=1;pageNumber<=pdf.numPages;pageNumber++){

      const page=
        await pdf.getPage(pageNumber);

      const viewport=
        page.getViewport({scale:1.4});

      const canvas=
        document.createElement('canvas');

      canvas.width=viewport.width;
      canvas.height=viewport.height;
      canvas.className='vf-vault-page';

      docHost.appendChild(canvas);

      await page.render({
        canvasContext:canvas.getContext('2d'),
        viewport
      }).promise;
    }

    if(status){
      status.textContent='';
    }

  }catch(error){

    console.error('Vault file open failed:',error);

    if(status){
      status.textContent=
        error.message||'Could not open that file.';
    }
  }
}


if($('#closeVaultViewer')){
  $('#closeVaultViewer').onclick=()=>vfCloseVaultViewer();
}


if($('#vaultViewerModal')){

  $('#vaultViewerModal').onclick=event=>{

    if(event.target===$('#vaultViewerModal')){
      vfCloseVaultViewer();
    }
  };
}


/*
 * One search box filters both columns. Matching is deliberately
 * forgiving: the words can appear in any order, across any field,
 * so "venmo 40" finds a $40 Venmo entry.
 */
let vfIncExpSearch='';

function vfIncExpMatches(haystackParts,query){

  const q=String(query||'').trim().toLowerCase();

  if(!q){
    return true;
  }

  const hay=
    haystackParts
      .filter(Boolean)
      .join(' ')
      .toLowerCase();

  return q
    .split(/\s+/)
    .every(word=>hay.includes(word));
}


function vfIncExpSearchNote(shown,total,noun){

  if(!vfIncExpSearch.trim()){
    return '';
  }

  return `<p class="muted vf-incexp-count">`+
    `${shown} of ${total} ${noun}${total===1?'':'s'} match `+
    `"${esc(vfIncExpSearch.trim())}".</p>`;
}


function vfClearIncomeForm(){

  vfRenderIncomeCategoryOptions();

  editingIncomeId=null;

  if($('#saveIncome'))$('#saveIncome').textContent='Save income';

  if($('#incDateEarned'))$('#incDateEarned').value=new Date().toISOString().slice(0,10);
  if($('#incAmount'))$('#incAmount').value='';
  if($('#incPayer'))$('#incPayer').value='';
  if($('#incCategory'))$('#incCategory').value='other';
  if($('#incMemo'))$('#incMemo').value='';
}


/*
 * Possible duplicates, across BOTH places money can already exist.
 *
 * Checking income against income alone would miss the case that
 * actually matters: a Venmo transfer already imported as a family
 * payment, then entered here by hand. Gross income sums payments AND
 * income, so that double-counts on a tax figure -- silently, and in
 * the direction that overstates what the vendor owes.
 *
 * Same amount to the cent, within three days either way. The payer
 * is used to raise confidence, never to rule a match out, because
 * the same person is written a dozen ways across statements.
 */
function vfFindIncomeDuplicates(entry){

  const amount=
    Number(entry.amount||0);

  if(!(amount>0)){
    return [];
  }

  const earned=
    Date.parse(`${entry.dateEarned}T12:00:00`);

  const withinThreeDays=
    other=>{

      if(Number.isNaN(earned)){
        return true;
      }

      const when=
        Date.parse(`${other}T12:00:00`);

      if(Number.isNaN(when)){
        return false;
      }

      return Math.abs(when-earned) <= 3*24*60*60*1000;
    };

  const samePayer=
    other=>{

      const a=String(entry.payer||'').trim().toLowerCase();
      const b=String(other||'').trim().toLowerCase();

      return Boolean(a) && Boolean(b) && a===b;
    };

  const matches=[];

  income.forEach(item=>{

    if(entry.id && item.id===entry.id){
      return;
    }

    if(
      Math.abs(Number(item.amount||0)-amount)<0.005 &&
      withinThreeDays(item.dateEarned)
    ){
      matches.push({
        kind:'income',
        label:
          `${vfIncomeCategoryLabel(item.category)}${
            item.payer ? ` from ${item.payer}` : ''
          } on ${item.dateEarned||'an unknown date'}`,
        confident:samePayer(item.payer)
      });
    }
  });

  payments.forEach(item=>{

    if(
      Math.abs(Number(item.amount||0)-amount)<0.005 &&
      withinThreeDays(item.date||item.paymentDate)
    ){
      matches.push({
        kind:'payment',
        label:
          `a recorded payment${
            item.student ? ` for ${item.student}` : ''
          }${
            item.payer ? ` from ${item.payer}` : ''
          } on ${item.date||item.paymentDate||'an unknown date'}`,
        confident:samePayer(item.payer||item.student)
      });
    }
  });

  return matches.sort(
    (x,y)=>Number(y.confident)-Number(x.confident)
  );
}


function vfIncomeDuplicateWarning(matches,amount){

  const lines=
    matches
      .slice(0,4)
      .map(m=>`  - ${m.label}`)
      .join('\n');

  const more=
    matches.length>4
      ? `\n  ...and ${matches.length-4} more`
      : '';

  return (
    `${money(amount)} may already be recorded.\n\n`+
    `VendorFlow found ${matches.length} `+
    `${matches.length===1?'entry':'entries'} for the same amount `+
    `within three days:\n\n${lines}${more}\n\n`+
    `Gross income counts recorded payments and income together, so `+
    `saving this anyway would count the money twice.\n\n`+
    `Save it anyway?`
  );
}


/*
 * IMPORTING INCOME FROM A STATEMENT
 *
 * Reuses /payment-statement/extract, the same reader behind the
 * Payments page. Its output already carries everything income needs
 * -- date, payer, description, memo, amount, direction, method --
 * so no worker change was required.
 *
 * Nothing is written until the vendor presses Import. Every row is
 * checked against existing income AND existing payments first
 * (vfFindIncomeDuplicates), because a statement is the single most
 * likely way to import money that VendorFlow already recorded from
 * the family side. Rows that look like duplicates arrive UNTICKED,
 * so double-counting takes a deliberate click rather than being the
 * default.
 */
let vfIncomeImportRows=[];
let vfIncomeImportBusy=false;


function vfIncomeImportDirection(tx){

  const raw=
    String(tx?.direction||'').toLowerCase();

  if(raw==='incoming' || raw==='outgoing'){
    return raw;
  }

  return 'uncertain';
}


let vfIncomeImportVaultId=null;


/* ============================================================
   GUESSING AN INCOME CATEGORY

   Two sources, in this order of trust:

     1. What the vendor chose for this payer before. The same family
        pays for the same thing month after month, so their own past
        decision is the best available evidence -- better than any
        keyword list, because it is specific to them.

     2. Words in the memo. Venmo memos usually say what the money is
        for ("Aug tutoring", "math class").

   Learning reads the vendor's existing income records rather than a
   separate store. That means it works from day one on history they
   already have, needs no migration, and self-corrects: change a
   payer's category a few times and the new answer wins on its own.

   Every guess is only a DEFAULT on a row the vendor reviews before
   anything is saved.
   ============================================================ */

const VF_INCOME_CATEGORY_HINTS=[
  {key:'tutoring',  words:['tutor','tutoring','1:1','one on one','session']},
  {key:'classes',   words:['class','classes','course','enrollment','semester','program','math jam','co-op','coop']},
  {key:'workshops', words:['workshop','camp','clinic','event','field trip','fieldtrip']},
  {key:'materials', words:['material','supplies','book','books','kit','curriculum']},
  {key:'charter',   words:['charter','certificate','purchase order',' po ','po#','reimburse']},
  {key:'consulting',words:['consult','contract','coaching','advisory']}
];


function vfNormalizePayerKey(payer){

  return String(payer||'')
    .trim()
    .toLowerCase()
    .replace(/\s+/g,' ');
}


function vfGuessIncomeCategoryFromText(text){

  const hay=String(text||'').toLowerCase();

  if(!hay.trim()){
    return '';
  }

  for(const hint of VF_INCOME_CATEGORY_HINTS){
    if(hint.words.some(word=>hay.includes(word))){
      return hint.key;
    }
  }

  return '';
}


/*
 * Everything already on file about who this payer is and what their
 * money has been for.
 *
 * Two sources, because a vendor's history lives in two places:
 *
 *   income   -- money typed in or imported here, carrying a category
 *               the vendor actually chose. Strongest evidence.
 *   payments -- money from families for groups and tutoring. These
 *               carry no income category, but the GROUP tells us:
 *               a payment against "Tutoring" is tutoring income,
 *               one against "Math Jam 3" is class income.
 *
 * The first version only looked at `income`, and found nothing --
 * the Income page is explicitly for money VendorFlow did not already
 * record, so a vendor's regulars are almost all in `payments`. That
 * is why every row still said "Other".
 *
 * A payer is matched on the payment's payer OR the parent's name,
 * since a Venmo display name is often the parent rather than
 * whatever was typed into the payer box.
 */
function vfIncomeCategoryEvidence(payer){

  const key=vfNormalizePayerKey(payer);

  if(!key){
    return [];
  }

  const found=[];

  income.forEach(item=>{

    if(vfNormalizePayerKey(item.payer)!==key)return;
    if(!item.category || item.category==='other')return;

    found.push({
      category:item.category,
      date:String(item.dateEarned||''),
      /* A chosen category outranks one we inferred. */
      strength:1,
      name:item.payer||payer,
      source:'income'
    });
  });

  payments.forEach(item=>{

    const matchesPayer=
      vfNormalizePayerKey(item.payer)===key ||
      vfNormalizePayerKey(item.parentName)===key;

    if(!matchesPayer)return;

    const category=
      vfGuessIncomeCategoryFromText(
        vfPaymentGroupText(item)
      );

    if(!category)return;

    found.push({
      category,
      date:String(item.date||item.paymentDate||''),
      strength:0.6,
      name:item.payer||item.parentName||payer,
      source:'payments'
    });
  });

  return found.sort(
    (x,y)=>String(y.date).localeCompare(String(x.date))
  );
}


/*
 * What a payment was for, as text. The group name is the signal --
 * "Tutoring", "Math Jam 3". Falls back to the student's groups when
 * the payment itself does not name one.
 */
function vfPaymentGroupText(payment){

  const direct=
    [
      payment?.className,
      payment?.serviceName,
      payment?.groupName
    ].filter(Boolean).join(' ').trim();

  if(direct)return direct;

  const studentId=String(payment?.studentId||'').trim();

  if(!studentId)return '';

  return services
    .filter(s=>String(s.studentId||'')===studentId)
    .map(s=>s.name||s.serviceType||'')
    .filter(Boolean)
    .join(' ');
}


/*
 * What this vendor has previously filed this payer's money under.
 *
 * Most recent entries count for more, so changing your mind about a
 * payer takes effect quickly instead of being outvoted by years of
 * old rows. 'other' is ignored -- it is the default nobody chose, so
 * counting it would teach the app that the vendor keeps picking
 * "Other" when in fact they just never picked anything.
 */
function vfLearnedIncomeCategory(payer){

  const all=vfIncomeCategoryEvidence(payer);

  if(!all.length){
    return null;
  }

  /*
   * A category the vendor actually chose on an income entry wins
   * outright over one inferred from a group name -- it is the only
   * direct evidence of how they categorise INCOME, where a payment's
   * group is a proxy.
   *
   * Weighting the two together did not work: a payment dated one day
   * later outranked a real choice, because recency swamped the
   * strength difference. Choosing the source first, then ranking by
   * recency within it, is both correct and easy to predict.
   */
  const chosen=
    all.filter(item=>item.source==='income');

  const matches=
    chosen.length ? chosen : all;

  const weights=new Map();

  matches.forEach((item,index)=>{
    /* 1st, 1/2, 1/3 ... so the newest choice leads. */
    const weight=1/(index+1);
    weights.set(
      item.category,
      (weights.get(item.category)||0)+weight
    );
  });

  let best=null;
  let bestWeight=0;

  for(const [category,weight] of weights){
    if(weight>bestWeight){
      best=category;
      bestWeight=weight;
    }
  }

  if(!best){
    return null;
  }

  const supporting=
    matches.filter(m=>m.category===best);

  return {
    category:best,
    timesSeen:supporting.length,
    payerName:matches[0].name||payer,
    fromPayments:
      supporting.every(m=>m.source==='payments')
  };
}


/*
 * Returns {category, reason} for one imported transaction. reason is
 * shown to the vendor, so they can see WHY a row was pre-filled and
 * judge whether to trust it -- a silent guess is one nobody checks.
 */
function vfSuggestIncomeCategory(payer,memo){

  const learned=vfLearnedIncomeCategory(payer);

  if(learned){

    const times=
      `${learned.timesSeen} time${learned.timesSeen===1?'':'s'}`;

    return {
      category:learned.category,
      reason:
        learned.fromPayments
          ? `${learned.payerName} has paid for `+
            `${vfIncomeCategoryLabel(learned.category)} `+
            `${times} before.`
          : `You filed ${learned.payerName}'s money under `+
            `${vfIncomeCategoryLabel(learned.category)} `+
            `${times} before.`
    };
  }

  const guessed=
    vfGuessIncomeCategoryFromText(`${memo||''} ${payer||''}`);

  if(guessed){
    return {
      category:guessed,
      reason:`Guessed from the memo.`
    };
  }

  return {category:'other',reason:''};
}


function vfBuildIncomeImportRows(data){

  const list=
    Array.isArray(data?.transactions)
      ? data.transactions
      : [];

  return list
    .map((tx,index)=>{

      const amount=
        Math.abs(Number(tx.amount||0));

      const direction=
        vfIncomeImportDirection(tx);

      const entry={
        amount,
        dateEarned:
          String(tx.date||'').slice(0,10),
        payer:
          String(tx.payer||'').trim()
      };

      const duplicates=
        amount>0
          ? vfFindIncomeDuplicates(entry)
          : [];

      const memo=
        String(
          tx.memo ||
          tx.description ||
          ''
        ).trim();

      const suggestion=
        vfSuggestIncomeCategory(entry.payer,memo);

      return {
        id:`inc-import-${index}`,
        amount,
        dateEarned:entry.dateEarned,
        payer:entry.payer,
        memo:
          String(
            tx.memo ||
            tx.description ||
            ''
          ).trim(),
        method:
          String(tx.method||'').trim(),
        direction,
        duplicates,

        /*
         * Outgoing money is not income, and a possible duplicate is
         * money already counted. Both start unticked; an uncertain
         * direction does too, because guessing in the direction of
         * overstating income is the wrong way to be wrong.
         */
        include:
          direction==='incoming' &&
          amount>0 &&
          duplicates.length===0,

        category:suggestion.category,
        categoryReason:suggestion.reason
      };
    })
    .filter(row=>row.amount>0);
}


function vfRenderIncomeImportResults(){

  const host=$('#incomeStatementResults');

  if(!host){
    return;
  }

  if(!vfIncomeImportRows.length){
    host.innerHTML='';
    return;
  }

  const categoryOptions=
    row=>
      VF_INCOME_CATEGORIES
        .map(c=>
          `<option value="${esc(c.key)}" ${
            c.key===row.category ? 'selected' : ''
          }>${esc(c.label)}</option>`
        )
        .join('');

  const incoming=
    vfIncomeImportRows.filter(r=>r.direction==='incoming').length;

  const flagged=
    vfIncomeImportRows.filter(r=>r.duplicates.length).length;

  host.innerHTML=`
    <div class="vf-income-import-summary">
      <strong>${vfIncomeImportRows.length} transaction${
        vfIncomeImportRows.length===1?'':'s'
      } found</strong>
      <span class="muted">
        ${incoming} coming in${
          flagged
            ? ` · ${flagged} may already be recorded`
            : ''
        }
      </span>
    </div>

    <div class="tablewrap">
      <table>
        <thead>
          <tr>
            <th>Import</th>
            <th>Date</th>
            <th>Payer</th>
            <th>Amount</th>
            <th>Category</th>
            <th>Notes</th>
          </tr>
        </thead>
        <tbody>
          ${
            vfIncomeImportRows.map(row=>`
              <tr class="${row.duplicates.length?'vf-income-import-dup':''}">
                <td>
                  <input
                    type="checkbox"
                    data-income-import-pick="${esc(row.id)}"
                    ${row.include?'checked':''}>
                </td>
                <td>${esc(row.dateEarned||'—')}</td>
                <td>${esc(row.payer||'—')}</td>
                <td>${money(row.amount)}</td>
                <td>
                  <select class="input" data-income-import-category="${esc(row.id)}">
                    ${categoryOptions(row)}
                  </select>
                </td>
                <td>
                  ${
                    row.direction==='outgoing'
                      ? '<div class="vf-income-import-note">Money going out — not income</div>'
                      : ''
                  }
                  ${
                    row.direction==='uncertain'
                      ? '<div class="vf-income-import-note">VendorFlow could not tell which way this went</div>'
                      : ''
                  }
                  ${
                    row.duplicates.length
                      ? `<div class="vf-income-import-warning">
                           May already be recorded: ${esc(row.duplicates[0].label)}
                         </div>`
                      : ''
                  }
                  ${
                    row.categoryReason
                      ? `<div class="vf-income-import-learned">${
                          esc(row.categoryReason)
                        }</div>`
                      : ''
                  }
                  ${
                    row.memo
                      ? `<div class="muted">${esc(row.memo)}</div>`
                      : ''
                  }
                </td>
              </tr>
            `).join('')
          }
        </tbody>
      </table>
    </div>

    <div class="row">
      <button type="button" id="vfIncomeImportRun" class="primary">
        Import selected
      </button>
      <button type="button" id="vfIncomeImportCancel">Cancel</button>
    </div>
  `;

  host.querySelectorAll('[data-income-import-pick]').forEach(box=>{
    box.onchange=()=>{
      const row=
        vfIncomeImportRows.find(
          r=>r.id===box.dataset.incomeImportPick
        );
      if(row){
        row.include=box.checked;
      }
    };
  });

  host.querySelectorAll('[data-income-import-category]').forEach(select=>{
    select.onchange=()=>{
      const row=
        vfIncomeImportRows.find(
          r=>r.id===select.dataset.incomeImportCategory
        );
      if(row){
        row.category=select.value;

        /* The vendor has overruled the guess, so the explanation for
           it is no longer true. Drop it rather than leave a note
           claiming a reason for a choice they just changed. */
        row.categoryReason='';

        vfRenderIncomeImportResults();
      }
    };
  });

  const cancel=$('#vfIncomeImportCancel');

  if(cancel){
    cancel.onclick=()=>{
      vfIncomeImportRows=[];
      vfRenderIncomeImportResults();
      if($('#incomeStatementFile'))$('#incomeStatementFile').value='';
      if($('#incomeStatementStatus'))$('#incomeStatementStatus').textContent='';
    };
  }

  const run=$('#vfIncomeImportRun');

  if(run){
    run.onclick=()=>vfRunIncomeImport();
  }
}


async function vfRunIncomeImport(){

  if(vfIncomeImportBusy){
    return;
  }

  const chosen=
    vfIncomeImportRows.filter(r=>r.include);

  if(!chosen.length){
    return toast('Tick at least one transaction to import.');
  }

  const flagged=
    chosen.filter(r=>r.duplicates.length).length;

  if(flagged){

    const proceed=
      confirm(
        `${flagged} of the ${chosen.length} selected `+
        `${flagged===1?'transaction looks':'transactions look'} like `+
        `money VendorFlow has already recorded.\n\n`+
        `Gross income counts recorded payments and income together, `+
        `so importing ${flagged===1?'it':'them'} would count that `+
        `money twice.\n\nImport anyway?`
      );

    if(!proceed){
      return;
    }
  }

  vfIncomeImportBusy=true;

  const run=$('#vfIncomeImportRun');

  if(run){
    run.disabled=true;
    run.textContent='Importing…';
  }

  let saved=0;

  try{

    for(const row of chosen){

      await addDoc(
        sub('income'),
        {
          amount:row.amount,
          dateEarned:
            row.dateEarned ||
            new Date().toISOString().slice(0,10),
          payer:row.payer,
          category:row.category||'other',
          memo:row.memo,
          method:row.method,
          source:'Statement import',
          vaultFileId:vfIncomeImportVaultId||'',
          createdAt:serverTimestamp(),
          updatedAt:serverTimestamp()
        }
      );

      saved++;
    }

    const total=
      chosen.reduce((sum,r)=>sum+r.amount,0);

    await log(
      'Income imported',
      `${saved} transaction${saved===1?'':'s'} imported from a `+
      `statement, ${money(total)} in total.`+
      `${flagged?` ${flagged} were flagged as possible duplicates and imported anyway.`:''}`,
      'Imported'
    );

    vfIncomeImportRows=[];
    vfRenderIncomeImportResults();

    if($('#incomeStatementFile'))$('#incomeStatementFile').value='';

    if($('#incomeStatementStatus')){
      $('#incomeStatementStatus').textContent=
        `Imported ${saved} transaction${saved===1?'':'s'}.`;
    }

    await refreshAll();
    renderIncome();
    renderTaxSummary();

    toast(`Imported ${saved} into income.`);

  }catch(error){

    console.error('Income import failed:',error);

    toast(
      `Imported ${saved} before this failed: ${
        error.message || 'something went wrong'
      }`
    );

    if(saved){
      await refreshAll();
      renderIncome();
      renderTaxSummary();
    }

  }finally{

    vfIncomeImportBusy=false;

    if(run){
      run.disabled=false;
      run.textContent='Import selected';
    }
  }
}


if($('#incomeStatementFile')){

  $('#incomeStatementFile').addEventListener('change',async event=>{

    const file=event.target.files?.[0];

    if(!file || !user){
      return;
    }

    const status=$('#incomeStatementStatus');

    vfIncomeImportRows=[];
    vfRenderIncomeImportResults();

    if(status){
      status.textContent=`Reading ${file.name}…`;
    }

    try{

      const token=
        await user.getIdToken();

      const form=new FormData();
      form.append('file',file,file.name);

      const response=
        await fetch(
          `${VENDORFLOW_API}/payment-statement/extract`,
          {
            method:'POST',
            headers:{Authorization:`Bearer ${token}`},
            body:form
          }
        );

      let data={};

      try{
        data=await response.json();
      }catch{}

      if(!response.ok){
        throw new Error(
          data?.detail ||
          data?.error ||
          `Statement reader returned ${response.status}.`
        );
      }

      /*
       * The document goes into the Vault now, before any
       * transaction is imported. The vendor uploaded it, so it is
       * theirs to find again whether or not they import from it.
       */
      vfIncomeImportVaultId=
        await vfRecordVaultFile(
          data?.storedFile,
          'statement',
          'Income import'
        );

      vfIncomeImportRows=
        vfBuildIncomeImportRows(data);

      vfRenderIncomeImportResults();

      if(status){

        status.textContent=
          vfIncomeImportRows.length
            ? `Read ${file.name}. Nothing has been imported yet — choose what to keep.`
            : `Read ${file.name}, but found no transactions to import.`;
      }

    }catch(error){

      console.error('Income statement read failed:',error);

      if(status){
        status.textContent=
          error.message ||
          'Could not read that statement.';
      }

      toast('Could not read that statement.');
    }
  });
}


function renderIncome(){

  const list=$('#incomeList');

  if(!list){
    return;
  }

  vfRenderIncomeCategoryOptions();

  if(!income.length){
    list.innerHTML='<p class="muted">No income recorded here yet.</p>';
    return;
  }

  const sorted=
    [...income].sort(
      (a,b)=>
        String(b.dateEarned||'').localeCompare(String(a.dateEarned||''))
    );

  const matches=
    sorted.filter(item=>
      vfIncExpMatches(
        [
          vfIncomeCategoryLabel(item.category),
          item.dateEarned,
          item.payer,
          item.memo,
          money(Number(item.amount||0)),
          String(item.amount||'')
        ],
        vfIncExpSearch
      )
    );

  if(!matches.length){
    list.innerHTML=
      `<p class="muted">No income matches `+
      `"${esc(vfIncExpSearch.trim())}".</p>`;
    return;
  }

  list.innerHTML=
    vfIncExpSearchNote(matches.length,sorted.length,'entry')+
    matches.map(item=>`
      <div class="vf-expense-row">
        <div class="vf-expense-row-main">
          <strong>${esc(vfIncomeCategoryLabel(item.category))}</strong>
          <span class="muted">
            Earned ${esc(item.dateEarned||'—')}${
              item.payer ? ` · ${esc(item.payer)}` : ''
            }
          </span>
          ${
            item.memo
              ? `<p class="muted">${esc(item.memo)}</p>`
              : ''
          }
          <span class="muted vf-income-recorded">
            Recorded ${esc(vfIncomeRecordedDate(item))}
          </span>
        </div>
        <div class="vf-expense-row-amount">${money(Number(item.amount||0))}</div>
        <div class="vf-expense-row-actions">
          <button type="button" class="vf-secondary-button" data-edit-income="${esc(item.id)}">Edit</button>
          <button type="button" class="vf-secondary-button" data-delete-income="${esc(item.id)}">Delete</button>
        </div>
      </div>
    `).join('');

  list.querySelectorAll('[data-delete-income]').forEach(btn=>{
    btn.onclick=()=>deleteIncome(btn.dataset.deleteIncome);
  });

  list.querySelectorAll('[data-edit-income]').forEach(btn=>{
    btn.onclick=()=>vfEditIncome(btn.dataset.editIncome);
  });
}


/*
 * Editing reuses the Add form, so a saved edit runs through exactly
 * the same validation as a new entry.
 */
function vfEditIncome(incomeId){

  const item=
    income.find(x=>x.id===incomeId);

  if(!item){
    return toast('That income entry is no longer here.');
  }

  vfClearIncomeForm();

  editingIncomeId=incomeId;

  if($('#incDateEarned'))$('#incDateEarned').value=item.dateEarned||'';
  if($('#incAmount'))$('#incAmount').value=item.amount ?? '';
  if($('#incPayer'))$('#incPayer').value=item.payer||'';
  if($('#incCategory'))$('#incCategory').value=item.category||'other';
  if($('#incMemo'))$('#incMemo').value=item.memo||'';
  if($('#saveIncome'))$('#saveIncome').textContent='Update income';

  show($('#incomeForm'));

  $('#incomeForm').scrollIntoView({behavior:'smooth',block:'nearest'});
}


function vfIncomeRecordedDate(item){

  const raw=item?.createdAt;

  try{

    const d=
      raw?.toDate ? raw.toDate() : new Date(raw);

    return Number.isNaN(d.getTime())
      ? '—'
      : d.toLocaleDateString();

  }catch{
    return '—';
  }
}


async function deleteIncome(incomeId){

  const item=
    income.find(i=>i.id===incomeId);

  if(!item){
    return;
  }

  const ok=
    confirm(
      `Delete this income entry?\n\n`+
      `${vfIncomeCategoryLabel(item.category)} — `+
      `${money(Number(item.amount||0))}`+
      `${item.payer?` from ${item.payer}`:''}`
    );

  if(!ok){
    return;
  }

  await deleteDoc(
    doc(db,'vendors',user.uid,'income',incomeId)
  );

  await log(
    'Income deleted',
    `${vfIncomeCategoryLabel(item.category)} — `+
    `${money(Number(item.amount||0))} removed from income.`,
    'Manual'
  );

  await refreshAll();
  renderIncome();
  renderTaxSummary();

  toast('Income entry deleted.');
}


if($('#addIncome')){
  $('#addIncome').onclick=()=>{
    vfClearIncomeForm();
    show($('#incomeForm'));
  };
}


if($('#incExpSearch')){

  $('#incExpSearch').oninput=()=>{
    vfIncExpSearch=$('#incExpSearch').value||'';
    renderIncome();
    renderExpenses();
  };
}


if($('#incExpSearchClear')){

  $('#incExpSearchClear').onclick=()=>{
    vfIncExpSearch='';
    if($('#incExpSearch'))$('#incExpSearch').value='';
    renderIncome();
    renderExpenses();
  };
}


if($('#cancelIncome')){
  $('#cancelIncome').onclick=()=>{
    vfClearIncomeForm();
    hide($('#incomeForm'));
  };
}


if($('#saveIncome')){

  $('#saveIncome').onclick=async()=>{

    const amount=
      Number($('#incAmount').value);

    if(!(amount>0)){
      return toast('Enter an amount.');
    }

    const entry={
      amount,
      dateEarned:
        $('#incDateEarned').value ||
        new Date().toISOString().slice(0,10),
      payer:
        $('#incPayer').value.trim(),
      category:
        $('#incCategory').value || 'other',
      memo:
        $('#incMemo').value.trim()
    };

    /*
     * Editing an entry that already exists. Update in place rather
     * than adding a second copy, and skip the duplicate check --
     * the entry would always match itself.
     */
    if(editingIncomeId){

      const editingId=editingIncomeId;

      await updateDoc(
        doc(db,'vendors',user.uid,'income',editingId),
        {
          ...entry,
          updatedAt:serverTimestamp()
        }
      );

      await log(
        'Income updated',
        `${vfIncomeCategoryLabel(entry.category)} — ${money(amount)}`+
        `${entry.payer?` from ${entry.payer}`:''}`+
        ` earned ${entry.dateEarned}.`,
        'Manual'
      );

      vfClearIncomeForm();
      hide($('#incomeForm'));

      await refreshAll();
      renderIncome();
      renderTaxSummary();

      return toast('Income updated.');
    }

    const duplicates=
      vfFindIncomeDuplicates(entry);

    if(duplicates.length){

      const proceed=
        confirm(
          vfIncomeDuplicateWarning(duplicates,amount)
        );

      if(!proceed){
        return;
      }
    }

    await addDoc(
      sub('income'),
      {
        ...entry,
        source:'Manual',
        createdAt:serverTimestamp(),
        updatedAt:serverTimestamp()
      }
    );

    await log(
      'Income added',
      `${vfIncomeCategoryLabel(entry.category)} — ${money(amount)}`+
      `${entry.payer?` from ${entry.payer}`:''}`+
      ` earned ${entry.dateEarned}.`+
      `${entry.memo?` ${entry.memo}`:''}`+
      `${duplicates.length?` Saved despite ${duplicates.length} possible duplicate(s).`:''}`,
      'Manual'
    );

    vfClearIncomeForm();
    hide($('#incomeForm'));

    await refreshAll();
    renderIncome();
    renderTaxSummary();

    toast('Income saved.');
  };
}


