function vfExpenseCategoryLabel(key){
  const found=VF_EXPENSE_CATEGORIES.find(c=>c.key===key);
  return found?found.label:'Other Expenses';
}

let editingExpenseId=null;

function clearExpenseForm(){
  editingExpenseId=null;
  if($('#expCategory'))$('#expCategory').value='advertising';
  if($('#expAmount'))$('#expAmount').value='';
  if($('#expDate'))$('#expDate').value=new Date().toISOString().slice(0,10);
  if($('#expNote'))$('#expNote').value='';
  if($('#saveExpense'))$('#saveExpense').textContent='Save expense';
}

function renderExpenses(){
  const list=$('#expenseList');
  if(!list)return;

  if(!expenses.length){
    list.innerHTML='<p class="muted">No expenses recorded yet.</p>';
    return;
  }

  const sorted=[...expenses].sort(
    (a,b)=>String(b.date||'').localeCompare(String(a.date||''))
  );

  const matches=
    sorted.filter(e=>
      vfIncExpMatches(
        [
          vfExpenseCategoryLabel(e.category),
          e.date,
          e.note,
          money(Number(e.amount||0)),
          String(e.amount||'')
        ],
        vfIncExpSearch
      )
    );

  if(!matches.length){
    list.innerHTML=
      `<p class="muted">No expenses match `+
      `"${esc(vfIncExpSearch.trim())}".</p>`;
    return;
  }

  list.innerHTML=
    vfIncExpSearchNote(matches.length,sorted.length,'expense')+
    matches.map(e=>`
    <div class="vf-expense-row">
      <div class="vf-expense-row-main">
        <strong>${esc(vfExpenseCategoryLabel(e.category))}</strong>
        <span class="muted">${esc(e.date||'')}</span>
        ${e.note?`<p class="muted">${esc(e.note)}</p>`:''}
      </div>
      <div class="vf-expense-row-amount">${money(Number(e.amount||0))}</div>
      <div class="vf-expense-row-actions">
        <button type="button" class="vf-secondary-button" data-edit-expense="${e.id}">Edit</button>
        <button type="button" class="vf-secondary-button" data-delete-expense="${e.id}">Delete</button>
      </div>
    </div>
  `).join('');

  list.querySelectorAll('[data-delete-expense]').forEach(btn=>{
    btn.onclick=()=>deleteExpense(btn.dataset.deleteExpense);
  });

  list.querySelectorAll('[data-edit-expense]').forEach(btn=>{
    btn.onclick=()=>vfEditExpense(btn.dataset.editExpense);
  });
}


/*
 * Editing reuses the Add form. This edits the one expense, not any
 * repeat schedule attached to it -- repeats are edited from the
 * schedule list.
 */
function vfEditExpense(expenseId){

  const item=
    expenses.find(x=>x.id===expenseId);

  if(!item){
    return toast('That expense is no longer here.');
  }

  clearExpenseForm();
  vfRepeatClear('exp');

  editingExpenseId=expenseId;

  if($('#expCategory'))$('#expCategory').value=item.category||'other';
  if($('#expAmount'))$('#expAmount').value=item.amount ?? '';
  if($('#expDate'))$('#expDate').value=item.date||'';
  if($('#expNote'))$('#expNote').value=item.note||'';
  if($('#saveExpense'))$('#saveExpense').textContent='Update expense';

  show($('#expenseForm'));

  $('#expenseForm').scrollIntoView({behavior:'smooth',block:'nearest'});
}

async function deleteExpense(expenseId){
  const expense=expenses.find(e=>e.id===expenseId);
  if(!expense)return;

  const ok=confirm(
    `Delete this expense?\n\n${vfExpenseCategoryLabel(expense.category)} — ${money(Number(expense.amount||0))}`
  );

  if(!ok)return;

  await deleteDoc(
    doc(db,'vendors',user.uid,'expenses',expenseId)
  );

  await log(
    'Expense deleted',
    `${vfExpenseCategoryLabel(expense.category)} — ${money(Number(expense.amount||0))}.`,
    'Manual'
  );

  await refreshAll();
  renderExpenses();
  renderTaxSummary();

  toast('Expense deleted.');
}

if($('#addExpense')){
  $('#addExpense').onclick=()=>{
    clearExpenseForm();
    show($('#expenseForm'));
  };
}

if($('#cancelExpense')){
  $('#cancelExpense').onclick=()=>{
    clearExpenseForm();
    hide($('#expenseForm'));
  };
}

if($('#saveExpense')){
  $('#saveExpense').onclick=async()=>{

    const amount=Number($('#expAmount').value);

    if(!amount){
      return toast('Enter an amount.');
    }

    const d={
      category:$('#expCategory').value,
      amount,
      date:$('#expDate').value || new Date().toISOString().slice(0,10),
      note:$('#expNote').value.trim(),
      updatedAt:serverTimestamp()
    };

    /*
     * Editing a repeat, not adding an expense. The form is being
     * used to change the rule's own settings and template, so no
     * expense is created -- doing so added a duplicate every time a
     * schedule was adjusted.
     */
    if(vfEditingRecurrenceId){

      await vfRepeatSaveRule('exp',d,d.date);

      clearExpenseForm();
      vfRepeatClear('exp');
      hide($('#expenseForm'));

      await refreshAll();
      renderExpenses();
      renderTaxSummary();
      vfRenderAllRepeatLists();

      return toast('Repeat updated.');
    }

    /*
     * Editing an expense that already exists. Update in place, and
     * do NOT touch any repeat rule -- vfRepeatSaveRule below is for
     * newly added expenses only.
     */
    if(editingExpenseId){

      const editingId=editingExpenseId;

      await updateDoc(
        doc(db,'vendors',user.uid,'expenses',editingId),
        d
      );

      await log(
        'Expense updated',
        `${vfExpenseCategoryLabel(d.category)} — ${money(amount)}.`,
        'Manual'
      );

      clearExpenseForm();
      vfRepeatClear('exp');
      hide($('#expenseForm'));

      await refreshAll();
      renderExpenses();
      renderTaxSummary();

      return toast('Expense updated.');
    }

    await addDoc(
      sub('expenses'),
      {
        ...d,
        createdAt:serverTimestamp()
      }
    );

    await log(
      'Expense added',
      `${vfExpenseCategoryLabel(d.category)} — ${money(amount)}.`,
      'Manual'
    );

    await vfRepeatSaveRule('exp',d,d.date);

    clearExpenseForm();
    vfRepeatClear('exp');
    hide($('#expenseForm'));

    await refreshAll();
    renderExpenses();
    renderTaxSummary();
    vfRenderAllRepeatLists();

    toast('Expense saved.');
  };
}

/* ============================================================
   EXPENSE STATEMENT IMPORT

   Mirrors the income statement import deliberately: same worker
   endpoint, same review-before-saving flow, same duplicate
   warnings. The differences are that OUTGOING money is what we
   want here, and that each row needs an IRS category.
   ============================================================ */

let vfExpenseImportRows=[];
let vfExpenseImportBusy=false;

/*
 * The Vault record for the statement currently under review. Stamped
 * onto every row imported from it, so the file can later show which
 * transactions came out of it -- and so an imported row can point
 * back at the document that produced it.
 */
let vfExpenseImportVaultId=null;


/*
 * A first guess at the IRS category from the merchant text. Only a
 * guess -- every row shows a dropdown and the vendor can change it
 * before anything is saved. Anything unrecognised stays 'other'
 * rather than being forced into a category that looks plausible.
 */
const VF_EXPENSE_CATEGORY_HINTS=[
  {key:'advertising',words:['facebook','google ads','instagram','advertis','flyer','printing','vistaprint','canva']},
  {key:'carMileage',words:['gas','fuel','shell','chevron','76 ','arco','parking','dmv','auto ','oil change']},
  {key:'contractLabor',words:['contractor','1099','subcontract']},
  {key:'insurance',words:['insurance','liability','state farm','geico','allstate','hiscox','next insurance']},
  {key:'legalProfessional',words:['attorney','legal','lawyer','accountant','cpa','bookkeep','tax prep']},
  {key:'officeExpense',words:['office','staples','paper','ink','toner','postage','usps','fedex','ups store']},
  {key:'rentOtherProperty',words:['rent','lease','storage','workspace']},
  {key:'repairsMaintenance',words:['repair','maintenance','fix']},
  {key:'supplies',words:['supply','supplies','amazon','target','walmart','michaels','dollar','costco','craft']},
  {key:'taxesLicenses',words:['license','permit','franchise tax','secretary of state','tax ']},
  {key:'travel',words:['airline','flight','hotel','airbnb','delta air','southwest','united air','marriott','hilton']},
  {key:'meals',words:['restaurant','cafe','coffee','starbucks','doordash','grubhub','uber eats','pizza','deli']},
  {key:'utilities',words:['electric','water','internet','comcast','xfinity','verizon','at&t','t-mobile','spectrum','phone']},
  {key:'wages',words:['payroll','gusto','adp','wages']}
];


function vfGuessExpenseCategory(text){

  const hay=
    String(text||'').toLowerCase();

  if(!hay.trim()){
    return 'other';
  }

  for(const hint of VF_EXPENSE_CATEGORY_HINTS){

    if(hint.words.some(word=>hay.includes(word))){
      return hint.key;
    }
  }

  return 'other';
}


/*
 * Possible duplicates among expenses already recorded. Same shape
 * as the income check: amount to the cent, within three days, with
 * a matching note raising confidence but never ruling a match out.
 */
function vfFindExpenseDuplicates(entry){

  const amount=
    Number(entry.amount||0);

  if(!(amount>0)){
    return [];
  }

  const spent=
    Date.parse(`${entry.date}T12:00:00`);

  const withinThreeDays=
    other=>{

      if(Number.isNaN(spent)){
        return true;
      }

      const when=
        Date.parse(`${other}T12:00:00`);

      if(Number.isNaN(when)){
        return false;
      }

      return Math.abs(when-spent) <= 3*24*60*60*1000;
    };

  const sameNote=
    other=>{

      const x=String(entry.note||'').trim().toLowerCase();
      const y=String(other||'').trim().toLowerCase();

      return Boolean(x) && Boolean(y) && x===y;
    };

  const matches=[];

  expenses.forEach(item=>{

    if(entry.id && item.id===entry.id){
      return;
    }

    if(
      Math.abs(Number(item.amount||0)-amount)<0.005 &&
      withinThreeDays(item.date)
    ){
      matches.push({
        kind:'expense',
        label:
          `${vfExpenseCategoryLabel(item.category)}`+
          `${item.note?` — ${item.note}`:''}`+
          ` on ${item.date||'an unknown date'}`,
        confident:sameNote(item.note)
      });
    }
  });

  return matches.sort(
    (x,y)=>Number(y.confident)-Number(x.confident)
  );
}


function vfBuildExpenseImportRows(data){

  const list=
    Array.isArray(data?.transactions)
      ? data.transactions
      : [];

  return list
    .map((tx,index)=>{

      const amount=
        Math.abs(Number(tx.amount||0));

      const direction=
        vfIncomeImportDirection(tx);

      const note=
        String(
          tx.memo ||
          tx.description ||
          tx.payer ||
          ''
        ).trim();

      const entry={
        amount,
        date:String(tx.date||'').slice(0,10),
        note
      };

      const duplicates=
        amount>0
          ? vfFindExpenseDuplicates(entry)
          : [];

      return {
        id:`exp-import-${index}`,
        amount,
        date:entry.date,
        note,
        merchant:String(tx.payer||'').trim(),
        method:String(tx.method||'').trim(),
        direction,
        duplicates,

        /*
         * Money coming IN is not an expense, and a possible
         * duplicate is money already counted. Both start unticked,
         * as does an uncertain direction -- overstating deductions
         * is the wrong way to be wrong.
         */
        include:
          direction==='outgoing' &&
          amount>0 &&
          duplicates.length===0,

        category:
          vfGuessExpenseCategory(`${note} ${tx.payer||''}`)
      };
    })
    .filter(row=>row.amount>0);
}


function vfRenderExpenseImportResults(){

  const host=$('#expenseStatementResults');

  if(!host){
    return;
  }

  if(!vfExpenseImportRows.length){
    host.innerHTML='';
    return;
  }

  const categoryOptions=
    row=>
      VF_EXPENSE_CATEGORIES
        .map(c=>
          `<option value="${esc(c.key)}" ${
            c.key===row.category ? 'selected' : ''
          }>${esc(c.label)} (${esc(c.line)})</option>`
        )
        .join('');

  const outgoing=
    vfExpenseImportRows.filter(r=>r.direction==='outgoing').length;

  const flagged=
    vfExpenseImportRows.filter(r=>r.duplicates.length).length;

  host.innerHTML=`
    <div class="vf-income-import-summary">
      <strong>${vfExpenseImportRows.length} transaction${
        vfExpenseImportRows.length===1?'':'s'
      } found</strong>
      <span class="muted">
        ${outgoing} going out${
          flagged
            ? ` · ${flagged} may already be recorded`
            : ''
        }
      </span>
    </div>

    <div class="tablewrap">
      <table>
        <thead>
          <tr>
            <th>Import</th>
            <th>Date</th>
            <th>Paid to</th>
            <th>Amount</th>
            <th>Category</th>
            <th>Notes</th>
          </tr>
        </thead>
        <tbody>
          ${
            vfExpenseImportRows.map(row=>`
              <tr class="${row.duplicates.length?'vf-income-import-dup':''}">
                <td>
                  <input
                    type="checkbox"
                    data-expense-import-pick="${esc(row.id)}"
                    ${row.include?'checked':''}>
                </td>
                <td>${esc(row.date||'—')}</td>
                <td>${esc(row.merchant||'—')}</td>
                <td>${money(row.amount)}</td>
                <td>
                  <select class="input" data-expense-import-category="${esc(row.id)}">
                    ${categoryOptions(row)}
                  </select>
                </td>
                <td>
                  ${
                    row.direction==='incoming'
                      ? '<div class="vf-income-import-note">Money coming in — not an expense</div>'
                      : ''
                  }
                  ${
                    row.direction==='uncertain'
                      ? '<div class="vf-income-import-note">VendorFlow could not tell which way this went</div>'
                      : ''
                  }
                  ${
                    row.duplicates.length
                      ? `<div class="vf-income-import-warning">
                           May already be recorded: ${esc(row.duplicates[0].label)}
                         </div>`
                      : ''
                  }
                  ${
                    row.note
                      ? `<div class="muted">${esc(row.note)}</div>`
                      : ''
                  }
                </td>
              </tr>
            `).join('')
          }
        </tbody>
      </table>
    </div>

    <div class="row">
      <button type="button" id="vfExpenseImportRun" class="primary">
        Import selected
      </button>
      <button type="button" id="vfExpenseImportCancel">Cancel</button>
    </div>
  `;

  host.querySelectorAll('[data-expense-import-pick]').forEach(box=>{
    box.onchange=()=>{
      const row=
        vfExpenseImportRows.find(
          r=>r.id===box.dataset.expenseImportPick
        );
      if(row){
        row.include=box.checked;
      }
    };
  });

  host.querySelectorAll('[data-expense-import-category]').forEach(select=>{
    select.onchange=()=>{
      const row=
        vfExpenseImportRows.find(
          r=>r.id===select.dataset.expenseImportCategory
        );
      if(row){
        row.category=select.value;
      }
    };
  });

  const cancel=$('#vfExpenseImportCancel');

  if(cancel){
    cancel.onclick=()=>{
      vfExpenseImportRows=[];
      vfRenderExpenseImportResults();
      if($('#expenseStatementFile'))$('#expenseStatementFile').value='';
      if($('#expenseStatementStatus'))$('#expenseStatementStatus').textContent='';
    };
  }

  const run=$('#vfExpenseImportRun');

  if(run){
    run.onclick=()=>vfRunExpenseImport();
  }
}


async function vfRunExpenseImport(){

  if(vfExpenseImportBusy){
    return;
  }

  const chosen=
    vfExpenseImportRows.filter(r=>r.include);

  if(!chosen.length){
    return toast('Tick at least one transaction to import.');
  }

  const flagged=
    chosen.filter(r=>r.duplicates.length).length;

  if(flagged){

    const proceed=
      confirm(
        `${flagged} of the ${chosen.length} selected `+
        `${flagged===1?'transaction looks':'transactions look'} like `+
        `money VendorFlow has already recorded as an expense.\n\n`+
        `Importing ${flagged===1?'it':'them'} would deduct that `+
        `money twice.\n\nImport anyway?`
      );

    if(!proceed){
      return;
    }
  }

  vfExpenseImportBusy=true;

  const run=$('#vfExpenseImportRun');

  if(run){
    run.disabled=true;
    run.textContent='Importing…';
  }

  let saved=0;

  try{

    for(const row of chosen){

      await addDoc(
        sub('expenses'),
        {
          amount:row.amount,
          date:
            row.date ||
            new Date().toISOString().slice(0,10),
          category:row.category||'other',
          note:row.note,
          method:row.method,
          source:'Statement import',
          vaultFileId:vfExpenseImportVaultId||'',
          createdAt:serverTimestamp(),
          updatedAt:serverTimestamp()
        }
      );

      saved++;
    }

    const total=
      chosen.reduce((sum,r)=>sum+r.amount,0);

    await log(
      'Expenses imported',
      `${saved} transaction${saved===1?'':'s'} imported from a `+
      `statement, ${money(total)} in total.`+
      `${flagged?` ${flagged} were flagged as possible duplicates and imported anyway.`:''}`,
      'Imported'
    );

    vfExpenseImportRows=[];
    vfRenderExpenseImportResults();

    if($('#expenseStatementFile'))$('#expenseStatementFile').value='';

    if($('#expenseStatementStatus')){
      $('#expenseStatementStatus').textContent=
        `Imported ${saved} transaction${saved===1?'':'s'}.`;
    }

    await refreshAll();
    renderExpenses();
    renderTaxSummary();

    toast(`Imported ${saved} into expenses.`);

  }catch(error){

    console.error('Expense import failed:',error);

    toast(
      `Imported ${saved} before this failed: ${
        error.message || 'something went wrong'
      }`
    );

    if(saved){
      await refreshAll();
      renderExpenses();
      renderTaxSummary();
    }

  }finally{

    vfExpenseImportBusy=false;

    if(run){
      run.disabled=false;
      run.textContent='Import selected';
    }
  }
}


if($('#expenseStatementFile')){

  $('#expenseStatementFile').addEventListener('change',async event=>{

    const file=event.target.files?.[0];

    if(!file || !user){
      return;
    }

    const status=$('#expenseStatementStatus');

    vfExpenseImportRows=[];
    vfRenderExpenseImportResults();

    if(status){
      status.textContent=`Reading ${file.name}…`;
    }

    try{

      const token=
        await user.getIdToken();

      const form=new FormData();
      form.append('file',file,file.name);

      const response=
        await fetch(
          `${VENDORFLOW_API}/payment-statement/extract`,
          {
            method:'POST',
            headers:{Authorization:`Bearer ${token}`},
            body:form
          }
        );

      let data={};

      try{
        data=await response.json();
      }catch{}

      if(!response.ok){
        throw new Error(
          data?.detail ||
          data?.error ||
          `Statement reader returned ${response.status}.`
        );
      }

      vfExpenseImportVaultId=
        await vfRecordVaultFile(
          data?.storedFile,
          'statement',
          'Expense import'
        );

      vfExpenseImportRows=
        vfBuildExpenseImportRows(data);

      vfRenderExpenseImportResults();

      if(status){

        status.textContent=
          vfExpenseImportRows.length
            ? `Read ${file.name}. Nothing has been imported yet — choose what to keep.`
            : `Read ${file.name}, but found no transactions to import.`;
      }

    }catch(error){

      console.error('Expense statement read failed:',error);

      if(status){
        status.textContent=
          error.message ||
          'Could not read that statement.';
      }

      toast('Could not read that statement.');
    }
  });
}


function vfAvailableTaxYears(){
  const years=new Set();
  years.add(String(new Date().getFullYear()));

  payments.forEach(p=>{
    if(p.date)years.add(String(p.date).slice(0,4));
  });

  expenses.forEach(e=>{
    if(e.date)years.add(String(e.date).slice(0,4));
  });

  return Array.from(years).sort((a,b)=>b.localeCompare(a));
}

function populateTaxYearSelect(){
  const select=$('#taxYear');
  if(!select)return;

  const years=vfAvailableTaxYears();
  const wanted=select.value || String(new Date().getFullYear());

  select.innerHTML=years.map(
    y=>`<option value="${y}">${y}</option>`
  ).join('');

  select.value=years.includes(wanted)?wanted:years[0];
}

function renderTaxSummary(){
  const body=$('#taxSummaryBody');
  if(!body)return;

  populateTaxYearSelect();

  const year=$('#taxYear').value || String(new Date().getFullYear());

  const totalIncome=payments
    .filter(p=>String(p.date||'').startsWith(year))
    .reduce((sum,p)=>sum+Number(p.amount||0),0);

  const yearExpenses=expenses.filter(
    e=>String(e.date||'').startsWith(year)
  );

  const totalExpenses=yearExpenses.reduce(
    (sum,e)=>sum+Number(e.amount||0),0
  );

  const categoryTotals=VF_EXPENSE_CATEGORIES.map(cat=>({
    ...cat,
    total:yearExpenses
      .filter(e=>e.category===cat.key)
      .reduce((sum,e)=>sum+Number(e.amount||0),0)
  }));

  /*
   * Gross income is what VendorFlow billed PLUS what was recorded by
   * hand on the Income page. Kept as two visible figures rather than
   * one merged number, because they answer different questions: the
   * recorded side is auditable back to a student and a certificate,
   * the added side is the vendor's own word. A preparer looking at
   * this in April should be able to see which is which.
   */
  const yearIncome=
    income.filter(
      item=>
        String(item.dateEarned||'').startsWith(year)
    );

  const addedIncome=
    yearIncome.reduce(
      (sum,item)=>sum+Number(item.amount||0),
      0
    );

  const grossIncome=
    totalIncome+addedIncome;

  const incomeCategoryTotals=
    VF_INCOME_CATEGORIES
      .map(cat=>({
        ...cat,
        total:
          yearIncome
            .filter(item=>item.category===cat.key)
            .reduce((sum,item)=>sum+Number(item.amount||0),0)
      }))
      .filter(cat=>cat.total>0);

  body.innerHTML=`
    <div class="vf-tax-summary-totals">
      <div class="vf-tax-summary-tile">
        <div class="eyebrow">Gross income</div>
        <div class="vf-tax-summary-figure">${money(grossIncome)}</div>
        ${
          addedIncome>0
            ? `<div class="muted vf-tax-summary-split">
                 ${money(totalIncome)} recorded by VendorFlow +
                 ${money(addedIncome)} you added
               </div>`
            : ''
        }
      </div>
      <div class="vf-tax-summary-tile">
        <div class="eyebrow">Total expenses</div>
        <div class="vf-tax-summary-figure">${money(totalExpenses)}</div>
      </div>
      <div class="vf-tax-summary-tile">
        <div class="eyebrow">Net</div>
        <div class="vf-tax-summary-figure">${money(grossIncome-totalExpenses)}</div>
      </div>
    </div>
    ${
      incomeCategoryTotals.length
        ? `
          <h3 class="vf-tax-summary-section">Income you added</h3>
          <table class="vf-tax-summary-table">
            <thead>
              <tr><th>Category</th><th>Total</th></tr>
            </thead>
            <tbody>
              ${
                incomeCategoryTotals.map(c=>`
                  <tr>
                    <td>${esc(c.label)}</td>
                    <td>${money(c.total)}</td>
                  </tr>
                `).join('')
              }
            </tbody>
          </table>`
        : ''
    }

    <h3 class="vf-tax-summary-section">Expenses</h3>
    <table class="vf-tax-summary-table">
      <thead>
        <tr><th>Category</th><th>IRS line</th><th>Total</th></tr>
      </thead>
      <tbody>
        ${categoryTotals.map(c=>`
          <tr>
            <td>${esc(c.label)}</td>
            <td class="muted">${esc(c.line)}</td>
            <td>${money(c.total)}</td>
          </tr>
        `).join('')}
      </tbody>
    </table>
  `;
}

if($('#taxYear')){
  $('#taxYear').onchange=()=>renderTaxSummary();
}

function money(v){
  return Number(v||0).toLocaleString(
    undefined,
    {
      style:'currency',
      currency:'USD'
    }
  );
}


function normalizedName(v){
  return String(v||'')
    .trim()
    .toLowerCase()
    .replace(/\s+/g,' ');
}


function coreStudentById(id){
  return students.find(
    s=>s.id===id
  );
}


function studentServices(studentId){
  return services.filter(
    s=>s.studentId===studentId && !s.deleted
  );
}


function refreshStudentServiceSelectors(){

  const studentSelect=$('#serviceStudent');

  if(studentSelect){

    const selected=studentSelect.value;

    studentSelect.innerHTML=
      '<option value="">Choose student</option>'+
      students
        .filter(student=>!vfStudentIsArchived(student))
        .sort(
          (a,b)=>
            (a.studentName||'')
              .localeCompare(b.studentName||'')
        )
        .map(
          s=>
            `<option value="${s.id}">
              ${esc(s.studentName||'Unnamed student')}
            </option>`
        )
        .join('');

    if(students.some(s=>s.id===selected)){
      studentSelect.value=selected;
    }
  }


  const classSelect=$('#serviceClass');

  if(classSelect){

    const selected=classSelect.value;

    classSelect.innerHTML=
      '<option value="">Not linked to a group</option>'+
      [...classes]
        .sort(
          (a,b)=>
            (a.name||'')
              .localeCompare(b.name||'')
        )
        .map(
          c=>
            `<option value="${c.id}">
              ${esc(c.name||'Group')}
              ${c.term?' — '+esc(c.term):''}
            </option>`
        )
        .join('');

    if(classes.some(c=>c.id===selected)){
      classSelect.value=selected;
    }
  }
}




function refundableParentAmount(student){

  if(!student){
    return 0;
  }

  /*
   * Parent-paid transactions only.
   * Negative amounts are prior refunds, so they naturally
   * reduce the remaining refundable total.
   */
  return Math.max(
    0,
    studentPayments(student)
      .filter(
        payment=>
          String(payment.method||'')
            .toLowerCase()!=='charter payment'
      )
      .reduce(
        (sum,payment)=>
          sum+Number(payment.amount||0),
        0
      )
  );
}


function renderRefundStudentSelect(){

  const select=
    $('#refundStudent');

  if(!select){
    return;
  }

  const current=
    select.value;

  select.innerHTML=
    '<option value="">Choose student</option>'+
    students
      .filter(studentVisibleInServices)
      .sort(
        (a,b)=>
          (a.studentName||'')
            .localeCompare(
              b.studentName||''
            )
      )
      .map(
        student=>
          `<option value="${student.id}">
            ${esc(student.studentName||'Unnamed student')}
            ${student.parentName
              ? ' — '+esc(student.parentName)
              : ''}
          </option>`
      )
      .join('');

  if(
    students.some(
      student=>student.id===current
    )
  ){
    select.value=current;
  }

  updateRefundAvailable();
}


function updateRefundAvailable(){

  const box=
    $('#refundAvailable');

  const select=
    $('#refundStudent');

  if(!box || !select){
    return;
  }

  const student=
    students.find(
      item=>item.id===select.value
    );

  if(!student){

    box.className=
      'vf-refund-available';

    box.textContent=
      'Choose a student to see refundable parent payments.';

    return;
  }

  const available=
    refundableParentAmount(
      student
    );

  box.className=
    available>0
      ? 'vf-refund-available vf-refund-positive'
      : 'vf-refund-available vf-refund-zero';

  box.innerHTML=
    `<strong>${money(available)}</strong>
     currently available from recorded parent payments.`;
}


