function resolvedLateFeeForObligation(obligation, classRecord){

  const classCurrentLateFee=
    Number(classRecord?.lateFee||0);

  if(classCurrentLateFee<=0){
    return 0;
  }

  return Number(
    obligation.lateFeeAmount ??
    classCurrentLateFee
  );
}


/*
 * Actually charges a late fee onto an obligation's real balance.
 * Runs during refreshAll(), same pattern as createDueInvoices().
 * Nothing before this function ever flipped lateFeeApplied to
 * true or added the fee to remainingAmount -- the fee only ever
 * showed up as warning text in reminder emails. This is the
 * missing piece that actually applies it, once, on the scheduled
 * lateFeeDate, using the amount that was locked in when the
 * obligation was created (unless the class's fee has since been
 * corrected to $0, which suppresses it -- same rule already used
 * for the reminder-email warning text).
 */
/*
 * If an already-charged late fee turns out to have been unfair --
 * the certificate/payment covering it is dated on or before the
 * due date, so it was actually on time, just entered into
 * VendorFlow after the fact -- undo it automatically. Mirrors
 * removeLateFeeManually()'s math, but runs on its own (no confirm()
 * dialog) and logs the reversal as Automatic so it's easy to spot.
 */
async function reverseLateFeeIfPaidOnTime(obligation){

  if(
    !obligation.lateFeeApplied ||
    !obligation.dueDate
  ){
    return;
  }

  const timelyRemaining=
    timelyRemainingForObligation(
      obligation,
      obligation.dueDate
    );

  if(timelyRemaining>0.009){
    return;
  }

  const chargedAmount=
    Number(obligation.lateFeeChargedAmount||0);

  if(chargedAmount<=0){
    return;
  }

  const currentRemaining=
    Number(
      obligation.remainingAmount ??
      obligation.amount ??
      0
    );

  const newRemaining=
    Math.max(
      0,
      Number(
        (currentRemaining-chargedAmount).toFixed(2)
      )
    );

  await setDoc(
    doc(
      db,
      'vendors',
      user.uid,
      'obligations',
      obligation.id
    ),
    {
      remainingAmount:
        newRemaining,

      lateFeeApplied:
        false,

      lateFeeChargedAmount:
        0,

      lateFeeAppliedAt:
        null,

      lateFeeRemovedAt:
        serverTimestamp(),

      lateFeeLastRemovedAmount:
        chargedAmount,

      lateFeeRemovalNoticeReviewedAt:
        null,

      updatedAt:
        serverTimestamp()
    },
    {
      merge:true
    }
  );

  await log(
    'Late fee removed automatically',
    `${money(chargedAmount)} late fee removed from ${obligation.studentName||'a student'}'s account for ${obligation.serviceName||obligation.className||'a payment'} -- the certificate or payment on file is dated on or before the due date, so it was actually on time. Balance is now ${money(newRemaining)}.`,
    'Automatic',
    {
      type:'obligation',
      id:obligation.id
    }
  );
}


async function applyLateFees(){

  /*
   * Nothing here should touch a real balance until the vendor has
   * explicitly clicked "Ready?" -- same rule already applied to
   * every automated parent email (see queuePaymentReminderReviews,
   * queueLateFeeChargedReviews, etc). Before this, applyLateFees()
   * ran on every refreshAll() regardless of that flag, so a late
   * fee could get charged to a real balance before the vendor ever
   * told VendorFlow to start automating anything.
   */
  if(profile?.betaSetupComplete===false){
    return 0;
  }

  if(!obligations.length){
    return 0;
  }

  const autoApply=
    profile?.automations?.applyLateFees===undefined
      ? true
      : Boolean(profile.automations.applyLateFees);

  const todayMs=
    Date.now();

  let applied=0;

  for(const obligation of obligations){

    if(obligation.deleted){
      continue;
    }

    if(vfObligationStudentIsArchived(obligation)){
      continue;
    }

    if(obligation.lateFeeApplied){

      await reverseLateFeeIfPaidOnTime(
        obligation
      );

      continue;
    }

    if(obligation.lateFeeWaived){
      continue;
    }

    if(!obligation.lateFeeDate){
      continue;
    }

    const feeMs=
      new Date(
        `${obligation.lateFeeDate}T00:00:00`
      ).getTime();

    if(Number.isNaN(feeMs) || feeMs>todayMs){
      continue;
    }

    const remaining=
      Number(
        obligation.remainingAmount ??
        obligation.amount ??
        0
      );

    if(remaining<=0.009){
      continue;
    }

    if(
      obligation.dueDate &&
      timelyRemainingForObligation(
        obligation,
        obligation.dueDate
      )<=0.009
    ){
      /*
       * Fully covered by certificates/payments actually dated on
       * or before the due date -- this was paid on time, just
       * entered into VendorFlow later. Never charge a late fee
       * for it.
       */
      continue;
    }

    const classRecord=
      classes.find(
        c=>c.id===obligation.classId
      ) || {};

    const lateFee=
      resolvedLateFeeForObligation(
        obligation,
        classRecord
      );

    if(lateFee<=0){
      continue;
    }

    if(!autoApply){
      continue;
    }

    const newRemaining=
      Number(
        (remaining+lateFee).toFixed(2)
      );

    await setDoc(
      doc(
        db,
        'vendors',
        user.uid,
        'obligations',
        obligation.id
      ),
      {
        remainingAmount:
          newRemaining,

        lateFeeApplied:
          true,

        lateFeeAppliedAt:
          serverTimestamp(),

        lateFeeChargedAmount:
          lateFee,

        updatedAt:
          serverTimestamp()
      },
      {
        merge:true
      }
    );

    await log(
      'Late fee charged',
      `${money(lateFee)} late fee added to ${obligation.studentName||'a student'}'s account for ${obligation.serviceName||obligation.className||'a payment'} -- balance is now ${money(newRemaining)}.`,
      'Automatic',
      {
        type:'obligation',
        id:obligation.id
      }
    );

    applied++;
  }

  return applied;
}


function defaultLateFeeChargedSubjectTemplate(){
  return `A late fee has been added to {{studentName}}'s account`;
}


function defaultLateFeeChargedBodyTemplate(){
  return `Hi {{parentName}},

A {{lateFeeAmount}} late fee has been added to {{studentName}}'s account for {{serviceName}}, since the {{originalAmountDue}} payment due {{dueDate}} hasn't come through yet. The total now due is {{newBalance}}.

I don't take late fees lightly, but they do apply once a payment is past due, and this one isn't something I'm able to waive as a courtesy. I'd really appreciate it if you could take care of this soon to keep the account up to date.

Payment instructions:
{{paymentInstructions}}

If you've already sent this in and it just hasn't been recorded yet, thank you -- and please let me know so I can double-check.

I'm testing a new tool that's helping me keep payments and charter certificates organized, so these emails may look a little different for now. If anything here doesn't look right, please don't hesitate to let me know and I'll check into it more carefully. Thank you for your understanding as I work through this new way of handling payments and charter funds.

Thank you,
{{businessName}}`;
}


function defaultLateFeeRemovedSubjectTemplate(){
  return `The late fee on {{studentName}}'s account has been removed`;
}


function defaultLateFeeRemovedBodyTemplate(){
  return `Hi {{parentName}},

Good news -- the {{lateFeeAmount}} late fee that was added to {{studentName}}'s account for {{serviceName}} has been removed. The payment (or charter certificate) on file for the {{dueDate}} due date was actually made on time, so the fee didn't apply after all. The balance is now {{newBalance}}.

No action is needed on your part -- I just wanted you to see the corrected balance.

Thank you,
{{businessName}}`;
}


/*
 * When "Apply late fees to family accounts" is turned off in
 * Settings > Automations, applyLateFees() itself never touches a
 * real balance -- this proposes the exact same charge instead, as
 * a Notifications card the vendor has to approve or decline.
 * Once approved (approveLateFeeChargeReview), the actual balance
 * change is identical to what applyLateFees() would have done
 * automatically.
 */
async function queueLateFeeChargeApprovals(){

  try{

    const autoApply=
      profile?.automations?.applyLateFees===undefined
        ? true
        : Boolean(profile.automations.applyLateFees);

    if(autoApply){
      return 0;
    }

    if(profile?.betaSetupComplete===false){
      return 0;
    }

    if(!obligations.length){
      return 0;
    }

    const todayMs=Date.now();
    let queued=0;

    for(const obligation of obligations){

      if(obligation.deleted)continue;
      if(obligation.lateFeeApplied)continue;
      if(obligation.lateFeeWaived)continue;
      if(!obligation.lateFeeDate)continue;

      const feeMs=
        new Date(`${obligation.lateFeeDate}T00:00:00`).getTime();

      if(Number.isNaN(feeMs) || feeMs>todayMs)continue;

      const remaining=
        Number(obligation.remainingAmount ?? obligation.amount ?? 0);

      if(remaining<=0.009)continue;

      if(
        obligation.dueDate &&
        timelyRemainingForObligation(obligation,obligation.dueDate)<=0.009
      ){
        continue;
      }

      const classRecord=
        classes.find(c=>c.id===obligation.classId) || {};

      const lateFee=
        resolvedLateFeeForObligation(obligation,classRecord);

      if(lateFee<=0)continue;

      /*
       * The vendor already said no to this exact charge -- don't
       * ask again unless the late-fee date itself changes (e.g. a
       * grace-period edit), which means it's really a new charge.
       */
      if(
        obligation.lateFeeChargeDeclinedForDate &&
        obligation.lateFeeChargeDeclinedForDate===obligation.lateFeeDate
      ){
        continue;
      }

      const alreadyQueued=
        reviews.some(
          r=>
            r.reviewType==='late-fee-charge-approval' &&
            r.obligationId===obligation.id
        );

      if(alreadyQueued)continue;

      const newRemaining=
        Number((remaining+lateFee).toFixed(2));

      await addDoc(
        sub('review'),
        {
          reviewType:'late-fee-charge-approval',

          obligationId:obligation.id,
          studentId:obligation.studentId||'',
          classId:obligation.classId||'',

          lateFeeAmount:lateFee,
          currentBalance:remaining,
          newBalance:newRemaining,
          lateFeeDate:obligation.lateFeeDate,

          title:
            `Late Fee: ${obligation.studentName||'Student'} — Approval Needed`,

          detail:
            `${obligation.serviceName||obligation.className||'A payment'} is past due. A ${money(lateFee)} late fee is ready to add -- the balance would become ${money(newRemaining)}.`,

          createdAt:serverTimestamp()
        }
      );

      queued++;
    }

    return queued;

  }catch(error){

    console.error('Could not queue late fee approvals:',error);
    return 0;
  }
}


async function approveLateFeeChargeReview(reviewId,{silent=false}={}){

  const review=
    reviews.find(r=>r.id===reviewId);

  if(!review || review.reviewType!=='late-fee-charge-approval'){
    return false;
  }

  const obligation=
    obligations.find(o=>o.id===review.obligationId);

  if(!obligation){

    await deleteDoc(doc(db,'vendors',user.uid,'review',reviewId));

    if(!silent){
      await refreshAll();
      toast('That late fee no longer applies.');
    }

    return false;
  }

  const remaining=
    Number(obligation.remainingAmount ?? obligation.amount ?? 0);

  const classRecord=
    classes.find(c=>c.id===obligation.classId) || {};

  const lateFee=
    resolvedLateFeeForObligation(obligation,classRecord);

  if(lateFee<=0){

    await deleteDoc(doc(db,'vendors',user.uid,'review',reviewId));

    if(!silent){
      await refreshAll();
      toast('That late fee no longer applies.');
    }

    return false;
  }

  const newRemaining=
    Number((remaining+lateFee).toFixed(2));

  try{

    await setDoc(
      doc(db,'vendors',user.uid,'obligations',obligation.id),
      {
        remainingAmount:newRemaining,
        lateFeeApplied:true,
        lateFeeAppliedAt:serverTimestamp(),
        lateFeeChargedAmount:lateFee,
        updatedAt:serverTimestamp()
      },
      {merge:true}
    );

    await deleteDoc(
      doc(db,'vendors',user.uid,'review',reviewId)
    );

    await log(
      'Late fee charged',
      `${money(lateFee)} late fee added to ${obligation.studentName||'a student'}'s account for ${obligation.serviceName||obligation.className||'a payment'} -- balance is now ${money(newRemaining)}.`,
      'Manual',
      {type:'obligation',id:obligation.id}
    );

  }catch(error){

    if(!silent){
      toast(error.message || 'Could not apply the late fee.');
    }

    return false;
  }

  if(!silent){
    await refreshAll();
    toast('Late fee applied.');
  }

  return true;
}


async function declineLateFeeChargeReview(reviewId){

  const review=
    reviews.find(r=>r.id===reviewId);

  if(!review || review.reviewType!=='late-fee-charge-approval'){
    return false;
  }

  const obligation=
    obligations.find(o=>o.id===review.obligationId);

  try{

    if(obligation){

      await setDoc(
        doc(db,'vendors',user.uid,'obligations',obligation.id),
        {
          lateFeeChargeDeclinedForDate:obligation.lateFeeDate||null,
          updatedAt:serverTimestamp()
        },
        {merge:true}
      );
    }

    await deleteDoc(
      doc(db,'vendors',user.uid,'review',reviewId)
    );

    await log(
      'Late fee not applied',
      `${obligation?.studentName||'A student'}'s late fee was not applied -- skipped for this due date.`,
      'Manual'
    );

  }catch(error){

    toast(error.message || 'Could not update that request.');
    return false;
  }

  await refreshAll();
  toast('Late fee not applied.');

  return true;
}


/*
 * Queues the one-time "a late fee was just charged" notice, once
 * applyLateFees() has actually applied one. Gated per-class on
 * lateFeeChargedReminderEnabled (a vendor may want the reminder-
 * before-due email but not this one, or vice versa) and per-
 * obligation on lateFeeChargeNoticeReviewedAt so it only ever
 * queues once per fee, exactly like the existing before-due
 * reminder's own one-time gate.
 */
async function queueLateFeeChargedReviews(){

  try{

    if(profile?.betaSetupComplete===false){
      return 0;
    }

    if(!obligations.length){
      return 0;
    }

    let queued=0;

    for(const obligation of obligations){

      if(obligation.deleted){
        continue;
      }

      if(!obligation.lateFeeApplied){
        continue;
      }

      if(obligation.lateFeeChargeNoticeReviewedAt){
        continue;
      }

      const chargedAmount=
        Number(obligation.lateFeeChargedAmount||0);

      if(chargedAmount<=0.009){
        continue;
      }

      const remaining=
        Number(
          obligation.remainingAmount ??
          obligation.amount ??
          0
        );

      if(remaining<=0.009){
        continue;
      }

      const classRecord=
        classes.find(
          c=>c.id===obligation.classId
        ) || {};

      if(!classRecord.lateFeeChargedReminderEnabled){
        continue;
      }

      const alreadyQueued=
        reviews.some(
          r=>
            r.reviewType==='late-fee-charged-email' &&
            r.obligationId===obligation.id
        );

      if(alreadyQueued){
        continue;
      }

      const student=
        students.find(
          s=>s.id===obligation.studentId
        );

      const parentEmail=
        String(student?.parentEmail||'').trim();

      if(!parentEmail){
        continue;
      }

      const originalAmount=
        Math.max(
          0,
          remaining-chargedAmount
        );

      const tokens={
        studentName:
          obligation.studentName ||
          student?.studentName ||
          '',

        parentName:
          student?.parentName || '',

        lateFeeAmount:
          money(chargedAmount),

        originalAmountDue:
          money(originalAmount),

        newBalance:
          money(remaining),

        dueDate:
          formatVendorDate(obligation.dueDate) ||
          obligation.dueDate,

        serviceName:
          obligation.serviceName ||
          obligation.className ||
          '',

        paymentInstructions:
          vfFormatPaymentInstructions(profile.paymentMethods||{}),

        businessName:
          profile.businessName || ''
      };

      const fillTemplate=text=>
        String(text||'').replace(
          /\{\{(\w+)\}\}/g,
          (match,key)=>
            tokens[key]!==undefined
              ? tokens[key]
              : ''
        );

      const subject=
        fillTemplate(
          classRecord.lateFeeChargedSubject ||
          defaultLateFeeChargedSubjectTemplate()
        );

      const body=
        fillTemplate(
          classRecord.lateFeeChargedBody ||
          defaultLateFeeChargedBodyTemplate()
        )
          .replace(/\n{3,}/g,'\n\n')
          .trim();

      const lateFeeChargedEmailData={
          reviewType:
            'late-fee-charged-email',

          obligationId:
            obligation.id,

          studentId:
            obligation.studentId||'',

          classId:
            obligation.classId||'',

          title:
            `Parent Email: Late Fee Notice — ${
              obligation.studentName ||
              student?.studentName ||
              'Student'
            } — Ready to Send`,

          detail:
            `${money(chargedAmount)} late fee added -- balance now ${money(remaining)}.`,

          to:
            parentEmail,

          subject,

          body,

          source:
            'VendorFlow',

          createdAt:
            serverTimestamp()
      };

      const lateFeeChargedEmailRef=
        await addDoc(
          sub('review'),
          lateFeeChargedEmailData
        );

      reviews.push({
        id:lateFeeChargedEmailRef.id,
        ...lateFeeChargedEmailData
      });

      if(profile?.automations?.emailParents){

        const sent=
          await sendLateFeeChargedReview(
            lateFeeChargedEmailRef.id,
            {silent:true}
          );

        if(sent){
          reviews=
            reviews.filter(
              r=>r.id!==lateFeeChargedEmailRef.id
            );
        }
      }

      queued++;
    }

    return queued;

  }catch(error){

    console.error(
      'Could not queue late fee notices:',
      error
    );

    return 0;
  }
}


