let inboundInboxMessages=[];
let inboundInboxLoading=false;
let inboundInboxSelectedIds=new Set();
let inboundInboxShowArchived=false;
let vfInboxPollTimer=null;
let vfReviewPollTimer=null;
let vfReviewsRefreshing=false;


function inboundInboxEscape(value){

  return String(value ?? '')
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#039;');
}


function inboundInboxLabel(value){

  const text=
    String(value || 'unknown')
      .trim()
      .replaceAll('-',' ')
      .replaceAll('_',' ');

  return text
    .replace(
      /\b\w/g,
      letter=>letter.toUpperCase()
    );
}


function inboundInboxDate(value){

  const date=
    new Date(value);

  if(
    Number.isNaN(
      date.getTime()
    )
  ){
    return String(value || 'Date unavailable');
  }

  return date.toLocaleString();
}


function renderInboundInbox(){

  const list=
    $('#inboundInboxList');

  const status=
    $('#inboundInboxStatus');

  const badge=
    $('#inboxBadge');


  if(!list){

    return;
  }

  inboundInboxSelectedIds=
    new Set(
      [...inboundInboxSelectedIds].filter(
        id=>
          inboundInboxMessages.some(
            message=>
              message.id===id
          )
      )
    );


  const attentionCount=
    inboundInboxMessages.filter(
      message=>
        message.needsAttention
    ).length;


  if(badge && !inboundInboxShowArchived){

    badge.textContent=
      attentionCount
        ? String(attentionCount)
        : '';
  }


  if(status){

    status.textContent=
      inboundInboxMessages.length
        ? (
            inboundInboxShowArchived
              ? `${inboundInboxMessages.length} archived email${
                  inboundInboxMessages.length===1
                    ? ''
                    : 's'
                }.`
              : `${inboundInboxMessages.length} received email${
                  inboundInboxMessages.length===1
                    ? ''
                    : 's'
                }. ${attentionCount} need${
                  attentionCount===1
                    ? 's'
                    : ''
                } attention.`
          )
        : '';
  }


  if(!inboundInboxMessages.length){

    list.innerHTML=
      inboundInboxShowArchived
        ? `
          <div class="vf-inbox-empty">
            <strong>No archived emails.</strong>
            <p>
              Emails you archive from the inbox will show up here.
            </p>
          </div>
        `
        : `
          <div class="vf-inbox-empty">
            <strong>No emails have been recorded yet.</strong>
            <p>
              New trusted emails sent to your VendorFlow address
              will appear here.
            </p>
          </div>
        `;

    return;
  }


  list.innerHTML=
    inboundInboxMessages
      .map(message=>{

        const classification=
          inboundInboxLabel(
            message.classification
          );

        const confidence=
          inboundInboxLabel(
            message.confidence
          );

        const attentionClass=
          message.needsAttention
            ? ' needs-attention'
            : '';

        const attachmentCount=
          Number(
            message.attachmentCount || 0
          );

        const attachmentText=
          attachmentCount
            ? `${attachmentCount} attachment${
                attachmentCount===1
                  ? ''
                  : 's'
              }`
            : 'No attachments';

        const amount=
          Number(
            message.amount || 0
          );

        const detailRows=[];


        const addDetail=(
          label,
          value
        )=>{

          const cleanValue=
            String(
              value ?? ''
            ).trim();


          if(!cleanValue){
            return;
          }


          detailRows.push(`
            <div class="vf-inbox-detail-label">
              ${inboundInboxEscape(label)}
            </div>

            <div class="vf-inbox-detail-value">
              ${inboundInboxEscape(cleanValue)}
            </div>
          `);
        };


        addDetail(
          'Outcome',
          inboundInboxLabel(
            message.outcome
          )
        );

        addDetail(
          'Student',
          message.studentName
        );

        addDetail(
          'Payer',
          message.payer
        );

        if(amount>0){

          addDetail(
            'Amount',
            new Intl.NumberFormat(
              'en-US',
              {
                style:'currency',
                currency:'USD'
              }
            ).format(amount)
          );
        }

        addDetail(
          'Payment method',
          message.paymentMethod
        );

        addDetail(
          'Payment date',
          message.paymentDate
        );

        addDetail(
          'Memo',
          message.memo
        );

        addDetail(
          'Service',
          message.serviceName
        );

        addDetail(
          'Charter school',
          message.charterSchool
        );

        addDetail(
          'Certificate number',
          message.certificateNumber
        );

        addDetail(
          'Service start',
          message.serviceStartDate
        );

        addDetail(
          'Service end',
          message.serviceEndDate
        );

        addDetail(
          'Service description',
          message.serviceDescription
        );

        /*
         * A skipped duplicate is not a failure, so it must not be
         * labelled like one. Reading "Processing error: this is the
         * same email VendorFlow already received" would send a
         * vendor hunting for a bug that isn't there.
         */
        const vfWasSkipped=
          message.outcome==='duplicate';

        addDetail(
          vfWasSkipped
            ? 'Why it was skipped'
            : 'Why VendorFlow stopped',
          message.reasons
        );

        addDetail(
          vfWasSkipped
            ? 'What happened'
            : 'Processing error',
          message.detail
        );

        addDetail(
          'Accounting record ID',
          message.relatedRecordId
        );

        addDetail(
          'Review record ID',
          message.reviewId
        );

        addDetail(
          'Sent to',
          message.recipient
        );

        addDetail(
          'Source message ID',
          message.sourceMessageId
        );




        const actionButtons=[];


        if(message.pdfObjectKey){

          actionButtons.push(`
            <button
              type="button"
              class="primary"
              data-inbox-pdf="${inboundInboxEscape(
                message.pdfObjectKey
              )}">
              View Attached Certificate PDF
            </button>
          `);
        }


        if(message.reviewId){

          actionButtons.push(`
            <button
              type="button"
              class="primary"
              data-inbox-view="review">
              Open Needs Review
            </button>
          `);
        }


        if(
          message.classification===
            'payment' ||
          message.outcome===
            'created' &&
          message.payer
        ){

          actionButtons.push(`
            <button
              type="button"
              data-inbox-view="payments">
              Open Payments/Charges
            </button>
          `);
        }


        if(
          message.classification===
            'certificate'
        ){

          actionButtons.push(`
            <button
              type="button"
              data-inbox-view="certificates">
              Open Certificates
            </button>
          `);
        }


        actionButtons.push(`
          <button
            type="button"
            data-inbox-archive="${inboundInboxEscape(
              message.id
            )}">
            ${inboundInboxShowArchived ? 'Unarchive' : 'Archive'}
          </button>
        `);


        return `
          <article
            class="vf-inbox-message${attentionClass}"
            data-inbox-message-id="${inboundInboxEscape(
              message.id
            )}">
            <div class="vf-inbox-message-top">
              <label class="vf-inbox-select-row" title="Select for bulk archive">
                <input
                  type="checkbox"
                  data-inbox-select="${inboundInboxEscape(
                    message.id
                  )}"
                  ${
                    inboundInboxSelectedIds.has(message.id)
                      ? 'checked'
                      : ''
                  }>
              </label>
              <div>
                <div class="vf-inbox-subject">
                  ${inboundInboxEscape(
                    message.subject ||
                    '(No subject)'
                  )}
                </div>

                <div class="vf-inbox-sender">
                  From:
                  <strong>
                    ${inboundInboxEscape(
                      message.sender ||
                      'Unknown sender'
                    )}
                  </strong>
                </div>
              </div>

              <div class="vf-inbox-time">
                ${inboundInboxEscape(
                  inboundInboxDate(
                    message.receivedAt
                  )
                )}
              </div>
            </div>

            <div class="vf-inbox-tags">
              <span class="vf-inbox-tag">
                ${inboundInboxEscape(
                  classification
                )}
              </span>

              <span class="vf-inbox-tag">
                ${inboundInboxEscape(
                  confidence
                )} confidence
              </span>

              ${
                message.reviewId
                  ? `
                    <button
                      type="button"
                      class="vf-inbox-tag vf-inbox-status vf-inbox-tag-button"
                      data-inbox-view="review"
                      title="Open this item in Needs Review">
                      ${inboundInboxEscape(
                        message.status ||
                        'Needs Review'
                      )}
                    </button>
                  `
                  : `
                    <span class="vf-inbox-tag vf-inbox-status">
                      ${inboundInboxEscape(
                        message.status ||
                        'Classified'
                      )}
                    </span>
                  `
              }

              ${
                message.needsAttention
                  ? '<span class="vf-inbox-tag attention">Needs attention</span>'
                  : ''
              }
            </div>

            <div class="vf-inbox-attachments">
              ${inboundInboxEscape(
                attachmentText
              )}

              ${
                message.attachmentNames
                  ? ` — ${inboundInboxEscape(
                      message.attachmentNames
                    )}`
                  : ''
              }
            </div>

            <details class="vf-inbox-details">
              <summary>
                View everything VendorFlow knows
              </summary>

              <div class="vf-inbox-body-section">

                <div class="vf-inbox-body-label">
                  Original email content
                </div>

                <div class="vf-inbox-body-text">
                  ${
                    String(message.bodyText||'').trim()
                      ? inboundInboxEscape(message.bodyText)
                      : 'VendorFlow did not capture any text for this email (it may have arrived with no plain-text version).'
                  }
                </div>

              </div>

              ${
                detailRows.length
                  ? `
                    <div class="vf-inbox-detail-grid">
                      ${detailRows.join('')}
                    </div>
                  `
                  : `
                    <div class="vf-inbox-no-details">
                      This earlier email has no additional
                      extracted details. New processed emails
                      will include them.
                    </div>
                  `
              }

              ${
                actionButtons.length
                  ? `
                    <div class="vf-inbox-actions">
                      ${actionButtons.join('')}
                    </div>
                  `
                  : ''
              }
            </details>
          </article>
        `;
      })
      .join('');


  $$(
    '#inboundInboxList [data-inbox-view]'
  ).forEach(button=>{

    button.onclick=()=>{

      switchView(
        button.dataset.inboxView
      );
    };
  });


  $$(
    '#inboundInboxList [data-inbox-pdf]'
  ).forEach(button=>{

    button.onclick=()=>{

      openCertificatePdf(
        button.dataset.inboxPdf
      );
    };
  });

  $$(
    '#inboundInboxList [data-inbox-select]'
  ).forEach(checkbox=>{

    checkbox.onchange=()=>{

      const id=
        checkbox.dataset.inboxSelect;

      if(checkbox.checked){
        inboundInboxSelectedIds.add(id);
      }else{
        inboundInboxSelectedIds.delete(id);
      }

      updateInboxBulkArchiveUI();
    };
  });

  $$(
    '#inboundInboxList [data-inbox-archive]'
  ).forEach(button=>{

    button.onclick=()=>{

      archiveInboundEmails(
        [button.dataset.inboxArchive],
        !inboundInboxShowArchived
      );
    };
  });

  updateInboxBulkArchiveUI();
}


/*
 * Keeps the "Select all" checkbox and "Archive Selected" button
 * (in the Email Inbox header) matched to inboundInboxSelectedIds.
 */
function updateInboxBulkArchiveUI(){

  const archiveButton=
    $('#archiveSelectedInboxEmails');

  if(archiveButton){

    const count=
      inboundInboxSelectedIds.size;

    const actionWord=
      inboundInboxShowArchived
        ? 'Unarchive'
        : 'Archive';

    archiveButton.disabled=
      count===0;

    archiveButton.textContent=
      count
        ? `${actionWord} Selected (${count})`
        : `${actionWord} Selected`;
  }

  const selectAll=
    $('#inboundInboxSelectAll');

  if(selectAll){

    selectAll.checked=
      inboundInboxMessages.length>0 &&
      inboundInboxSelectedIds.size===
        inboundInboxMessages.length;
  }
}


/*
 * Archives one or several inbox emails (POST /inbound/inbox/archive)
 * and removes them from the list on success -- archiving just hides
 * an email from the inbox, it doesn't touch any student/payment/
 * certificate records already created from it.
 */
async function archiveInboundEmails(emailIds, archived=true){

  const ids=[
    ...new Set(
      (emailIds||[]).filter(Boolean)
    )
  ];

  if(!ids.length){
    return;
  }

  try{

    const token=
      await user.getIdToken();

    const response=
      await fetch(
        `${VENDORFLOW_API}/inbound/inbox/archive`,
        {
          method:'POST',

          headers:{
            Authorization:
              `Bearer ${token}`,
            'Content-Type':
              'application/json'
          },

          body:
            JSON.stringify({
              emailIds:ids,
              archived
            })
        }
      );

    let data={};

    try{
      data=await response.json();
    }catch{}

    if(!response.ok || data.ok===false){

      throw new Error(
        data.error ||
        (archived ? 'Could not archive that email.' : 'Could not restore that email.')
      );
    }

    inboundInboxMessages=
      inboundInboxMessages.filter(
        message=>
          !ids.includes(message.id)
      );

    ids.forEach(
      id=>
        inboundInboxSelectedIds.delete(id)
    );

    renderInboundInbox();

    toast(
      archived
        ? (
            ids.length===1
              ? 'Email archived.'
              : `${ids.length} emails archived.`
          )
        : (
            ids.length===1
              ? 'Email restored to the inbox.'
              : `${ids.length} emails restored to the inbox.`
          )
    );

  }catch(error){

    toast(
      error.message ||
      (archived ? 'Could not archive that email.' : 'Could not restore that email.')
    );
  }
}



async function loadInboundInbox(){

  if(
    !user ||
    inboundInboxLoading
  ){
    return;
  }


  inboundInboxLoading=true;


  const status=
    $('#inboundInboxStatus');

  const refreshButton=
    $('#refreshInboundInbox');


  if(status){
    status.textContent=
      inboundInboxShowArchived
        ? 'Loading your archived emails…'
        : 'Loading your VendorFlow emails…';
  }


  if(refreshButton){
    refreshButton.disabled=true;
  }


  try{

    const token=
      await user.getIdToken();


    const inboxUrl=
      inboundInboxShowArchived
        ? `${VENDORFLOW_API}/inbound/inbox?archived=true`
        : `${VENDORFLOW_API}/inbound/inbox`;


    const response=
      await fetch(
        inboxUrl,
        {
          method:'GET',

          headers:{
            Authorization:
              `Bearer ${token}`
          }
        }
      );


    let data={};


    try{
      data=
        await response.json();
    }catch{}


    if(!response.ok){

      throw new Error(
        data.detail ||
        data.error ||
        'Email Inbox could not be loaded.'
      );
    }


    inboundInboxMessages=
      Array.isArray(data.messages)
        ? data.messages
        : [];


    renderInboundInbox();

  }catch(error){

    console.error(
      'VendorFlow Email Inbox failed:',
      error
    );


    if(status){

      status.textContent=
        error.message ||
        'Email Inbox could not be loaded.';
    }

  }finally{

    inboundInboxLoading=false;


    if(refreshButton){
      refreshButton.disabled=false;
    }
  }
}


function switchView(v){
  $$('.view').forEach(
    x=>x.classList.remove('active')
  );

  const selectedView=
    $(`#${v}View`);

  selectedView.classList.add('active');

  /*
   * Start every page at the top.
   *
   * Two things were wrong with the scrollIntoView() call this
   * replaces, and both were measured on the live site:
   *
   *   1. block:'start' puts the SECTION's top edge at the top of the
   *      window. The logo, page title and account header live above
   *      that section -- 203px of them -- so a successful scroll
   *      pushed the whole header off screen, and the page arrived
   *      looking as if it had already been scrolled down.
   *
   *   2. It ran a frame after the view was shown but before the
   *      view's data had rendered, so the document was often still
   *      too short to scroll at all. The call then did nothing and
   *      the page kept the PREVIOUS page's scroll position. Switching
   *      to Students from 247px down left it sitting at 247px down
   *      with the header 237px above the viewport.
   *
   * Scrolling to an absolute position fixes both. It needs no layout
   * to settle, so it is done synchronously rather than waiting for a
   * frame; and it cannot fail on a short document, because the target
   * is the top. A section that grows underneath afterwards cannot
   * drag the page away from there either.
   *
   * The target is the top of the content column, not the top of the
   * document. On a desktop layout the sidebar is a sticky grid column
   * that starts at document top, so this is plain scroll-to-top. On a
   * narrow layout the sidebar stacks above the content, so this still
   * skips past the navigation the way the old call did -- it just
   * stops one header earlier.
   */
  const vfScrollToPageTop=()=>{

    const column=
      selectedView.closest('main') || selectedView;

    const columnTop=
      column.getBoundingClientRect().top + window.scrollY;

    window.scrollTo({
      top:Math.max(0,columnTop),
      left:0,
      behavior:'auto'
    });
  };

  vfScrollToPageTop();

  /*
   * Re-asserted on the next frame purely as a backstop, in case
   * something rendered by this view moves the column underneath us.
   * It is the same absolute target, so a second call is a no-op
   * whenever nothing moved.
   */
  window.requestAnimationFrame(vfScrollToPageTop);

  let names={
    dashboard:'Dashboard',
    classes:'Groups',
    charters:'Charter Schools',
    students:'Students',
    payments:'Payments',
    expenses:'Income/Expenses',
    taxsummary:'Summary',
    certificates:'Certificates',
    invoices:'Invoices',
    compliance:'To-do List',
    inbox:'Email Inbox',
    review:'Notifications',
    history:'History',
    account:'Account',
    profile:'Business Profile',
    settings:'Settings',
    studentCommandCenter:'Student Account'
  };

  $('#title').textContent=names[v];

  $$('nav button').forEach(
    b=>b.classList.toggle(
      'active',
      b.dataset.view===v
    )
  );


  if(v==='inbox'){

    /*
     * Tim asked to remove the Email Inbox's automatic 30-second
     * poll -- it was causing more problems than it solved. Loading
     * the inbox when the tab is opened, plus the manual refresh
     * button already on that view, is enough.
     */
    loadInboundInbox();
  }


  if(v==='review'){

    refreshReviewsView();

    if(!vfReviewPollTimer){

      vfReviewPollTimer=
        setInterval(
          ()=>{

            /*
             * Belt and suspenders: only actually poll while the
             * Notifications tab is still the one on screen, in case
             * this timer somehow outlives a view switch.
             */
            if(
              $('#reviewView')?.classList.contains('active') &&
              !vfProposalEditingId
            ){
              refreshReviewsView();
            }
          },
          30000
        );
    }

  }else if(vfReviewPollTimer){

    clearInterval(
      vfReviewPollTimer
    );

    vfReviewPollTimer=null;
  }

  if(v==='expenses'){
    renderExpenses();
    renderIncome();
  }

  if(v==='taxsummary'){
    renderTaxSummary();
  }

  if(v==='settings'){
    renderLateFeesSettings();
    populateInvoicingDefaults();
    renderAutomationsSettings();
  }

  if(v==='studentCommandCenter'){
    renderStudentCommandCenter(vfCommandCenterStudentId);
  }

}

