$('#saveCharterSchool').onclick=async()=>{

  const name=
    $('#charterName')
      .value
      .trim();

  if(!name){

    return toast(
      'Enter the charter school name.'
    );
  }


  const invoiceDays=
    Math.max(
      0,
      Math.min(
        365,
        Math.round(
          Number(
            $('#charterInvoiceDays').value
          )||0
        )
      )
    );


  const existingCharterForSave=
    editingCharterSchoolId
      ? charterSchools.find(charter=>charter.id===editingCharterSchoolId)
      : null;

  const selectedBankRecord=
    selectedSharedCharterBankRecord || {};

  const existingSharedRecord=
    existingCharterForSave || {};


  const data={

    name,

    sharedBankId:
      String(
        selectedBankRecord.id ||
        existingSharedRecord.sharedBankId ||
        ''
      ),

    cdsCode:
      String(
        selectedBankRecord.cdsCode ||
        existingSharedRecord.cdsCode ||
        ''
      ),

    sharedVerifiedAt:
      String(
        selectedBankRecord.verifiedAt ||
        existingSharedRecord.sharedVerifiedAt ||
        ''
      ),

    sharedSourceUrl:
      String(
        selectedBankRecord.sourceUrl ||
        existingSharedRecord.sharedSourceUrl ||
        ''
      ),

    billingEmail:
      $('#charterBillingEmail')
        .value
        .trim(),

    phone:
      $('#charterPhone')
        .value
        .trim(),

    contactName:
      $('#charterContactName')
        .value
        .trim(),

    contactEmail:
      $('#charterContactEmail')
        .value
        .trim(),

    address:
      $('#charterAddress')
        .value
        .trim(),

    city:
      $('#charterCity')
        .value
        .trim(),

    state:
      $('#charterState')
        .value
        .trim(),

    zip:
      $('#charterZip')
        .value
        .trim(),

    invoiceDaysAfterStart:
      invoiceDays,

    notes:
      $('#charterNotes')
        .value
        .trim(),

    archived:false,

    updatedAt:
      serverTimestamp()
  };


  if(editingCharterSchoolId){

    await setDoc(
      doc(
        db,
        'vendors',
        user.uid,
        'charterSchools',
        editingCharterSchoolId
      ),
      data,
      {
        merge:true
      }
    );

    await log(
      'Charter school updated',
      name,
      'Manual'
    );

    toast(
      'Charter school updated.'
    );


  }else{

    const duplicate=
      charterSchools.find(
        charter=>
          !charter.archived &&
          String(charter.name||'')
            .trim()
            .toLowerCase()===
          name.toLowerCase()
      );

    if(duplicate){

      return toast(
        'That charter school is already in your list.'
      );
    }

    const newCharterRef=
      await addDoc(
        sub('charterSchools'),
        {
          ...data,
          createdAt:
            serverTimestamp()
        }
      );

    const newlyAddedCharter={
      id:newCharterRef.id,
      ...data
    };

    await log(
      'Charter school added',
      name,
      'Manual'
    );

    toast(
      'Charter school added.'
    );
  }


  const pendingCertificateFlow=
    sessionStorage.getItem(
      'vendorflowPendingCertificateCharter'
    );

  const savedCharterId=
    editingCharterSchoolId ||
    (
      typeof newlyAddedCharter!=='undefined'
        ? newlyAddedCharter.id
        : ''
    );


  resetCharterForm();

  hide(
    $('#charterForm')
  );

  await refreshAll();


  if(
    pendingCertificateFlow &&
    savedCharterId
  ){

    const savedCharter=
      charterSchools.find(
        charter=>
          charter.id===savedCharterId
      );

    if(savedCharter){

      restorePendingCertificateAfterCharterSave(
        savedCharter
      );
    }
  }
};




