/* ==========================================================
   BULK CERTIFICATE INTAKE
   ----------------------------------------------------------
   This intentionally reuses the proven single-PDF extraction
   service. It does NOT create certificates automatically yet.
   The first foundation pass reads each PDF and prepares a
   reviewable batch without changing financial records.
   ========================================================== */

let bulkCertificateItems=[];

/*
 * When checked, a vendor is telling VendorFlow it's fine to import
 * certificates (or payments, via the payments version of this flag
 * below) without a matched student -- VendorFlow will still flag the
 * item in Notifications so the vendor can connect it to a student
 * later, rather than being blocked from importing at all.
 */
let vfDeferCertStudentMatch=false;

/*
 * Same idea as vfDeferCertStudentMatch, but for the payment
 * statement importer.
 */
let vfDeferPaymentStudentMatch=false;




function showCertificateImportConfirmation(
  message='',
  action=''
){

  const box=
    $('#certificateImportConfirmation');

  if(!box){
    return;
  }


  const text=
    String(
      message || ''
    ).trim();


  box.textContent=
    text;


  box.dataset.action=
    String(
      action || ''
    );


  box.classList.toggle(
    'vf-certificate-import-confirmation-clickable',
    Boolean(
      text &&
      action
    )
  );


  box.classList.toggle(
    'hidden',
    !text
  );
}



if($('#certificateImportConfirmation')){

  $('#certificateImportConfirmation')
    .addEventListener(
      'click',
      ()=>{

        const box=
          $('#certificateImportConfirmation');


        const action=
          box?.dataset.action || '';


        if(action==='needs-review-page'){

          switchView(
            'review'
          );

          return;
        }


        if(action==='batch-review'){

          const item=
            bulkCertificateItems.find(
              entry=>
                entry.state==='review' ||
                entry.state==='ready'
            );


          if(item){

            openBulkCertificateReview(
              item.id
            );
          }
        }
      }
    );
}


function vendorReviewsCertificatesBeforeImport(){

  /*
   * Always true now -- every certificate is read automatically and
   * always requires the vendor to approve, edit, or deny it before
   * it's added. There's no reason to import one unread or
   * unapproved, so this is no longer a preference a vendor can turn
   * off.
   */
  return true;
}


function renderCertificateReviewPreference(){

  const input=
    $('#reviewCertificatesBeforeImport');

  if(!input){
    return;
  }


  input.checked=
    vendorReviewsCertificatesBeforeImport();
}


async function saveCertificateReviewPreference(){

  const input=
    $('#reviewCertificatesBeforeImport');

  if(!input || !user){
    return;
  }


  const enabled=
    Boolean(
      input.checked
    );


  try{

    await setDoc(
      vendorDoc(),
      {
        reviewCertificatesBeforeImport:
          enabled,

        updatedAt:
          serverTimestamp()
      },
      {
        merge:true
      }
    );


    profile={
      ...profile,

      reviewCertificatesBeforeImport:
        enabled
    };


    renderBulkCertificateItems();

    showCertificateImportConfirmation('');


    toast(
      enabled
        ? 'Certificate review is on.'
        : 'Certificate review is off. VendorFlow will import certificates it can verify safely.'
    );


    /*
     * If the vendor turns review OFF while a batch is already
     * waiting, immediately finalize only the certificates that
     * meet the stricter automatic-import rules.
     */
    if(
      !enabled &&
      bulkCertificateItems.length
    ){

      await importReadyBulkCertificates({
        automatic:true
      });
    }


  }catch(error){

    console.error(
      'Could not save certificate review preference:',
      error
    );


    input.checked=
      vendorReviewsCertificatesBeforeImport();


    toast(
      'VendorFlow could not save that preference.'
    );
  }
}


if($('#reviewCertificatesBeforeImport')){

  $('#reviewCertificatesBeforeImport')
    .addEventListener(
      'change',
      saveCertificateReviewPreference
    );
}


function bulkCertificateItemId(){

  return (
    'bulk-cert-' +
    Date.now() +
    '-' +
    Math.random()
      .toString(36)
      .slice(2,9)
  );
}


function resetBulkCertificateIntake(){

  bulkCertificateItems=[];

  const input=
    $('#bulkCertificateFiles');

  if(input){
    input.value='';
  }

  const list=
    $('#bulkCertificateList');

  if(list){
    list.innerHTML='';
  }

  const status=
    $('#bulkCertificateStatus');

  if(status){
    status.textContent='';
  }

  updateBulkCertificateSummary();

  hide(
    $('#bulkCertificateWorkspace')
  );
}


function updateBulkCertificateSummary(){

  const total=
    bulkCertificateItems.length;

  const ready=
    bulkCertificateItems.filter(
      item=>item.state==='ready'
    ).length;

  const review=
    bulkCertificateItems.filter(
      item=>item.state==='review'
    ).length;

  const errors=
    bulkCertificateItems.filter(
      item=>item.state==='error'
    ).length;


  if($('#bulkCertificateCount')){
    $('#bulkCertificateCount').textContent=
      String(total);
  }

  if($('#bulkCertificateReadyCount')){
    $('#bulkCertificateReadyCount').textContent=
      String(ready);
  }

  if($('#bulkCertificateReviewCount')){
    $('#bulkCertificateReviewCount').textContent=
      String(review);
  }

  if($('#bulkCertificateErrorCount')){
    $('#bulkCertificateErrorCount').textContent=
      String(errors);
  }
}



function exactBulkCertificateStudent(
  name
){

  const target=
    normalizedName(
      name || ''
    );

  if(!target){
    return null;
  }


  const matches=
    students.filter(
      student=>
        normalizedName(
          student.studentName || ''
        )===target
    );


  return matches.length===1
    ? matches[0]
    : null;
}



function bulkCertificateExistingDuplicate(
  item
){

  const x=
    bulkCertificateVendorExtraction(
      item
    );


  const number=
    String(
      x.certificateNumber ||
      x.purchaseOrderNumber ||
      ''
    ).trim();


  if(!number){
    return null;
  }


  return findDuplicateCertificate({
    number
  });
}


function bulkCertificateImportReadiness(
  item,
  options={}
){

  const automatic=
    Boolean(
      options.automatic
    );


  const x=
    bulkCertificateVendorExtraction(
      item
    );


  const student=
    exactBulkCertificateStudent(
      x.studentName ||
      x.student ||
      x.learnerName ||
      ''
    );


  const extractedCharterName=
    String(
      x.charterSchool ||
      x.charterSchoolName ||
      x.schoolName ||
      x.school ||
      ''
    ).trim();


  const charterResolution=
    resolveSavedCharterMatch(
      extractedCharterName
    );


  const charter=
    charterResolution.charter;


  const amount=
    Number(
      x.amount ||
      x.certificateAmount ||
      0
    );


  const number=
    String(
      x.certificateNumber ||
      x.purchaseOrderNumber ||
      ''
    ).trim();


  const serviceStartDate=
    String(
      x.serviceStartDate ||
      ''
    ).trim();


  /*
   * Automatic importing is deliberately stricter.
   *
   * It may use only a clean VendorFlow "ready" result.
   * A Needs Review item never slips through automatically.
   *
   * The manual "Import all ready certificates" button is a
   * superset of that: it also accepts anything a vendor has
   * individually edited or approved. It must NOT drop plain
   * "ready" items though -- that button's own label promises "no
   * need to preview each one," so a cleanly-read certificate has
   * to count as importable without the vendor first opening it and
   * clicking Looks correct. Missing `item.state==='ready'` here
   * made the button (and its count) silently exclude every
   * certificate VendorFlow read successfully but the vendor hadn't
   * yet clicked on individually -- which is why the button looked
   * like it did nothing on a fresh batch.
   */
  const reviewed=
    automatic
      ? item.state==='ready'
      : (
          item.state==='ready' ||
          item.vendorEdited ||
          item.vendorApproved
        );


  const problems=[];


  if(!reviewed){

    problems.push(
      automatic
        ? 'VendorFlow flagged this certificate for review.'
        : 'Open this certificate and either save a correction or choose Looks correct before importing.'
    );
  }


  if(!student && !vfDeferCertStudentMatch){

    problems.push(
      'Student does not match a saved VendorFlow student. Match one below, or choose "I\'ll match this student later".'
    );
  }


  if(!charter){

    if(
      charterResolution.candidates.length
    ){

      problems.push(
        'Charter school needs matching.'
      );

    }else{

      problems.push(
        `No saved charter school matches “${extractedCharterName || 'the extracted school name'}”.`
      );
    }
  }


  if(!(amount>0)){

    problems.push(
      'Certificate amount is missing.'
    );
  }


  if(!number){

    problems.push(
      'Certificate / PO number is missing.'
    );
  }


  if(!item?.result?.objectKey){

    problems.push(
      'Original PDF is not securely stored.'
    );
  }


  if(!serviceStartDate){

    problems.push(
      'Service start date is required.'
    );
  }


  return {

    ready:
      problems.length===0,

    problems,

    student,

    charter,

    charterResolution,

    extractedCharterName,

    extraction:x,

    amount,

    number,

    serviceStartDate
  };
}


function bulkCertificateImportableItems(
  options={}
){

  return bulkCertificateItems.filter(
    item=>
      bulkCertificateImportReadiness(
        item,
        options
      ).ready
  );
}


function updateBulkCertificateImportButton(){

  const button=
    $('#importReadyCertificates');

  if(!button){
    return;
  }


  const count=
    bulkCertificateImportableItems()
      .length;


  const manualReview=
    vendorReviewsCertificatesBeforeImport();


  button.classList.toggle(
    'hidden',
    !manualReview
  );


  button.disabled=
    count===0;


  button.textContent=
    count
      ? `Import all ${count} certificate${count===1?'':'s'} below (no need to preview each one)`
      : 'Import all certificates below (no need to preview each one)';
}


function bulkCertificateStateLabel(item){

  if(item.state==='reading'){
    return 'Reading PDF…';
  }

  if(item.state==='ready'){
    return 'Click to approve';
  }

  if(item.state==='review'){
    return 'Needs your review';
  }

  if(item.state==='error'){
    return 'Could not read';
  }

  if(item.state==='imported'){
    return 'Imported';
  }

  return 'Waiting';
}


function renderBulkCertificateItems(){

  const list=
    $('#bulkCertificateList');

  if(!list){
    return;
  }

  list.innerHTML='';


  for(const item of bulkCertificateItems){

    const row=
      document.createElement('div');

    row.className=
      'vf-bulk-item ' +
      `vf-bulk-item-${item.state}`;

    row.dataset.bulkCertificateReview=
      item.id;

    row.setAttribute(
      'role',
      'button'
    );

    row.setAttribute(
      'tabindex',
      '0'
    );

    row.setAttribute(
      'title',
      'Click to review VendorFlow’s certificate details'
    );


    const extraction=
      item.result?.extraction || {};


    const student=
      extraction.studentName ||
      extraction.student ||
      extraction.learnerName ||
      '';


    const school=
      extraction.charterSchool ||
      extraction.charterSchoolName ||
      extraction.school ||
      '';


    const amount=
      Number(
        extraction.amount ||
        extraction.certificateAmount ||
        0
      );


    const reference=
      extraction.certificateNumber ||
      extraction.purchaseOrderNumber ||
      '';


    const serviceDates=
      [
        extraction.serviceStartDate,
        extraction.serviceEndDate
      ]
        .filter(Boolean)
        .join(' – ');


    row.innerHTML=`
      <div class="vf-bulk-item-main">

        <div class="vf-bulk-file-name">
          ${esc(item.file.name)}
        </div>

        <div class="vf-bulk-item-details">

          ${
            student
              ? `<span>${esc(student)}</span>`
              : ''
          }

          ${
            school
              ? `<span>${esc(school)}</span>`
              : ''
          }

          ${
            amount
              ? `<span>${money(amount)}</span>`
              : ''
          }

          ${
            reference
              ? `<span>#${esc(reference)}</span>`
              : ''
          }

          ${
            serviceDates
              ? `<span>${esc(serviceDates)}</span>`
              : ''
          }

        </div>

        <div class="vf-bulk-review-hint">
          Click to check details
        </div>

      </div>

      <div class="vf-bulk-item-state">
        ${esc(bulkCertificateStateLabel(item))}
      </div>
    `;


    if(item.message){

      const message=
        document.createElement('div');

      message.className=
        'vf-bulk-item-message';

      message.textContent=
        item.message;

      row.appendChild(message);
    }


    list.appendChild(row);
  }


  updateBulkCertificateSummary();

  updateBulkCertificateImportButton();

  wireBulkCertificateReviewRows();
}


async function readOneBulkCertificate(item){

  item.state='reading';
  item.message='';
  item.result=null;

  renderBulkCertificateItems();


  let uploaded=null;


  try{

    /*
     * Follow the SAME proven pipeline as the existing
     * single-certificate workflow:
     *
     * 1. Securely upload the PDF.
     * 2. Read the stored PDF using its object key.
     * 3. Run the same client validation.
     *
     * Nothing is saved as a certificate here.
     */

    uploaded=
      await uploadCertificatePdf(
        item.file
      );


    /*
     * Keep the successful upload information immediately.
     * If extraction fails, the batch still knows that the
     * original PDF made it safely into secure storage.
     */
    item.result={
      ...uploaded,
      extraction:null,
      clientValidation:null,
      sourceTextLength:0
    };


    renderBulkCertificateItems();


    const extracted=
      await extractCertificatePdf(
        uploaded.objectKey
      );


    const extraction=
      extracted?.extraction || {};


    const clientValidation=
      validateExtractedCertificate(
        extracted
      );


    item.result={
      ...uploaded,
      extraction,
      clientValidation,
      sourceTextLength:
        Number(
          extracted?.sourceTextLength || 0
        )
    };


    /*
     * The existing validator is the authority here.
     * We do not invent a separate bulk validation system.
     */
    const validationNeedsReview=
      Boolean(
        clientValidation?.needsReview
      );


    const extractionNeedsReview=
      Boolean(
        extraction?.needsReview
      );


    const confidence=
      Number(
        extraction?.confidence || 0
      );


    if(
      validationNeedsReview ||
      extractionNeedsReview ||
      (
        confidence>0 &&
        confidence<0.75
      )
    ){

      item.state='review';

      item.message=
        'VendorFlow read this certificate, but it should be checked before importing.';

    }else{

      item.state='ready';

      item.message=
        'Certificate read successfully.';
    }


  }catch(error){

    console.error(
      'Bulk certificate read failed:',
      error
    );


    if(uploaded?.objectKey){

      /*
       * Match the behavior of the working single-file form:
       * upload success is not treated the same as upload failure.
       */
      item.state='review';

      item.result={
        ...(item.result || uploaded)
      };

      item.message=
        'PDF stored securely, but VendorFlow could not confidently read it. Review it before importing.';

    }else{

      item.state='error';

      item.message=
        error?.message ||
        'VendorFlow could not upload this PDF.';
    }
  }


  renderBulkCertificateItems();
}

async function processBulkCertificateBatch(){

  const button=
    $('#startBulkCertificates');

  if(!bulkCertificateItems.length){
    return;
  }


  if(button){
    button.disabled=true;
    button.textContent=
      'Reading certificates…';
  }


  const status=
    $('#bulkCertificateStatus');

  if(status){
    status.textContent=
      'VendorFlow is reading the certificates one at a time.';
  }


  /*
   * Sequential on purpose.
   *
   * This protects the existing upload/extraction service from a
   * sudden burst of simultaneous historical PDFs and makes the
   * batch easier to recover if one individual file fails.
   */
  for(
    let index=0;
    index<bulkCertificateItems.length;
    index++
  ){

    const item=
      bulkCertificateItems[index];


    if(
      item.state==='ready' ||
      item.state==='review'
    ){
      continue;
    }


    if(status){

      status.textContent=
        `Reading certificate ${index+1} of ${bulkCertificateItems.length}…`;
    }


    await readOneBulkCertificate(
      item
    );
  }


  if(button){
    button.disabled=false;
    button.textContent=
      'Read certificates';
  }


  const ready=
    bulkCertificateItems.filter(
      item=>item.state==='ready'
    ).length;

  const review=
    bulkCertificateItems.filter(
      item=>item.state==='review'
    ).length;

  const errors=
    bulkCertificateItems.filter(
      item=>item.state==='error'
    ).length;


  if(status){

    status.textContent=
      `${ready} read successfully` +
      `${review ? ` · ${review} need review` : ''}` +
      `${errors ? ` · ${errors} could not be read` : ''}. ` +
      (
        vendorReviewsCertificatesBeforeImport()
          ? `Nothing has been added to the account yet.`
          : `VendorFlow is finalizing certificates it can verify safely.`
      );
  }


  /*
   * Detect known duplicate certificate numbers BEFORE asking
   * the vendor to review/import them.
   *
   * A duplicate belongs in Needs Review, not in the normal
   * certificate-import flow.
   */
  const duplicateItems=
    bulkCertificateItems.filter(
      item=>
        item.state==='ready' &&
        Boolean(
          bulkCertificateExistingDuplicate(
            item
          )
        )
    );


  for(const duplicateItem of duplicateItems){

    await importReadyBulkCertificates({
      automatic:true,
      onlyItemId:
        duplicateItem.id,
      skipConfirmation:true
    });
  }


  /*
   * REVIEW ON:
   * The vendor already asked to review every certificate.
   * Open the first remaining certificate automatically.
   */
  if(
    vendorReviewsCertificatesBeforeImport()
  ){

    const nextItem=
      bulkCertificateItems.find(
        item=>
          item.state==='ready' ||
          item.state==='review'
      );


    if(nextItem){

      openBulkCertificateReview(
        nextItem.id
      );

    }else if(duplicateItems.length){

      showCertificateImportConfirmation(
        `${duplicateItems.length} possible duplicate` +
        `${duplicateItems.length===1?'':'s'} sent to Needs Review. ` +
        `Click to review.`,
        'needs-review-page'
      );
    }


    return;
  }


  /*
   * REVIEW OFF:
   * Only clean Ready items with exact/safe matches and all
   * required information are eligible for automatic import.
   */
  if(
    !vendorReviewsCertificatesBeforeImport()
  ){

    await importReadyBulkCertificates({
      automatic:true
    });


    /*
     * Automatic import must never fail silently.
     *
     * Anything still sitting in Ready state after the automatic
     * pass did not qualify for import. Convert it to Needs Review
     * and display the actual reason.
     */
    for(const item of bulkCertificateItems){

      if(item.state!=='ready'){
        continue;
      }


      const readiness=
        bulkCertificateImportReadiness(
          item,
          {
            automatic:true
          }
        );


      if(!readiness.ready){

        item.state='review';

        item.message=
          readiness.problems.join(' ');
      }
    }


    renderBulkCertificateItems();


    const remaining=
      bulkCertificateItems.length;


    if(remaining){

      const status=
        $('#bulkCertificateStatus');


      if(status){

        status.textContent=
          `${remaining} certificate` +
          `${remaining===1?'':'s'} need attention before importing.`;
      }


      showCertificateImportConfirmation(
        `${remaining} certificate` +
        `${remaining===1?'':'s'} need attention. ` +
        `Click to review.`,
        'batch-review'
      );
    }
  }
}



async function importReadyBulkCertificates(
  options={}
){

  const automatic=
    Boolean(
      options.automatic
    );

  const onlyItemId=
    String(
      options.onlyItemId || ''
    ).trim();

  const skipConfirmation=
    Boolean(
      options.skipConfirmation
    );


  const button=
    $('#importReadyCertificates');

  const status=
    $('#bulkCertificateStatus');


  const candidates=
    bulkCertificateImportableItems({
      automatic
    }).filter(
      item=>
        !onlyItemId ||
        item.id===onlyItemId
    );


  if(!candidates.length){

    if(!automatic){

      toast(
        'No certificates are ready to import yet.'
      );
    }

    return {
      imported:0,
      duplicates:0,
      skipped:0
    };
  }


  if(
    !automatic &&
    !skipConfirmation
  ){

    const ok=
      confirm(
        `Import ${candidates.length} ready certificate` +
        `${candidates.length===1?'':'s'}?\n\n` +
        `VendorFlow will add these certificate records now.\n\n` +
        `Possible duplicates will be sent to Needs Review instead of being imported twice.`
      );


    if(!ok){
      return {
        imported:0,
        duplicates:0,
        skipped:0
      };
    }
  }


  if(button){

    button.disabled=true;

    button.textContent=
      automatic
        ? 'Finalizing certificates…'
        : 'Importing certificates…';
  }


  let imported=0;
  let duplicates=0;
  let skipped=0;

  const vfCertificateEmailQueue=[];


  try{

    for(
      let index=0;
      index<candidates.length;
      index++
    ){

      const item=
        candidates[index];


      const readiness=
        bulkCertificateImportReadiness(
          item,
          {
            automatic
          }
        );


      /*
       * Re-check immediately before every Firestore write.
       */
      if(!readiness.ready){

        item.state='review';

        item.message=
          readiness.problems.join(' ');

        skipped++;

        continue;
      }


      const {
        student,
        charter,
        charterResolution,
        extractedCharterName,
        extraction:x,
        amount,
        number,
        serviceStartDate
      }=readiness;


      const invoiceSchedule=
        certificateInvoiceSchedule(
          serviceStartDate,
          charter,
          student?.id || ''
        );


      const materialsFee=
        Math.max(
          0,
          Number(
            x.materialsFee || 0
          )
        );


      const serviceAmount=
        Math.max(
          0,
          Number(
            x.serviceAmount ||
            Math.max(
              0,
              amount-materialsFee
            )
          )
        );


      const data={

        studentId:
          student?.id || '',

        student:
          student?.studentName ||
          String(
            x.studentName || ''
          ).trim(),

        parentName:
          student?.parentName || '',

        parentEmail:
          student?.parentEmail || '',


        school:
          charter.name,

        charterSchoolId:
          charter.id,

        charterSchoolName:
          charter.name,

        charterMatched:
          true,

        charterBillingEmail:
          charter.billingEmail || '',

        charterAddress:
          charter.address || '',

        charterCity:
          charter.city || '',

        charterState:
          charter.state || '',

        charterZip:
          charter.zip || '',


        serviceAmount,

        materialsFee,

        amount,

        number,

        status:
          'Received - Not Billed',

        source:
          automatic
            ? 'Automatic PDF import'
            : 'Bulk PDF import',

        matchedBy:
          student
            ? 'Exact student + charter match'
            : 'Charter match only -- vendor will connect student later',

        studentMatchPending:
          !student,


        pdfObjectKey:
          item.result?.objectKey || '',

        pdfName:
          item.result?.originalName ||
          item.file?.name ||
          '',

        pdfSize:
          Number(
            item.result?.size ||
            item.file?.size ||
            0
          ),

        pdfStored:
          Boolean(
            item.result?.objectKey
          ),


        issueDate:
          String(
            x.issueDate || ''
          ).trim(),

        serviceStartDate,

        serviceEndDate:
          String(
            x.serviceEndDate || ''
          ).trim(),

        serviceDescription:
          String(
            x.serviceDescription || ''
          ).trim(),

        billingEmail:
          String(
            x.billingEmail ||
            charter.billingEmail ||
            ''
          ).trim(),

        invoiceInstructions:
          String(
            x.invoiceInstructions || ''
          ).trim(),


        invoiceDaysAfterStart:
          invoiceSchedule.days,

        paymentTermsDays:
          invoicePaymentTermsDays(
            charter.paymentTermsDays
          ),

        invoiceReadyDate:
          invoiceSchedule.readyDate,

        invoiceScheduleValid:
          Boolean(
            invoiceSchedule.valid
          ),

        invoiceScheduleSource:
          invoiceSchedule.source || '',

        tutoringClassId:
          invoiceSchedule.tutoringClassId || '',

        tutoringClassName:
          invoiceSchedule.tutoringClassName || '',


        notes:'',

        extraction:{
          ...x
        },

        extractionConfidence:
          Number(
            x.confidence || 0
          ),

        extractionNeedsReview:
          false,


        bulkImported:
          true,

        automaticallyImported:
          automatic,

        vendorReviewed:
          Boolean(
            item.vendorEdited ||
            item.vendorApproved
          ),

        createdAt:
          serverTimestamp(),

        updatedAt:
          serverTimestamp()
      };


      const duplicateCertificate=
        findDuplicateCertificate(
          data
        );


      if(duplicateCertificate){

        await queueDuplicateReview(
          'certificate',
          data,
          duplicateCertificate
        );


        /*
         * This PDF is not an importable pending certificate anymore.
         * It now lives in the real Needs Review queue.
         */
        item.state='duplicate';

        item.duplicateQueued=true;

        item.message=
          'Possible duplicate — sent to Needs Review.';

        duplicates++;

        continue;
      }


      const importedCertificateRef=
        await addDoc(
          sub('certificates'),
          data
        );

      vfCertificateEmailQueue.push({
        certificateId:
          importedCertificateRef.id,

        data,

        studentMatch:
          student
      });


      /*
       * When VendorFlow makes a unique strong name match,
       * remember the PDF's charter name as an alias.
       *
       * Example:
       * Pacific Coast Academy
       *        ↕
       * Pacific Coast Academy (PCA)
       */
      if(
        charterResolution?.type==='strong' &&
        extractedCharterName
      ){

        await rememberCharterAlias(
          charter,
          extractedCharterName
        );
      }


      await log(
        'Certificate added',
        `${charter.name} certificate for ` +
        `${data.student} — ${money(amount)} — ` +
        `${automatic?'automatic':'bulk'} PDF import.`,
        'VendorFlow',
        {
          type:'certificate',
          id:importedCertificateRef.id
        }
      );


      item.state='imported';

      item.message=
        'Imported successfully.';

      imported++;


      if(status){

        status.textContent=
          automatic
            ? `Finalizing certificate ${index+1} of ${candidates.length}…`
            : `Importing certificate ${index+1} of ${candidates.length}…`;
      }
    }


    await refreshAll();


    for(const pendingEmail of vfCertificateEmailQueue){

      await queueCertificateReceivedEmail(
        pendingEmail.certificateId,
        pendingEmail.data,
        pendingEmail.studentMatch
      );
    }

    /*
     * Same reasoning as the single-certificate save: these email
     * reviews were created after refreshAll() already ran, so
     * refresh once more so they show up immediately.
     */
    if(vfCertificateEmailQueue.length){
      await refreshAll();
    }


    bulkCertificateItems=
      bulkCertificateItems.filter(
        item=>
          item.state!=='imported' &&
          !item.duplicateQueued
      );


    renderBulkCertificateItems();


    const summary=
      `${imported} certificate${imported===1?'':'s'} imported` +
      `${duplicates ? ` · ${duplicates} possible duplicate${duplicates===1?'':'s'} sent to review` : ''}` +
      `${skipped ? ` · ${skipped} skipped` : ''}.`;


    if(
      automatic &&
      imported>0 &&
      duplicates===0 &&
      skipped===0 &&
      bulkCertificateItems.length===0
    ){

      resetBulkCertificateIntake();

      showCertificateImportConfirmation(
        `${imported} certificate${imported===1?'':'s'} imported.`
      );

    }else{

      if(status){

        status.textContent=
          summary;
      }


      if(
        duplicates ||
        skipped
      ){

        const needsReviewOnly=
          duplicates>0 &&
          skipped===0;


        showCertificateImportConfirmation(
          `${imported} certificate${imported===1?'':'s'} imported. ` +
          `${duplicates+skipped} need attention. ` +
          `Click to review.`,
          needsReviewOnly
            ? 'needs-review-page'
            : 'batch-review'
        );
      }
    }


    if(!automatic){

      toast(
        summary
      );
    }


    return {
      imported,
      duplicates,
      skipped
    };


  }catch(error){

    console.error(
      'Certificate import failed:',
      error
    );


    toast(
      error?.message ||
      'VendorFlow could not finish importing the certificates.'
    );


    return {
      imported,
      duplicates,
      skipped,
      error
    };


  }finally{

    renderBulkCertificateItems();

    updateBulkCertificateImportButton();
  }
}


if($('#importReadyCertificates')){

  $('#importReadyCertificates')
    .addEventListener(
      'click',
      ()=>importReadyBulkCertificates({
        automatic:false,

        /*
         * This button's own label already promises "no need to
         * preview each one" -- a blocking native confirm() dialog
         * right after clicking it contradicted that promise, and
         * was very likely why the button looked like it "didn't
         * work": a vendor clicking the big blue button and getting
         * an unexpected native popup, easy to miss or misread as
         * nothing having happened. Skip it here; the button already
         * shows "Importing certificates..." while the real work is
         * in flight, which is the actual proof-of-life a vendor
         * needs.
         */
        skipConfirmation:true
      })
    );
}


if($('#chooseBulkCertificates')){

  $('#chooseBulkCertificates')
    .addEventListener(
      'click',
      ()=>{

        $('#bulkCertificateFiles')
          ?.click();
      }
    );
}


if($('#certDeferStudentMatch')){

  $('#certDeferStudentMatch')
    .addEventListener(
      'change',
      e=>{

        vfDeferCertStudentMatch=
          e.target.checked;

        /*
         * Re-check every already-scanned item against the new
         * preference and re-render so items that were blocked
         * only on a missing student become importable right away.
         */
        renderBulkCertificateItems();
        updateBulkCertificateImportButton();

        if(activeBulkCertificateReviewId){

          const current=
            bulkCertificateItems.find(
              entry=>
                entry.id===activeBulkCertificateReviewId
            );

          if(current){
            renderBulkCertificateReviewFields(current);
          }
        }
      }
    );
}


if($('#bulkCertificateFiles')){

  $('#bulkCertificateFiles')
    .addEventListener(
      'change',
      event=>{

        showCertificateImportConfirmation('');

        const files=[
          ...(event.target.files || [])
        ];


        const pdfs=
          files.filter(
            file=>
              file.type==='application/pdf' ||
              file.name
                .toLowerCase()
                .endsWith('.pdf')
          );

        if(pdfs.length>20){

          event.target.value='';

          resetBulkCertificateIntake();

          toast(
            'Choose no more than 20 certificate PDFs at a time.'
          );

          return;
        }


        bulkCertificateItems=
          pdfs.map(
            file=>({
              id:bulkCertificateItemId(),
              file,
              state:'waiting',
              result:null,
              message:''
            })
          );


        if(!bulkCertificateItems.length){

          resetBulkCertificateIntake();

          toast(
            'Choose one or more certificate PDFs.'
          );

          return;
        }


        /*
         * Remember (for the rest of this wizard visit) that a real
         * certificate batch was started here -- independent of
         * bulkCertificateItems later being cleared back to [] once
         * everything in it finishes importing. Without this, the
         * wizard's "upload more / go to next step" poll below never
         * fires after a fully successful import, since it was keyed
         * off items.length alone -- see vfWizardPollCertificatesLoop.
         */
        vfWizardCertBatchEverRan=true;


        show(
          $('#bulkCertificateWorkspace')
        );


        const status=
          $('#bulkCertificateStatus');

        if(status){

          status.textContent=
            `${bulkCertificateItems.length} certificate` +
            `${bulkCertificateItems.length===1 ? '' : 's'} selected. ` +
            `VendorFlow is reading them now.`;
        }


        renderBulkCertificateItems();

        processBulkCertificateBatch();
      }
    );
}


if($('#startBulkCertificates')){

  $('#startBulkCertificates')
    .addEventListener(
      'click',
      processBulkCertificateBatch
    );
}


if($('#clearBulkCertificates')){

  $('#clearBulkCertificates')
    .addEventListener(
      'click',
      resetBulkCertificateIntake
    );
}



/* ==========================================================
   BULK CERTIFICATE REVIEW
   ========================================================== */

let activeBulkCertificateReviewId='';

let activeBulkCertificatePdfDocument=null;

let activeBulkCertificatePdfData=null;

let bulkCertificatePdfZoom=1;


if(window.pdfjsLib){

  window.pdfjsLib.GlobalWorkerOptions.workerSrc=
    'vendor/pdfjs/pdf.worker.min.js';
}


function clearBulkCertificatePdf(){

  activeBulkCertificatePdfDocument=null;
  activeBulkCertificatePdfData=null;
  bulkCertificatePdfZoom=1;


  const pages=
    $('#bulkCertificatePdfPages');

  if(pages){
    pages.innerHTML='';
  }


  const status=
    $('#bulkCertificatePdfStatus');

  if(status){
    status.textContent='';
  }


  updateBulkCertificatePdfZoomLabel();
}


function updateBulkCertificatePdfZoomLabel(){

  const label=
    $('#bulkPdfZoomLabel');

  if(!label){
    return;
  }


  if(
    Math.abs(
      bulkCertificatePdfZoom-1
    )<0.01
  ){
    label.textContent='Fit';
    return;
  }


  label.textContent=
    `${Math.round(
      bulkCertificatePdfZoom*100
    )}%`;
}


async function renderBulkCertificatePdf(){

  const pdf=
    activeBulkCertificatePdfDocument;

  const pages=
    $('#bulkCertificatePdfPages');

  const viewportBox=
    $('#bulkCertificatePdfViewport');

  const status=
    $('#bulkCertificatePdfStatus');


  if(
    !pdf ||
    !pages ||
    !viewportBox
  ){
    return;
  }


  pages.innerHTML='';


  if(status){
    status.textContent=
      'Rendering certificate…';
  }


  try{

    const firstPage=
      await pdf.getPage(1);


    const baseViewport=
      firstPage.getViewport({
        scale:1
      });


    const availableWidth=
      Math.max(
        300,
        viewportBox.clientWidth-28
      );


    const fitScale=
      availableWidth /
      baseViewport.width;


    const renderScale=
      fitScale *
      bulkCertificatePdfZoom;


    const deviceScale=
      Math.min(
        window.devicePixelRatio || 1,
        2
      );


    for(
      let pageNumber=1;
      pageNumber<=pdf.numPages;
      pageNumber++
    ){

      const page=
        pageNumber===1
          ? firstPage
          : await pdf.getPage(
              pageNumber
            );


      const viewport=
        page.getViewport({
          scale:renderScale
        });


      const wrapper=
        document.createElement('div');

      wrapper.className=
        'vf-bulk-pdf-page';


      const canvas=
        document.createElement('canvas');


      canvas.width=
        Math.floor(
          viewport.width *
          deviceScale
        );

      canvas.height=
        Math.floor(
          viewport.height *
          deviceScale
        );


      canvas.style.width=
        `${Math.floor(
          viewport.width
        )}px`;

      canvas.style.height=
        `${Math.floor(
          viewport.height
        )}px`;


      const context=
        canvas.getContext('2d');


      wrapper.appendChild(
        canvas
      );

      pages.appendChild(
        wrapper
      );


      await page.render({
        canvasContext:context,
        viewport,
        transform:
          deviceScale===1
            ? null
            : [
                deviceScale,
                0,
                0,
                deviceScale,
                0,
                0
              ]
      }).promise;
    }


    if(status){
      status.textContent='';
    }


    updateBulkCertificatePdfZoomLabel();


  }catch(error){

    console.error(
      'Certificate PDF render failed:',
      error
    );


    if(status){
      status.textContent=
        error?.message ||
        'Could not display the certificate.';
    }
  }
}


async function loadBulkCertificatePdf(
  item
){

  clearBulkCertificatePdf();


  const status=
    $('#bulkCertificatePdfStatus');


  if(
    !item?.result?.objectKey
  ){

    if(status){
      status.textContent=
        'Original PDF is not available.';
    }

    return;
  }


  if(!window.pdfjsLib){

    if(status){
      status.textContent=
        'PDF viewer did not load.';
    }

    return;
  }


  if(status){
    status.textContent=
      'Loading original certificate…';
  }


  try{

    const token=
      await user.getIdToken();


    const response=
      await fetch(
        `${VENDORFLOW_API}/certificate/file/` +
        encodeURIComponent(
          item.result.objectKey
        ),
        {
          headers:{
            Authorization:
              `Bearer ${token}`
          }
        }
      );


    if(!response.ok){

      let data={};

      try{
        data=
          await response.json();
      }catch{}


      throw new Error(
        data.error ||
        'Could not load certificate PDF.'
      );
    }


    const arrayBuffer=
      await response.arrayBuffer();


    activeBulkCertificatePdfData=
      new Uint8Array(
        arrayBuffer
      );


    activeBulkCertificatePdfDocument=
      await window.pdfjsLib
        .getDocument({
          data:
            activeBulkCertificatePdfData
        })
        .promise;


    bulkCertificatePdfZoom=1;


    await renderBulkCertificatePdf();


    const viewport=
      $('#bulkCertificatePdfViewport');

    if(viewport){
      viewport.scrollLeft=0;
      viewport.scrollTop=0;
    }


  }catch(error){

    console.error(
      'Bulk certificate PDF preview failed:',
      error
    );


    if(status){
      status.textContent=
        error?.message ||
        'Could not display the original certificate.';
    }
  }
}


async function changeBulkPdfZoom(
  amount
){

  if(
    !activeBulkCertificatePdfDocument
  ){
    return;
  }


  bulkCertificatePdfZoom=
    Math.max(
      .5,
      Math.min(
        3,
        bulkCertificatePdfZoom+
        amount
      )
    );


  await renderBulkCertificatePdf();
}


async function fitBulkPdf(){

  if(
    !activeBulkCertificatePdfDocument
  ){
    return;
  }


  bulkCertificatePdfZoom=1;

  await renderBulkCertificatePdf();


  const viewport=
    $('#bulkCertificatePdfViewport');

  if(viewport){
    viewport.scrollLeft=0;
    viewport.scrollTop=0;
  }
}


if($('#bulkPdfZoomIn')){

  $('#bulkPdfZoomIn').onclick=
    ()=>changeBulkPdfZoom(.25);
}


if($('#bulkPdfZoomOut')){

  $('#bulkPdfZoomOut').onclick=
    ()=>changeBulkPdfZoom(-.25);
}


if($('#bulkPdfFit')){

  $('#bulkPdfFit').onclick=
    fitBulkPdf;
}



/*
 * Small read-only helpers used by the bulk certificate
 * list and verification window.
 *
 * These do NOT save anything or change financial data.
 */

function bulkCertificateExtraction(item){

  return item?.result?.extraction || {};
}


function bulkCertificateStudentName(item){

  const x=
    bulkCertificateExtraction(item);

  return (
    x.studentName ||
    x.student ||
    x.learnerName ||
    ''
  );
}


function bulkCertificateSchoolName(item){

  const x=
    bulkCertificateExtraction(item);

  return (
    x.charterSchool ||
    x.charterSchoolName ||
    x.schoolName ||
    x.school ||
    ''
  );
}


function bulkCertificateAmount(item){

  const x=
    bulkCertificateExtraction(item);

  return Number(
    x.amount ||
    x.certificateAmount ||
    0
  );
}


function bulkCertificateReference(item){

  const x=
    bulkCertificateExtraction(item);

  return (
    x.certificateNumber ||
    x.purchaseOrderNumber ||
    ''
  );
}



/*
 * The certificate evidence modal is authored inside the
 * Certificates view in index.html.
 *
 * Inactive VendorFlow views use display:none, so opening that
 * modal while the vendor is on Students, Actions, etc. would
 * technically open it INSIDE a hidden parent.
 *
 * Move the one shared modal to document.body once. It can then
 * be opened from every VendorFlow view.
 */
function moveCertificateEvidenceModalToRoot(){

  const modal=
    $('#bulkCertificateReviewModal');


  if(
    !modal ||
    modal.parentElement===document.body
  ){
    return;
  }


  document.body.appendChild(
    modal
  );
}


moveCertificateEvidenceModalToRoot();


/* ==========================================================
   BULK CERTIFICATE VENDOR REVIEW / CORRECTIONS
   ========================================================== */


let savedCertificateEvidenceMode=false;
let savedCertificateEvidenceId='';


function savedCertificateEvidenceItem(){

  if(
    !savedCertificateEvidenceMode ||
    !savedCertificateEvidenceId
  ){
    return null;
  }


  const cert=
    certs.find(
      item=>
        item.id===
        savedCertificateEvidenceId
    );


  if(!cert){
    return null;
  }


  const extraction={
    ...(cert.extraction || {}),

    studentName:
      cert.student ||
      cert.extraction?.studentName ||
      '',

    charterSchool:
      cert.charterSchoolName ||
      cert.school ||
      cert.extraction?.charterSchool ||
      '',

    serviceAmount:
      Number(
        cert.serviceAmount ??
        Math.max(
          0,
          Number(cert.amount||0) -
          Number(cert.materialsFee||0)
        )
      ),

    materialsFee:
      Number(
        cert.materialsFee || 0
      ),

    amount:
      Number(cert.amount||0),

    certificateNumber:
      cert.number ||
      cert.extraction?.certificateNumber ||
      '',

    issueDate:
      cert.issueDate ||
      cert.extraction?.issueDate ||
      '',

    serviceStartDate:
      cert.serviceStartDate ||
      cert.extraction?.serviceStartDate ||
      '',

    serviceEndDate:
      cert.serviceEndDate ||
      cert.extraction?.serviceEndDate ||
      '',

    billingEmail:
      cert.billingEmail ||
      cert.charterBillingEmail ||
      cert.extraction?.billingEmail ||
      '',

    serviceDescription:
      cert.serviceDescription ||
      cert.extraction?.serviceDescription ||
      '',

    invoiceInstructions:
      cert.invoiceInstructions ||
      cert.extraction?.invoiceInstructions ||
      ''
  };


  return {

    id:
      `saved-certificate-${cert.id}`,

    state:'saved',

    file:{
      name:
        cert.pdfName ||
        cert.number ||
        'Saved certificate'
    },

    result:{
      objectKey:
        cert.pdfObjectKey || '',

      originalName:
        cert.pdfName || '',

      size:
        Number(cert.pdfSize||0),

      extraction,

      clientValidation:{
        safe:true,
        problems:[],
        warnings:[]
      }
    },

    vendorOverrides:{
      ...extraction
    },

    savedCertificate:
      cert
  };
}


function openSavedCertificateEvidence(
  certificateId
){

  const cert=
    certs.find(
      item=>
        item.id===certificateId
    );


  if(!cert){
    return;
  }


  savedCertificateEvidenceMode=true;
  savedCertificateEvidenceId=
    cert.id;


  const item=
    savedCertificateEvidenceItem();


  if(!item){
    return;
  }


  activeBulkCertificateReviewId=
    item.id;


  bulkCertificateEditMode=false;


  const title=
    $('#bulkCertificateReviewTitle');

  if(title){

    title.textContent=
      cert.student ||
      cert.number ||
      'Certificate';
  }


  const status=
    $('#bulkCertificateReviewStatus');

  if(status){

    status.innerHTML=
      '<strong>Saved certificate</strong>' +
      '<div>This certificate is already recorded in VendorFlow.</div>';
  }


  /*
   * Saved evidence is for checking the record, not importing it.
   */
  const approve=
    $('#approveBulkCertificateReview');

  if(approve){

    approve.classList.add(
      'hidden'
    );
  }


  const edit=
    $('#editBulkCertificateExtraction');

  if(edit){

    edit.classList.remove(
      'hidden'
    );
  }


  const done=
    $('#doneBulkCertificateReview');

  if(done){

    done.classList.remove(
      'hidden'
    );
  }


  renderBulkCertificateReviewFields(
    item
  );


  show(
    $('#bulkCertificateReviewModal')
  );


  loadBulkCertificatePdf(
    item
  );
}


let bulkCertificateEditMode=false;


function activeBulkCertificateItem(){

  if(savedCertificateEvidenceMode){

    return (
      savedCertificateEvidenceItem() ||
      null
    );
  }


  return bulkCertificateItems.find(
    item=>
      item.id===
      activeBulkCertificateReviewId
  ) || null;
}


function bulkCertificateVendorExtraction(
  item
){

  const original=
    bulkCertificateExtraction(item) || {};


  return {
    ...original,
    ...(item?.vendorOverrides || {})
  };
}


function setBulkCertificateEditMode(
  editing
){

  bulkCertificateEditMode=
    Boolean(editing);


  const edit=
    $('#editBulkCertificateExtraction');

  const save=
    $('#saveBulkCertificateCorrections');

  const cancel=
    $('#cancelBulkCertificateCorrections');

  const restore=
    $('#restoreBulkCertificateExtraction');


  if(edit){
    edit.classList.toggle(
      'hidden',
      bulkCertificateEditMode
    );
  }


  if(save){
    save.classList.toggle(
      'hidden',
      !bulkCertificateEditMode
    );
  }


  if(cancel){
    cancel.classList.toggle(
      'hidden',
      !bulkCertificateEditMode
    );
  }


  if(restore){

    const item=
      activeBulkCertificateItem();

    restore.classList.toggle(
      'hidden',
      savedCertificateEvidenceMode ||
      !bulkCertificateEditMode ||
      !item?.vendorEdited
    );
  }
}


function updateBulkVendorEditNotice(
  item
){

  const notice=
    $('#bulkCertificateVendorEditNotice');

  if(!notice){
    return;
  }


  notice.classList.toggle(
    'hidden',
    !item?.vendorEdited
  );
}


function bulkCertificateReviewDisplayValue(
  value
){

  if(
    value===undefined ||
    value===null ||
    String(value).trim()===''
  ){
    return 'Not found';
  }

  return String(value);
}



function renderBulkCharterMatchSuggestions(
  item
){

  const readiness=
    bulkCertificateImportReadiness(
      item,
      {
        automatic:false
      }
    );


  if(readiness.charter){
    return '';
  }


  const candidates=
    readiness.charterResolution
      ?.candidates || [];


  if(!candidates.length){
    return '';
  }


  return `
    <div class="vf-bulk-charter-suggestions">

      <strong>
        Which saved charter school is this?
      </strong>

      <div class="vf-bulk-charter-suggestion-help">
        VendorFlow found a close match. Choose it once and
        VendorFlow will remember it for future certificates.
      </div>

      <div class="vf-bulk-charter-suggestion-buttons">

        ${candidates
          .map(
            charter=>`
              <button
                type="button"
                class="vf-bulk-charter-suggestion"
                data-bulk-charter-match="${esc(charter.id)}">

                ${esc(charter.name || 'Saved charter')}

              </button>
            `
          )
          .join('')
        }

      </div>

    </div>
  `;
}


function wireBulkCharterMatchSuggestions(){

  $$('[data-bulk-charter-match]')
    .forEach(
      button=>{

        button.onclick=
          async ()=>{

            const item=
              activeBulkCertificateItem();

            if(!item){
              return;
            }


            const charter=
              charterSchools.find(
                candidate=>
                  candidate.id===
                  button.dataset.bulkCharterMatch
              );


            if(!charter){
              return;
            }


            const x=
              bulkCertificateVendorExtraction(
                item
              );


            const extractedName=
              String(
                x.charterSchool ||
                x.charterSchoolName ||
                x.schoolName ||
                x.school ||
                ''
              ).trim();


            item.vendorOverrides={
              ...(item.vendorOverrides || {}),

              charterSchool:
                charter.name
            };


            item.vendorApproved=true;

            item.message=
              `Matched to ${charter.name}.`;


            if(item.result){

              item.result.extraction={
                ...(item.result.extraction || {}),

                charterSchool:
                  charter.name
              };
            }


            if(extractedName){

              await rememberCharterAlias(
                charter,
                extractedName
              );
            }


            renderBulkCertificateReviewFields(
              item
            );

            renderBulkCertificateItems();

            wireBulkCharterMatchSuggestions();
          };
      }
    );
}


/*
 * The certificate viewer used to ask the vendor to TYPE the student's
 * name here, which is the one place a typo silently detaches a
 * certificate from its student -- and the case that prompted this was
 * a child whose certificate says "Maverick" while the roster says
 * "Ryder". A dropdown makes it a multiple-choice question instead.
 * The free-text box survives behind a "not on my roster" option, so a
 * certificate for a child who has not been added yet is not blocked.
 */
function vfCertificateStudentMatch(name){

  const target=normalizedName(name);

  if(!target){
    return null;
  }

  return students.find(
    student=>vfStudentAllNames(student).includes(target)
  ) || null;
}


function vfCertificateStudentOptions(currentName){

  const match=
    vfCertificateStudentMatch(currentName);

  return [...students]
    .sort(
      (a,b)=>
        String(a.studentName||'')
          .localeCompare(String(b.studentName||''))
    )
    .map(student=>
      `<option value="${esc(student.studentName||'')}" ${
        match && student.id===match.id ? 'selected' : ''
      }>${esc(student.studentName||'Unnamed student')}${
        vfStudentIsArchived(student) ? ' (archived)' : ''
      }</option>`
    )
    .join('');
}


/*
 * When the vendor's pick differs from the name actually printed on
 * the certificate, say so plainly. That difference is the whole
 * problem this screen exists to resolve, so it should be visible
 * rather than something the vendor has to notice for themselves.
 */
function vfCertificateOriginalStudentNote(item,currentName){

  const original=
    String(
      (bulkCertificateExtraction(item) || {}).studentName || ''
    ).trim();

  if(
    !original ||
    normalizedName(original)===normalizedName(currentName)
  ){
    return '';
  }

  return `<small class="vf-cert-read-note">The certificate reads &ldquo;${
    esc(original)
  }&rdquo;.</small>`;
}


function vfWireCertificateStudentPicker(currentName){

  const select=
    $('#bulkCertificateReviewFields select[data-bulk-edit="studentName"]');

  const other=
    $('#bulkCertificateOtherStudent');

  if(!select || !other){
    return;
  }

  const otherOption=
    select.querySelector('option[value="__vf_other__"]');

  /*
   * A name VendorFlow read off the PDF that matches nobody on the
   * roster starts in the free-text box, so it is never silently
   * discarded just because there is no matching student yet.
   */
  const unmatched=
    Boolean(
      String(currentName||'').trim() &&
      !vfCertificateStudentMatch(currentName)
    );

  const syncOther=()=>{

    const typed=other.value.trim();

    if(otherOption){
      otherOption.value=typed || '__vf_other__';
      otherOption.textContent=
        typed
          ? `${typed} (not on my roster)`
          : 'Someone not on my roster (type a name)';
    }

    select.value=typed || '__vf_other__';
  };

  if(unmatched){
    show(other);
    syncOther();
  }

  select.onchange=()=>{

    if(select.value==='__vf_other__'){
      show(other);
      other.focus();
      return;
    }

    hide(other);
    other.value='';

    if(otherOption){
      otherOption.value='__vf_other__';
      otherOption.textContent=
        'Someone not on my roster (type a name)';
    }
  };

  other.oninput=syncOther;
}


