/*
 * Checklist state follows the ACCOUNT, not the browser.
 *
 * This used to live only in localStorage, on the reasoning that it
 * was "a UI preference, not vendor data". That held while a vendor
 * used one computer. It is not a preference -- which steps you have
 * done, skipped or dismissed is progress, and opening the account on
 * a second computer showed a checklist that had forgotten all of it.
 *
 * Firestore is now the source of truth (profile.setupChecklist), with
 * localStorage kept as a same-browser mirror so the panel still
 * renders instantly on load and keeps working offline. Nothing here
 * touches anything financial -- that part of the original reasoning
 * was right and still holds.
 */
function vfSetupStorageKey(){
  return user && user.uid
    ? `vf-setup-checklist-${user.uid}`
    : 'vf-setup-checklist';
}


function vfSetupNormalizeState(parsed){

  const source=parsed||{};

  return {
    removed:Boolean(source.removed),
    snoozed:Boolean(source.snoozed),
    minimized:Boolean(source.minimized),
    openItem:source.openItem||'',
    skipped:source.skipped||{},
    visited:source.visited||{}
  };
}


function vfSetupLocalState(){

  try{

    const raw=
      localStorage.getItem(vfSetupStorageKey());

    return vfSetupNormalizeState(
      raw ? JSON.parse(raw) : {}
    );

  }catch{

    return vfSetupNormalizeState(null);
  }
}


function vfSetupState(){

  /*
   * The account's copy wins whenever it exists, so a second computer
   * shows the same checklist. Before a vendor has ever saved one,
   * fall back to whatever this browser remembers -- that is what
   * carries existing progress forward instead of resetting it.
   */
  if(profile && profile.setupChecklist){
    return vfSetupNormalizeState(profile.setupChecklist);
  }

  return vfSetupLocalState();
}


function vfSetupSaveState(changes){

  const next=
    vfSetupNormalizeState({
      ...vfSetupState(),
      ...changes
    });

  /* Local first, so the panel never waits on the network. */
  try{

    localStorage.setItem(
      vfSetupStorageKey(),
      JSON.stringify(next)
    );

  }catch(error){

    console.error(
      'Could not save your setup checklist locally:',
      error
    );
  }

  if(profile){
    profile.setupChecklist=next;
  }

  if(!user || !user.uid){
    return;
  }

  /*
   * Fire and forget. A checklist tick must never block the click
   * that caused it, and a failed write is not worth interrupting a
   * vendor over -- the local copy still has it, and the next change
   * will try again.
   */
  setDoc(
    vendorDoc(),
    {setupChecklist:next},
    {merge:true}
  ).catch(error=>{
    console.error(
      'Could not save your setup checklist to your account:',
      error
    );
  });
}


/*
 * One-time lift of an existing browser-only checklist into the
 * account, so a vendor who has been ticking things off on one
 * computer does not lose that the moment this ships.
 */
async function vfSetupMigrateLocalState(){

  if(!user || !user.uid || !profile){
    return;
  }

  if(profile.setupChecklist){
    return;
  }

  const local=vfSetupLocalState();

  const hasSomething=
    local.removed ||
    local.snoozed ||
    local.minimized ||
    Object.keys(local.skipped||{}).length>0 ||
    Object.keys(local.visited||{}).length>0;

  if(!hasSomething){
    return;
  }

  profile.setupChecklist=local;

  try{

    await setDoc(
      vendorDoc(),
      {setupChecklist:local},
      {merge:true}
    );

  }catch(error){

    console.error(
      'Could not move your setup checklist to your account:',
      error
    );
  }
}


function vfSetupVisited(key){
  return Boolean(vfSetupState().visited[key]);
}


function vfSetupItemDone(item){

  if(vfSetupState().skipped[item.key]){
    return true;
  }

  try{
    return Boolean(item.done());
  }catch(error){
    console.error(`Checklist item "${item.key}" could not be checked:`,error);
    return false;
  }
}


function vfSetupProgress(){

  const done=
    VF_SETUP_ITEMS.filter(vfSetupItemDone).length;

  return {
    done,
    total:VF_SETUP_ITEMS.length,
    complete:done===VF_SETUP_ITEMS.length
  };
}


function vfRenderSetupChecklist(){

  const existing=$('#vfSetupChecklist');
  if(existing)existing.remove();

  const app=$('#app');

  if(
    !app ||
    app.classList.contains('hidden') ||
    !user
  ){
    return;
  }

  const state=vfSetupState();

  if(state.removed || state.snoozed){
    return;
  }

  const progress=vfSetupProgress();

  const panel=document.createElement('div');
  panel.id='vfSetupChecklist';
  panel.className=
    `vf-setup-checklist${state.minimized?' vf-setup-min':''}`;

  if(state.minimized){

    panel.innerHTML=`
      <button type="button" id="vfSetupExpand" class="vf-setup-pill">
        Setup Checklist &middot; ${progress.done} of ${progress.total}
      </button>`;

    document.body.appendChild(panel);

    $('#vfSetupExpand').onclick=()=>{
      vfSetupSaveState({minimized:false});
      vfRenderSetupChecklist();
    };

    return;
  }

  panel.innerHTML=`

    <div class="vf-setup-head">
      <div>
        <strong>Setup Checklist</strong>
        <span>${progress.done} of ${progress.total} done</span>
      </div>
      <button type="button" id="vfSetupMinimize" title="Minimize">&minus;</button>
    </div>

    <div class="vf-setup-bar">
      <span style="width:${Math.round((progress.done/progress.total)*100)}%"></span>
    </div>

    <div class="vf-setup-items">
      ${
        VF_SETUP_ITEMS.map(item=>{

          const done=vfSetupItemDone(item);
          const open=state.openItem===item.key;

          return `
            <div class="vf-setup-item${done?' vf-setup-done':''}${open?' vf-setup-open':''}">

              <button type="button" class="vf-setup-row" data-setup-open="${esc(item.key)}">
                <span class="vf-setup-check">${done?'&#10003;':''}</span>
                <span class="vf-setup-title">${esc(item.title)}</span>
              </button>

              ${
                open
                  ? `
                    <div
                      class="vf-setup-body"
                      role="button"
                      tabindex="0"
                      data-setup-go="${esc(item.key)}">
                      ${item.body}
                      <div class="vf-setup-go-line">${esc(item.action)} &rarr;</div>
                      ${
                        item.skippable && !done
                          ? `<button type="button" class="vf-setup-skip" data-setup-skip="${esc(item.key)}">Skip this</button>`
                          : ''
                      }
                    </div>`
                  : ''
              }

            </div>`;
        }).join('')
      }
    </div>

    ${
      progress.complete
        ? `
          <div class="vf-setup-ready">
            <strong>You're ready to let VendorFlow work</strong>
            <p>Nothing has been sent or charged yet. Press
            <strong>Start Automating</strong> in the header when
            you're ready.</p>
          </div>`
        : ''
    }

    <div class="vf-setup-foot">
      <button type="button" id="vfSetupSnooze">Remind me to complete the checklist later</button>
      <button type="button" id="vfSetupRemove">Don't show this again</button>
    </div>`;

  document.body.appendChild(panel);

  $('#vfSetupMinimize').onclick=()=>{
    vfSetupSaveState({minimized:true});
    vfRenderSetupChecklist();
  };

  $('#vfSetupSnooze').onclick=()=>{
    vfSetupSaveState({snoozed:true});
    vfRenderSetupChecklist();
    toast('The checklist will be back next time you sign in.');
  };

  $('#vfSetupRemove').onclick=()=>{

    const sure=
      window.confirm(
        'Remove the setup checklist?\n\n'+
        'It stops appearing on this browser. Use "Remind me to '+
        'complete the checklist later" instead if you just want it '+
        'out of the way for now.'
      );

    if(!sure){
      return;
    }

    vfSetupSaveState({removed:true});
    vfRenderSetupChecklist();
    toast('Checklist removed.');
  };

  panel.querySelectorAll('[data-setup-open]').forEach(button=>{
    button.onclick=()=>{

      const key=button.dataset.setupOpen;

      vfSetupSaveState({
        openItem:state.openItem===key ? '' : key
      });

      vfRenderSetupChecklist();
    };
  });

  panel.querySelectorAll('[data-setup-go]').forEach(button=>{

    /*
     * The whole explanation is the link now, so a keyboard user gets
     * the same thing a mouse user does.
     */
    button.onkeydown=event=>{
      if(event.key==='Enter' || event.key===' '){
        event.preventDefault();
        button.click();
      }
    };

    button.onclick=()=>{

      const item=
        VF_SETUP_ITEMS.find(
          entry=>entry.key===button.dataset.setupGo
        );

      if(!item){
        return;
      }

      /*
       * Visiting is what ticks off the two items that have no single
       * saved field to read -- reading about the email address, and
       * looking at late fees.
       */
      vfSetupSaveState({
        visited:{
          ...vfSetupState().visited,
          [item.key]:true
        },
        minimized:true,
        openItem:''
      });

      switchView(item.view);
      vfRenderSetupChecklist();
    };
  });

  panel.querySelectorAll('[data-setup-skip]').forEach(button=>{
    button.onclick=event=>{

      /*
       * Skip sits inside the clickable explanation, so it has to stop
       * the click reaching it -- otherwise skipping would also
       * navigate away.
       */
      event.stopPropagation();

      vfSetupSaveState({
        skipped:{
          ...vfSetupState().skipped,
          [button.dataset.setupSkip]:true
        },
        openItem:''
      });

      vfRenderSetupChecklist();
    };
  });
}


/*
 * "Remind me later" only hides it for this session, so clearing the
 * snooze on sign-in is what makes it come back next time.
 */
function vfSetupClearSnooze(){
  if(vfSetupState().snoozed){
    vfSetupSaveState({snoozed:false});
  }
}


function vfReopenSetupChecklist(){
  vfSetupSaveState({removed:false,snoozed:false,minimized:false});
  vfRenderSetupChecklist();
}


function vfOpenRealInteractiveTutorial(){
  vfCloseRealInteractiveTutorial();
  vfTutorialStep=0;
  const modal=document.createElement('div');
  modal.id='vfRealTutorial';
  modal.className='vf-real-tutorial';
  modal.innerHTML=`
    <div class="vf-real-tutorial-panel" role="dialog" aria-modal="true" aria-labelledby="vfRealTutorialTitle">
      <div class="vf-real-tutorial-top">
        <div><div class="eyebrow">Interactive Tutorial</div><strong id="vfRealTutorialTitle">How VendorFlow works</strong></div>
        <button id="vfCloseRealTutorial" type="button">Close</button>
      </div>
      <div class="vf-real-tutorial-progress"><span id="vfTutorialProgress"></span></div>
      <div id="vfRealTutorialContent" class="vf-real-tutorial-content"></div>
      <div class="vf-real-tutorial-nav">
        <span id="vfTutorialCount"></span>
        <div><button id="vfTutorialBack" type="button">Back</button><button id="vfTutorialNext" type="button" class="primary">Next</button></div>
      </div>
    </div>`;
  document.body.appendChild(modal);
  $('#vfCloseRealTutorial').onclick=vfCloseRealInteractiveTutorial;
  $('#vfTutorialBack').onclick=()=>{if(vfTutorialStep>0){vfTutorialStep-=1;vfRenderTutorial();}};
  $('#vfTutorialNext').onclick=()=>{
    if(vfTutorialStep<vfTutorialSlides().length-1){vfTutorialStep+=1;vfRenderTutorial();return;}
    vfCloseRealInteractiveTutorial();
    showCenteredActionConfirmation('Tutorial complete. You remain in control of everything VendorFlow does.');
  };
  vfRenderTutorial();
}



/* ==========================================================
   VENDORFLOW GUIDED SETUP WIZARD
   A full-screen overlay that walks a new vendor through loading
   real data into their account -- classes and rosters, certificates,
   and payments -- reusing the exact same VendorFlow screens and
   functions as the regular pages, just relocated into the wizard
   while it's open. Nothing about how those screens save data is
   duplicated or reimplemented here.
   ========================================================== */

const VF_WIZARD_STEPS=['intro','paymentMethods','notifications','classes','certificates','payments','invoicing','finish'];

/*
 * The wizard remembers which step a vendor was on using localStorage,
 * so it can pick back up after a page reload. That key must be scoped
 * to the signed-in account -- otherwise a browser that was previously
 * used to run the wizard for one vendor (or for testing) can make a
 * brand-new vendor's wizard silently start on a later step, including
 * "Setup complete!", skipping the whole thing.
 */
function vfWizardStorageKey(){
  return user&&user.uid
    ? `vf-wizard-step-index-${user.uid}`
    : 'vf-wizard-step-index';
}

let vfWizardStepIndex=Math.max(
  0,
  Math.min(
    VF_WIZARD_STEPS.length-1,
    Number(localStorage.getItem(vfWizardStorageKey())||0)
  )
);

let vfWizardAdoptedNode=null;
let vfWizardAdoptedSlot=null;

const VF_WIZARD_STEP_INFO={
  intro:{
    title:'Before you begin',
    instruction:'',
    viewId:null
  },
  paymentMethods:{
    title:'How families can pay you',
    instruction:'Check every payment method you accept and add your details for each one -- this is what shows up automatically in payment reminder emails.',
    viewId:'paymentMethodsSettings'
  },
  notifications:{
    title:'Default parent notifications',
    instruction:'Choose which emails VendorFlow sends by default every time you create a new class. This only sets the starting point -- you can still turn any of these on or off for a specific class afterward.',
    viewId:'notificationDefaultsSettings'
  },
  classes:{
    title:'Create your classes',
    instruction:'Create each class or service you offer, then upload that class\u2019s student roster as a CSV. Repeat for every class -- you can also duplicate a class you already made and change what\u2019s different. Click Next once every class and roster is loaded.',
    viewId:'classesView'
  },
  certificates:{
    title:'Add certificates you already have',
    instruction:'Upload any certificates you have saved. Don\u2019t have any yet? Skip this step -- you can always add certificates later, by bulk upload or by forwarding the certificate email to VendorFlow.',
    viewId:'certificatesView'
  },
  payments:{
    title:'Add payments you\u2019ve already received',
    instruction:'Upload a bank or Venmo statement and VendorFlow will pull out the payments for you to review. Nothing to add yet? Skip this step -- you can always import statements later.',
    viewId:'paymentsView'
  },
  invoicing:{
    title:'Set up invoice numbering',
    instruction:'Choose how VendorFlow should number your invoices -- let VendorFlow number them automatically, or continue the numbering system you already use. You can change this anytime from the Invoices page.',
    viewId:'invoiceNumberingSettings'
  },
  finish:{
    title:'You\u2019re all set',
    instruction:'',
    viewId:null
  }
};

/*
 * Moves a real page section into the wizard body instead of copying
 * its markup, so every button, upload, and save inside it is the
 * exact same code as the regular page -- nothing here needs to know
 * how classes, certificates, or payments actually get saved.
 */
function vfWizardAdopt(viewId){
  vfWizardRestoreAdopted();

  const node=document.getElementById(viewId);
  if(!node)return null;

  try{

    vfWizardAdoptedNode=node;
    vfWizardAdoptedSlot={parent:node.parentNode,next:node.nextSibling};
    node.classList.add('vf-wizard-adopted');

    $('#vfWizardBody').appendChild(node);

  }catch(error){

    console.error(
      'Could not move this step\'s content into the wizard:',
      error
    );

    vfWizardAdoptedNode=null;
    vfWizardAdoptedSlot=null;

    return null;
  }

  return node;
}

function vfWizardRestoreAdopted(){
  if(vfWizardAdoptedNode && vfWizardAdoptedSlot){

    try{

      if(
        typeof vfWizardRestoreClassCardOrder==='function'
      ){
        vfWizardRestoreClassCardOrder();
      }

      vfWizardAdoptedNode.classList.remove('vf-wizard-adopted');
      vfWizardAdoptedSlot.parent.insertBefore(
        vfWizardAdoptedNode,
        vfWizardAdoptedSlot.next
      );

    }catch(error){

      /*
       * If the spot this card used to live in has since changed (for
       * example, something else on the page re-rendered around it),
       * putting it back exactly where it was can fail. That's fine --
       * the card just stays wherever it currently is instead of
       * disappearing, and this is logged so it's easy to track down
       * if it ever happens again.
       */
      console.error(
        'Could not put this step\'s content back in its normal spot on the page:',
        error
      );
    }
  }
  vfWizardAdoptedNode=null;
  vfWizardAdoptedSlot=null;
}

function vfEnsureWizardShell(){
  if($('#vfWizard'))return;

  const overlay=document.createElement('div');
  overlay.id='vfWizard';
  overlay.className='vf-wizard-overlay';
  overlay.innerHTML=`
    <div class="vf-wizard-card">
      <div class="vf-wizard-head">
        <div class="vf-wizard-progress"><span id="vfWizardProgressFill"></span></div>
        <div class="vf-wizard-head-row">
          <div>
            <div class="eyebrow" id="vfWizardStepLabel"></div>
            <h2 id="vfWizardStepTitle"></h2>
          </div>
          <button type="button" id="vfWizardLater">Run Setup Wizard Later</button>
        </div>
      </div>
      <div class="vf-wizard-instruction-bar">
        <p id="vfWizardStepInstruction" class="vf-wizard-instruction"></p>
      </div>
      <div id="vfWizardBody" class="vf-wizard-body"></div>
      <div id="vfWizardStepPrompt" class="vf-wizard-step-prompt hidden"></div>
      <div class="vf-wizard-foot">
        <button type="button" id="vfWizardBack">Back</button>
        <button type="button" id="vfWizardSkip">Skip this step</button>
        <button type="button" id="vfWizardNext" class="primary">Next</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);

  $('#vfWizardLater').onclick=vfCloseWizard;
  $('#vfWizardBack').onclick=()=>vfWizardGo(vfWizardStepIndex-1);
  $('#vfWizardSkip').onclick=()=>vfWizardGo(vfWizardStepIndex+1);
  $('#vfWizardNext').onclick=()=>vfWizardGo(vfWizardStepIndex+1);
}

function vfRenderWizardStep(){
  vfEnsureWizardShell();

  const stepId=VF_WIZARD_STEPS[vfWizardStepIndex];
  const info=VF_WIZARD_STEP_INFO[stepId];

  $('#vfWizardProgressFill').style.width=
    `${((vfWizardStepIndex+1)/VF_WIZARD_STEPS.length)*100}%`;
  $('#vfWizardStepLabel').textContent=
    `Step ${questions.length+vfWizardStepIndex+1} of ${questions.length+VF_WIZARD_STEPS.length}`;
  $('#vfWizardStepTitle').textContent=info.title;
  $('#vfWizardStepInstruction').textContent=info.instruction;

  $('#vfWizardBack').disabled=vfWizardStepIndex===0;

  vfWizardStopPolling();
  vfWizardHideStepPrompt();
  vfWizardCertPromptShown=false;
  vfWizardPaymentPromptShown=false;

  const body=$('#vfWizardBody');

  if(stepId==='intro'){
    vfWizardRestoreAdopted();
    body.innerHTML=`
      <div class="vf-wizard-intro">
        <p>
          You can bulk-upload your rosters, certificates already saved
          on your computer, and payment statements (bank or Venmo) --
          this saves time later. The same bulk upload tools are also
          available in VendorFlow after the setup wizard is complete,
          so there's no need to do it all right now.
        </p>
        <p>
          Don\u2019t have those handy? Skip ahead and add them anytime.
        </p>
        <p>
          You can also add or update certificates, rosters, and
          payments simply by forwarding the relevant email to
          VendorFlow -- for example, forward a charter school\u2019s
          certificate email and VendorFlow reads it and attaches it to
          the right student automatically.
        </p>
      </div>`;
    $('#vfWizardSkip').classList.add('hidden');
    $('#vfWizardNext').classList.remove('hidden');
    $('#vfWizardNext').disabled=false;
    $('#vfWizardNext').textContent='Next';
  }else if(stepId==='finish'){
    vfWizardRestoreAdopted();
    body.innerHTML=`
      <div class="vf-wizard-finish">
        <h3>Setup complete!</h3>
        <p>Your classes, certificates, and payments are loaded. VendorFlow is ready to use.</p>
        <p><strong>One more step:</strong> VendorFlow won't send anything automatically yet. Click the <strong>Ready?</strong> button in the header whenever you're truly done setting up -- that's what turns on payment reminders, past-due notices, invoice generation, and certificate-received emails.</p>
        <p class="vf-wizard-finish-next-step">
          Your next step is probably to forward any relevant emails to
          VendorFlow. You\u2019ll find your VendorFlow email address on
          your account page, under your name in the top right corner.
        </p>
        <div class="vf-wizard-finish-actions">
          <button type="button" id="vfWizardWatchTutorial" class="primary">Watch a quick tutorial</button>
          <button type="button" id="vfWizardGoHome" class="vf-secondary-button">Go to home page</button>
        </div>
      </div>`;
    $('#vfWizardSkip').classList.add('hidden');
    $('#vfWizardNext').classList.add('hidden');

    $('#vfWizardWatchTutorial').onclick=()=>{
      vfCompleteWizard();
      vfCloseWizardOverlay();
      vfOpenRealInteractiveTutorial();
    };
    $('#vfWizardGoHome').onclick=()=>{
      vfCompleteWizard();
      vfCloseWizardOverlay();
      switchView('review');
    };
  }else{
    $('#vfWizardSkip').classList.remove('hidden');
    $('#vfWizardNext').classList.remove('hidden');
    $('#vfWizardNext').textContent='Next';
    body.innerHTML='';

    const vfAdoptedStepNode=vfWizardAdopt(info.viewId);

    if(!vfAdoptedStepNode){
      body.innerHTML=`
        <div class="vf-wizard-intro">
          <p>
            This step didn\u2019t load correctly. Click Back and then
            forward to this step again, or refresh the page and
            reopen the wizard from the button in the header.
          </p>
        </div>`;
    }

    $('#vfWizardNext').disabled=!vfWizardStepUnlocked[stepId];

    if(stepId==='classes'){
      if(!vfWizardClassesStarted){
        vfWizardClassesStarted=true;
        vfWizardStartClassesFlow();
      }
    }else if(stepId==='certificates' || stepId==='payments'){
      vfWizardStartPolling(stepId);
    }
  }
}

function vfWizardGo(index){
  if(index<0)return;
  vfWizardStepIndex=Math.max(0,Math.min(VF_WIZARD_STEPS.length-1,index));
  localStorage.setItem(vfWizardStorageKey(),vfWizardStepIndex);
  vfRenderWizardStep();
}

function vfOpenWizard(){
  vfWizardStepUnlocked={paymentMethods:false,notifications:false,classes:false,certificates:false,payments:false,invoicing:false};
  vfWizardClassesStarted=false;
  vfWizardCertBatchEverRan=false;
  // Re-sync to this account's own saved progress, not whichever
  // account last used this browser.
  vfWizardStepIndex=Math.max(
    0,
    Math.min(
      VF_WIZARD_STEPS.length-1,
      Number(localStorage.getItem(vfWizardStorageKey())||0)
    )
  );
  document.body.classList.add('vf-wizard-open');
  vfRenderWizardStep();
}

function vfCloseWizardOverlay(){
  vfWizardStopPolling();
  vfWizardRestoreAdopted();
  $('#vfWizard')?.remove();
  document.body.classList.remove('vf-wizard-open');
}

function vfCloseWizard(){
  vfCloseWizardOverlay();
  vfRenderWizardNudge();
  vfRenderReadySetupButton();
}

async function vfCompleteWizard(){
  try{
    await setDoc(
      vendorDoc(),
      {betaWizardCompleted:true,betaWizardCompletedAt:serverTimestamp()},
      {merge:true}
    );
    profile.betaWizardCompleted=true;
    await log(
      'Vendor setup completed',
      `${profile.businessName||'This vendor'} finished the guided VendorFlow setup.`,
      'Onboarding'
    );

    /*
     * Finishing the wizard no longer turns automation on by itself.
     * The vendor does that explicitly with the "Ready?" button once
     * they've actually double-checked everything -- see
     * installVfReadyModal(). This refresh just brings the rest of
     * the UI (wizard nudge, etc.) up to date.
     */
    await refreshAll();
  }catch(error){
    console.error('Could not save setup completion:',error);
  }
  localStorage.removeItem(vfWizardStorageKey());
  vfRenderWizardNudge();
  vfRenderReadySetupButton();
}

/*
 * The one lasting reminder that setup isn't finished: a small button
 * in the header, present on every screen, until the wizard is
 * completed or the vendor explicitly dismisses it. It never pops
 * anything open on its own -- only a click opens the wizard.
 */
function vfRenderWizardNudge(){
  localStorage.removeItem('vf-preview-setup-step');
  localStorage.removeItem('vf-preview-setup-skipped');

  const existing=$('#vfWizardNudge');
  if(existing)existing.remove();

  /*
   * Retired. The setup checklist floats over every page and is
   * visible on its own, so a second reminder in the header was just
   * clutter. The function is left intact -- it now only cleans up
   * any nudge left over from a previous build. Bringing the button
   * back is deleting this one return.
   *
   * The way back to a checklist the vendor removed is the "Show
   * setup checklist" button on Account & Settings.
   */
  return;

  if(profile?.betaWizardCompleted===true)return;
  if(profile?.betaWizardDismissed===true)return;

  /*
   * Backward compatibility: any account that finished its wizard
   * before betaWizardCompleted existed only ever got
   * betaSetupComplete:true written (the old, single-flag system).
   * Treat that as "wizard done" too, so those accounts don't see
   * the nudge reappear after this split.
   */
  if(profile?.betaSetupComplete===true)return;

  if($('#vfWizard'))return;

  const app=$('#app');
  if(!app || app.classList.contains('hidden'))return;

  const host=$('.vf-header-account');
  if(!host)return;

  const nudge=document.createElement('div');
  nudge.id='vfWizardNudge';
  nudge.className='vf-wizard-nudge';
  nudge.innerHTML=`
    <button type="button" id="vfWizardNudgeOpen">Setup Checklist</button>
    <button type="button" id="vfWizardNudgeDismiss" title="Dismiss">&times;</button>`;
  host.insertAdjacentElement('beforebegin',nudge);

  $('#vfWizardNudgeOpen').onclick=()=>{
    if(typeof vfReopenSetupChecklist==='function'){
      vfReopenSetupChecklist();
    }
  };
  $('#vfWizardNudgeDismiss').onclick=async()=>{
    nudge.remove();
    try{
      /*
       * Dismissing the nudge means "I'm not going to finish the
       * guided wizard" -- it stops the setup reminder, but it does
       * NOT turn automation on. That's a separate, deliberate
       * decision the vendor makes with the "Ready?" button, so
       * dismissing this while still mid-import doesn't trigger a
       * sudden wave of emails and reminders nobody asked for yet.
       */
      await setDoc(
        vendorDoc(),
        {
          betaWizardDismissed:true
        },
        {merge:true}
      );
      profile.betaWizardDismissed=true;

      await refreshAll();
      vfRenderReadySetupButton();
    }catch(error){
      console.error('Could not save wizard dismissal:',error);
    }
  };
}

/*
 * A second, separate signal from finishing the wizard: an explicit
 * "yes, actually start automating" button. Finishing (or dismissing)
 * the wizard only means setup is done -- it does NOT by itself queue
 * parent emails, invoice generation, or payment reminders anymore.
 * Those stay held back (see queuePaymentReminderReviews /
 * queueCertificateReceivedEmail, both gated on betaSetupComplete)
 * until the vendor deliberately clicks this.
 */
function vfRenderReadySetupButton(){
  const existing=$('#vfReadyNudge');
  if(existing)existing.remove();

  if($('#vfWizard'))return;

  const app=$('#app');
  if(!app || app.classList.contains('hidden'))return;

  const host=$('.vf-header-account');
  if(!host)return;

  const nudge=document.createElement('div');
  nudge.id='vfReadyNudge';
  nudge.className='vf-ready-nudge';
  /*
   * This used to disappear the moment automation was switched on,
   * which left no indication anywhere that VendorFlow had started
   * emailing families and charging late fees on its own. It now
   * stays put and reports the state, and doubles as the way to pause
   * automation again.
   */
  const automationOn=
    profile?.betaSetupComplete===true;

  nudge.innerHTML=`
    <button type="button" id="vfReadyNudgeOpen"${automationOn?' class="vf-automation-on"':''}>${
      automationOn ? 'Automation on' : 'Start Automating'
    }</button>`;
  host.insertAdjacentElement('beforebegin',nudge);

  $('#vfReadyNudgeOpen').onclick=async()=>{

    if(!automationOn){
      const modal=$('#vfReadyModal');
      if(modal)show(modal);
      return;
    }

    const pause=
      window.confirm(
        `Pause automation?\n\n`+
        `VendorFlow will stop charging late fees, generating invoices `+
        `and emailing families on its own. Nothing already recorded `+
        `changes, and anything waiting for your approval stays in `+
        `Notifications. You can switch it back on here at any time.`
      );

    if(!pause){
      return;
    }

    await setDoc(
      vendorDoc(),
      {
        betaSetupComplete:false,
        updatedAt:serverTimestamp()
      },
      {merge:true}
    );

    await log(
      'Automation paused',
      'The vendor paused VendorFlow automation from the header.',
      'Manual'
    );

    await refreshAll();
    vfRenderReadySetupButton();

    toast('Automation paused.');
  };
}

/*
 * Wires up the "Ready?" popup itself. The modal markup lives
 * statically in index.html (same pattern as the other vf-modal-*
 * popups) since its content never varies, so this just needs to
 * run once at load time.
 */
function installVfReadyModal(){
  const modal=$('#vfReadyModal');
  const close=$('#closeVfReadyModal');
  const confirmBtn=$('#vfReadyConfirmBtn');

  if(!modal)return;

  const closeModal=()=>hide(modal);

  if(close){
    close.onclick=closeModal;
  }

  modal.onclick=event=>{
    if(event.target===modal){
      closeModal();
    }
  };

  if(confirmBtn){

    const defaultLabel=confirmBtn.textContent;

    confirmBtn.onclick=async()=>{

      confirmBtn.disabled=true;
      confirmBtn.textContent='One sec…';

      try{

        await setDoc(
          vendorDoc(),
          {
            betaSetupComplete:true,
            betaSetupCompletedAt:serverTimestamp()
          },
          {merge:true}
        );

        profile.betaSetupComplete=true;

        await log(
          'Vendor marked ready for automation',
          `${profile.businessName||'This vendor'} told VendorFlow to start sending parent emails, invoices, and payment reminders.`,
          'Onboarding'
        );

        closeModal();

        await refreshAll();

        vfRenderReadySetupButton();

        toast('VendorFlow is on it -- automation is live.');

      }catch(error){

        console.error('Could not save ready confirmation:',error);

        toast('Something went wrong -- try again.');

      }finally{

        confirmBtn.disabled=false;
        confirmBtn.textContent=defaultLabel;
      }
    };
  }
}

installVfReadyModal();

let vfWizardStepUnlocked={paymentMethods:false,notifications:false,classes:false,certificates:false,payments:false,invoicing:false};
let vfWizardClassesStarted=false;
let vfWizardPollTimer=null;
let vfWizardCertPromptShown=false;
let vfWizardPaymentPromptShown=false;
let vfWizardCertBatchEverRan=false;

function vfWizardShowStepPrompt(html){
  const el=$('#vfWizardStepPrompt');
  if(!el)return;
  el.innerHTML=html;
  el.classList.remove('hidden');
}

function vfWizardHideStepPrompt(){
  const el=$('#vfWizardStepPrompt');
  if(!el)return;
  el.classList.add('hidden');
  el.innerHTML='';
}

function vfWizardUnlock(stepId){
  vfWizardStepUnlocked[stepId]=true;
  if(VF_WIZARD_STEPS[vfWizardStepIndex]===stepId){
    $('#vfWizardNext').disabled=false;
  }
}

function vfWizardStopPolling(){
  if(vfWizardPollTimer){
    clearInterval(vfWizardPollTimer);
    vfWizardPollTimer=null;
  }
}

function vfWizardStartPolling(stepId){
  vfWizardStopPolling();
  if(stepId==='certificates'){
    vfWizardPollTimer=setInterval(vfWizardPollCertificatesLoop,900);
    vfWizardPollCertificatesLoop();
  }else if(stepId==='payments'){
    vfWizardPollTimer=setInterval(vfWizardPollPaymentsLoop,900);
    vfWizardPollPaymentsLoop();
  }
}

/*
 * Watches the real certificate-upload state (the same array the
 * Certificates page itself uses) and, once every selected file has
 * either been approved, edited-and-approved, denied, or failed --
 * nothing left mid-read or awaiting a decision -- offers to either
 * upload more or move on. Next stays locked until the vendor
 * explicitly answers that prompt at least once.
 */
function vfWizardPollCertificatesLoop(){
  if(typeof bulkCertificateItems==='undefined')return;

  const items=bulkCertificateItems||[];
  const pending=items.some(
    item=>item.state==='reading' || item.state==='ready' || item.state==='review'
  );

  if((items.length || vfWizardCertBatchEverRan) && !pending){
    if(!vfWizardCertPromptShown){
      vfWizardCertPromptShown=true;
      vfWizardShowStepPrompt(`
        <p>Would you like to upload any more certificates?</p>
        <div class="vf-wizard-step-prompt-actions">
          <button type="button" id="vfWizardCertAddMore" class="vf-secondary-button">Yes, add more</button>
          <button type="button" id="vfWizardCertContinue" class="primary">Go to next step</button>
        </div>`);
      $('#vfWizardCertAddMore').onclick=()=>{
        vfWizardCertPromptShown=false;
        vfWizardHideStepPrompt();
        $('#chooseBulkCertificates')?.click();
      };
      $('#vfWizardCertContinue').onclick=()=>{
        vfWizardUnlock('certificates');
        vfWizardGo(vfWizardStepIndex+1);
      };
    }
  }else{
    vfWizardCertPromptShown=false;
    vfWizardHideStepPrompt();
  }
}

/*
 * Same idea for payment statements: once an import has actually
 * finished (VendorFlow's own status line says so), offer to upload
 * another statement or move on.
 */
function vfWizardPollPaymentsLoop(){
  const status=$('#paymentStatementStatus');
  const done=Boolean(
    status &&
    /Statement import finished/.test(status.textContent||'')
  );

  if(done){
    if(!vfWizardPaymentPromptShown){
      vfWizardPaymentPromptShown=true;
      vfWizardShowStepPrompt(`
        <p>Would you like to upload another statement?</p>
        <div class="vf-wizard-step-prompt-actions">
          <button type="button" id="vfWizardPaymentAddMore" class="vf-secondary-button">Yes, add another</button>
          <button type="button" id="vfWizardPaymentContinue" class="primary">Go to next step</button>
        </div>`);
      $('#vfWizardPaymentAddMore').onclick=()=>{
        vfWizardPaymentPromptShown=false;
        vfWizardHideStepPrompt();
        if($('#paymentStatementFile'))$('#paymentStatementFile').value='';
        if(status)status.textContent='';
        $('#paymentStatementFile')?.scrollIntoView({behavior:'smooth',block:'center'});
      };
      $('#vfWizardPaymentContinue').onclick=()=>{
        vfWizardUnlock('payments');
        vfWizardGo(vfWizardStepIndex+1);
      };
    }
  }else{
    vfWizardPaymentPromptShown=false;
    vfWizardHideStepPrompt();
  }
}

/*
 * The classes step is guided rather than just adopted as-is: it
 * opens straight into the real create-class form so there's no
 * "+ Create a new class" button to hunt for, then chains into
 * uploading that class's roster and asking about the next one.
 */
let vfClassCardsReordered=false;

/*
 * A brand-new vendor has no classes yet, so leading with "Choose a
 * class" (an empty dropdown) makes no sense during setup. Move the
 * "Create a new class" card above it for the duration of the wizard
 * only -- vfWizardRestoreClassCardOrder() puts it back for the
 * regular Class Rosters page, where picking an existing class first
 * is the more common everyday action.
 */
function vfWizardReorderClassCards(){
  const chooseCard=$('#chooseClassCard');
  const createCard=$('#classCreateFormWrap');

  if(
    chooseCard &&
    createCard &&
    chooseCard.parentNode===createCard.parentNode
  ){
    createCard.parentNode.insertBefore(createCard,chooseCard);
    vfClassCardsReordered=true;
  }
}

function vfWizardRestoreClassCardOrder(){
  if(!vfClassCardsReordered)return;

  const chooseCard=$('#chooseClassCard');
  const createCard=$('#classCreateFormWrap');

  if(
    chooseCard &&
    createCard &&
    chooseCard.parentNode===createCard.parentNode
  ){
    chooseCard.parentNode.insertBefore(chooseCard,createCard);
  }

  vfClassCardsReordered=false;
}

function vfWizardStartClassesFlow(){
  resetClassCreateFormFields();
  vfWizardReorderClassCards();
  show($('#classCreateFormWrap'));
  vfWizardShowStepPrompt(`<p>Fill in this class's details below, then click <strong>Save class</strong>.</p>`);
}

function vfWizardAskAnotherClass(){
  vfWizardShowStepPrompt(`
    <p>Would you like to create another class?</p>
    <div class="vf-wizard-step-prompt-actions">
      <button type="button" id="vfWizardAnotherClassNew" class="vf-secondary-button">Yes, create new</button>
      <button type="button" id="vfWizardAnotherClassDup" class="vf-secondary-button">Yes, duplicate a class</button>
      <button type="button" id="vfWizardAnotherClassDone" class="primary">No, I'm done</button>
    </div>`);

  $('#vfWizardAnotherClassNew').onclick=()=>{
    vfWizardStartClassesFlow();
  };
  $('#vfWizardAnotherClassDup').onclick=()=>{
    vfWizardShowStepPrompt(`<p>Choose the class you want to copy from the list above, then click <strong>Duplicate class</strong> on its details card, change whatever's different, and click Save.</p>`);
    $('#classSelect')?.scrollIntoView({behavior:'smooth',block:'center'});
  };
  $('#vfWizardAnotherClassDone').onclick=()=>{
    vfWizardUnlock('classes');
    vfWizardHideStepPrompt();
  };
}


/* VENDORFLOW PREVIEW TASK BASED TUTORIAL */


/*
 * Beta Feedback -- a button/modal pair that lives outside the normal
 * view system (both elements are direct children of body in
 * index.html, not inside #app/#auth/#onboarding), so they show up
 * on every screen regardless of sign-in or setup state, including
 * the login screen and the "please use a desktop" mobile gate. The
 * route it posts to (/beta-feedback/send) is deliberately
 * unauthenticated on the Worker side, for the same reason -- someone
 * stuck before ever signing in should still be able to complain.
 */

let vfBetaFeedbackScreenshots=[];

function vfResetBetaFeedbackScreenshots(){
  vfBetaFeedbackScreenshots=[];
  if($('#betaFeedbackScreenshotPreview')){
    $('#betaFeedbackScreenshotPreview').innerHTML='';
  }
  if($('#betaFeedbackScreenshots')){
    $('#betaFeedbackScreenshots').value='';
  }
}

function vfRenderBetaFeedbackScreenshots(){
  const holder=$('#betaFeedbackScreenshotPreview');
  if(!holder){
    return;
  }
  holder.innerHTML=
    vfBetaFeedbackScreenshots
      .map(
        (shot,index)=>`
          <div class="vf-beta-feedback-thumb">
            <img src="data:${esc(shot.type||'image/png')};base64,${shot.content}" alt="Screenshot">
            <button type="button" data-remove-beta-shot="${index}">&times;</button>
          </div>
        `
      )
      .join('');

  $$('[data-remove-beta-shot]').forEach(button=>{
    button.onclick=()=>{
      const index=Number(button.dataset.removeBetaShot);
      vfBetaFeedbackScreenshots.splice(index,1);
      vfRenderBetaFeedbackScreenshots();
    };
  });
}

function vfOpenBetaFeedback(){

  if($('#betaFeedbackName') && !$('#betaFeedbackName').value && profile?.ownerName){
    $('#betaFeedbackName').value=profile.ownerName;
  }

  if($('#betaFeedbackEmail') && !$('#betaFeedbackEmail').value && user?.email){
    $('#betaFeedbackEmail').value=user.email;
  }

  if($('#betaFeedbackError')){
    hide($('#betaFeedbackError'));
  }

  show($('#vfBetaFeedbackOverlay'));
}

function vfCloseBetaFeedback(){
  hide($('#vfBetaFeedbackOverlay'));
}

if($('#vfBetaFeedbackButton')){
  $('#vfBetaFeedbackButton').onclick=vfOpenBetaFeedback;
}

if($('#closeBetaFeedback')){
  $('#closeBetaFeedback').onclick=vfCloseBetaFeedback;
}

if($('#vfBetaFeedbackOverlay')){
  $('#vfBetaFeedbackOverlay').onclick=event=>{
    if(event.target===$('#vfBetaFeedbackOverlay')){
      vfCloseBetaFeedback();
    }
  };
}

if($('#betaFeedbackScreenshots')){

  $('#betaFeedbackScreenshots').onchange=async event=>{

    const files=
      Array.from(event.target.files||[]);

    const MAX_FILES=5;
    const MAX_BYTES=5*1024*1024;

    for(const file of files){

      if(vfBetaFeedbackScreenshots.length>=MAX_FILES){
        toast(`You can attach up to ${MAX_FILES} screenshots.`);
        break;
      }

      if(!file.type.startsWith('image/')){
        continue;
      }

      if(file.size>MAX_BYTES){
        toast(`${file.name} is too large (5MB max).`);
        continue;
      }

      const base64=
        await new Promise(resolve=>{
          const reader=new FileReader();
          reader.onload=()=>{
            const result=String(reader.result||'');
            resolve(result.slice(result.indexOf(',')+1));
          };
          reader.readAsDataURL(file);
        });

      vfBetaFeedbackScreenshots.push({
        filename:file.name||'screenshot.png',
        type:file.type||'image/png',
        content:base64
      });
    }

    vfRenderBetaFeedbackScreenshots();
    event.target.value='';
  };
}

if($('#submitBetaFeedback')){

  $('#submitBetaFeedback').onclick=async()=>{

    const feedback=
      $('#betaFeedbackText')?.value.trim()||'';

    if(!feedback){
      $('#betaFeedbackError').textContent='Please write some feedback before sending.';
      show($('#betaFeedbackError'));
      return;
    }

    const button=$('#submitBetaFeedback');
    const originalLabel=button.textContent;
    button.disabled=true;
    button.textContent='Sending...';
    hide($('#betaFeedbackError'));

    try{

      const response=
        await fetch(
          `${VENDORFLOW_API}/beta-feedback/send`,
          {
            method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({
              name:$('#betaFeedbackName')?.value.trim()||'',
              phone:$('#betaFeedbackPhone')?.value.trim()||'',
              email:$('#betaFeedbackEmail')?.value.trim()||'',
              feedback,
              screenshots:
                vfBetaFeedbackScreenshots.map(
                  shot=>({filename:shot.filename,content:shot.content})
                )
            })
          }
        );

      let data={};
      try{
        data=await response.json();
      }catch(error){
        data={};
      }

      if(!response.ok){
        throw new Error(data?.error||'Something went wrong sending your feedback.');
      }

      $('#betaFeedbackText').value='';
      $('#betaFeedbackPhone').value='';
      vfResetBetaFeedbackScreenshots();
      vfCloseBetaFeedback();
      toast('Feedback sent -- thank you!');

    }catch(error){

      $('#betaFeedbackError').textContent=
        error.message||'Something went wrong sending your feedback. Please try again.';
      show($('#betaFeedbackError'));

    }finally{

      button.disabled=false;
      button.textContent=originalLabel;
    }
  };
}
